			t.Fatalf("Contexts = %+v, want exactly one workspace-repo-root context", insp.FetchPlan.Contexts)
		}
		if insp.FetchPlan.Contexts[0].Effect == nil {
			t.Fatal("expected a measured Effect before any fetch runs")
		}
	})
}

