func captureRun(t *testing.T, fn func() error) (string, error) {
	t.Helper()
	var err error
	out := captureStdout(t, func() { err = fn() })
	return out, err
}

func TestCheckoutSyncModes_ScopedPlanExcludesUnselected(t *testing.T) {
	dir, fp := checkoutModeFixture(t)
