	if got := gitSHA(t, dir, "feat-b"); got != bBefore {
		t.Fatalf("an unselected branch moved: %s -> %s", bBefore, got)
	}
	tx, err := internal.LoadCheckoutTransaction(fp)
	if err == nil && tx != nil {
		t.Fatal("a completed transaction must be deleted")
	}
}

