			[]internal.StackEntry{{Name: "feat-root", Base: "main"}, {Name: "other", Base: "feat-root", Repo: "/elsewhere"}},
			`stack entry "other" belongs to repository "/elsewhere"; checkout sync is single-repository (cross-repo-unsupported)`,
		},
		{
			"I13",
