	if err := internal.ContinueCheckoutSync(opts); err != nil {
		t.Fatalf("continue after switch interruption failed: %v", err)
	}

	// Should be complete
	if internal.HasCheckoutTransaction(fp) {
		t.Error("should be clean after continue")
