	stdout, stderr, exit := runPriorBinary(t, prior.path, f.repo, "sync", f.feature)
	if exit == 0 {
		t.Fatalf("a prior release must refuse a v3 payload it cannot decode; stdout=%q stderr=%q", stdout, stderr)
