		path := filepath.Join(dir, e.Name())
		if err := os.WriteFile(path, []byte("dirty\n"), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	t.Fatalf("no tracked file to dirty in %s", dir)
}

