// captureStderr swaps os.Stderr for an os.Pipe around fn. runWithFilteredStderr
// writes through fmt.Fprintln(os.Stderr, ...) at call time, so the swap is
// observable.
func captureStderr(t *testing.T, fn func()) string {
	t.Helper()
	old := os.Stderr
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stderr = w
	done := make(chan string, 1)
	go func() {
		data, _ := io.ReadAll(r)
		done <- string(data)
	}()
	fn()
	os.Stderr = old
	_ = w.Close()
	out := <-done
	_ = r.Close()
	return out
}

// TestRunDirClean_StderrFilter pins the three behaviours of the shipped filter
// exactly as they are: hint/advice removal, the duplicate-commit reformat, and
// verbatim (untrimmed) forwarding of everything else. Blank lines are dropped.
func TestRunDirClean_StderrFilter(t *testing.T) {
	dir := t.TempDir()
	script := strings.Join([]string{
		`printf 'hint: this is advice\n' 1>&2`,
		`printf 'Disable this message with something\n' 1>&2`,
		`printf 'warning: skipped previously applied commit deadbee\n' 1>&2`,
		`printf '\n' 1>&2`,
		`printf '   \n' 1>&2`,
		`printf '  indented real error\n' 1>&2`,
		`printf 'plain real error\n' 1>&2`,
	}, "; ")

	out := captureStderr(t, func() {
		if err := RunDirClean(dir, "sh", "-c", script); err != nil {
			t.Fatalf("RunDirClean: %v", err)
		}
	})

	if strings.Contains(out, "hint: this is advice") {
		t.Fatalf("hint: lines must be dropped:\n%s", out)
	}
	if strings.Contains(out, "Disable this message") {
		t.Fatalf("advice lines must be dropped:\n%s", out)
	}
	if strings.Contains(out, "skipped previously applied commit") {
		t.Fatalf("the duplicate-commit line must be reformatted:\n%s", out)
	}
	if !strings.Contains(out, "    (skipped duplicate commit)\n") {
		t.Fatalf("expected the reformatted duplicate-commit line:\n%s", out)
	}
	// Non-matching lines are forwarded UNTRIMMED, leading whitespace included.
	if !strings.Contains(out, "  indented real error\n") {
		t.Fatalf("non-matching lines must be forwarded untrimmed:\n%q", out)
	}
	if !strings.Contains(out, "plain real error\n") {
		t.Fatalf("real errors must survive the filter:\n%s", out)
	}
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		if strings.TrimSpace(line) == "" {
			t.Fatalf("blank lines must be dropped, got %q in:\n%q", line, out)
		}
	}
}

func TestRunDirClean_PropagatesExitStatus(t *testing.T) {
	dir := t.TempDir()
	out := captureStderr(t, func() {
		if err := RunDirClean(dir, "sh", "-c", "printf 'boom\\n' 1>&2; exit 3"); err == nil {
			t.Fatal("a non-zero child must produce an error")
		}
	})
	if !strings.Contains(out, "boom") {
		t.Fatalf("the failing child's stderr must reach the user:\n%s", out)
	}
}

// captureStdoutAndStderr swaps both os.Stdout and os.Stderr for os.Pipes
// around fn and returns each stream's captured bytes independently, mirroring
// captureStderr above but for functions (like RunDir/RunDirTo called with
// os.Stdout/os.Stderr) that write to both process-global streams at once.
func captureStdoutAndStderr(t *testing.T, fn func()) (stdout string, stderr string) {
	t.Helper()
	oldOut, oldErr := os.Stdout, os.Stderr

	outR, outW, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	errR, errW, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout, os.Stderr = outW, errW

	doneOut := make(chan string, 1)
	doneErr := make(chan string, 1)
	go func() {
		data, _ := io.ReadAll(outR)
		doneOut <- string(data)
	}()
	go func() {
		data, _ := io.ReadAll(errR)
		doneErr <- string(data)
	}()

	fn()

	os.Stdout, os.Stderr = oldOut, oldErr
	_ = outW.Close()
	_ = errW.Close()
	stdout = <-doneOut
	stderr = <-doneErr
	_ = outR.Close()
	_ = errR.Close()
	return stdout, stderr
}

// TestRunDirTo proves RunDirTo, called with os.Stdout/os.Stderr exactly as
// RunDir hard-wires them internally, is observationally identical to RunDir
// (same captured stdout, same captured stderr, same error/exit-status
// behaviour for both a successful and a failing child) — and, separately,
// that RunDirTo's two writers are honoured independently: stdout content
// never leaks into the stderr writer or vice versa, and a caller-supplied
// pair of writers that are NOT os.Stdout/os.Stderr (plain *bytes.Buffer
// values) is exactly where the child's two streams land.
func TestRunDirTo(t *testing.T) {
	dir := t.TempDir()
	script := "printf 'out-line\\n'; printf 'err-line\\n' 1>&2"

	t.Run("observationally identical to RunDir on success", func(t *testing.T) {
		viaRunDirOut, viaRunDirErr := captureStdoutAndStderr(t, func() {
			if err := RunDir(dir, "sh", "-c", script); err != nil {
				t.Fatalf("RunDir: %v", err)
			}
		})
		viaRunDirToOut, viaRunDirToErr := captureStdoutAndStderr(t, func() {
			if err := RunDirTo(os.Stdout, os.Stderr, dir, "sh", "-c", script); err != nil {
				t.Fatalf("RunDirTo: %v", err)
			}
		})
		if viaRunDirOut != viaRunDirToOut {
			t.Errorf("stdout differs: RunDir=%q RunDirTo(os.Stdout,os.Stderr,...)=%q", viaRunDirOut, viaRunDirToOut)
		}
		if viaRunDirErr != viaRunDirToErr {
			t.Errorf("stderr differs: RunDir=%q RunDirTo(os.Stdout,os.Stderr,...)=%q", viaRunDirErr, viaRunDirToErr)
		}
		if viaRunDirOut != "out-line\n" || viaRunDirErr != "err-line\n" {
			t.Fatalf("test fixture assumption broken: stdout=%q stderr=%q", viaRunDirOut, viaRunDirErr)
		}
	})

	t.Run("observationally identical to RunDir on exit-status propagation", func(t *testing.T) {
		failScript := "printf 'boom\\n' 1>&2; exit 5"
		var runDirErr, runDirToErr error
		captureStdoutAndStderr(t, func() { runDirErr = RunDir(dir, "sh", "-c", failScript) })
		captureStdoutAndStderr(t, func() { runDirToErr = RunDirTo(os.Stdout, os.Stderr, dir, "sh", "-c", failScript) })
		if runDirErr == nil || runDirToErr == nil {
			t.Fatalf("both must report the non-zero exit: RunDir err=%v RunDirTo err=%v", runDirErr, runDirToErr)
		}
		if runDirErr.Error() != runDirToErr.Error() {
			t.Errorf("error text differs: RunDir=%q RunDirTo=%q", runDirErr.Error(), runDirToErr.Error())
		}
	})

	t.Run("both writers honoured independently", func(t *testing.T) {
		var stdoutBuf, stderrBuf bytes.Buffer
		if err := RunDirTo(&stdoutBuf, &stderrBuf, dir, "sh", "-c", script); err != nil {
			t.Fatalf("RunDirTo: %v", err)
		}
		if got := stdoutBuf.String(); got != "out-line\n" {
			t.Errorf("stdout writer = %q, want exactly \"out-line\\n\" (no stderr content must leak in)", got)
		}
		if got := stderrBuf.String(); got != "err-line\n" {
			t.Errorf("stderr writer = %q, want exactly \"err-line\\n\" (no stdout content must leak in)", got)
		}
	})

	t.Run("dir argument is honoured", func(t *testing.T) {
		resolved, err := filepath.EvalSymlinks(dir)
		if err != nil {
			t.Fatalf("EvalSymlinks(%q): %v", dir, err)
		}
		var stdoutBuf, stderrBuf bytes.Buffer
		if err := RunDirTo(&stdoutBuf, &stderrBuf, dir, "pwd"); err != nil {
			t.Fatalf("RunDirTo pwd: %v", err)
		}
		gotDir, err := filepath.EvalSymlinks(strings.TrimSpace(stdoutBuf.String()))
		if err != nil {
			t.Fatalf("EvalSymlinks(%q): %v", stdoutBuf.String(), err)
		}
		if gotDir != resolved {
			t.Errorf("RunDirTo ran in %q, want %q", gotDir, resolved)
		}
	})
}

package internal

import (
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// ============================================================================
// GitVersion and the locked §16 rule 2 parser
// ============================================================================

// GitVersion is the locked §16 rule 2 probe result. Probed is always true
// once ProbeGitVersion has run — the act of asking is itself the fact — and
// OK is true only when a version could be parsed from the first line of
// `git --version`. Raw is that first line, verbatim, kept so a rank 5.9
// probe-failed detail can quote exactly what the host printed even when
// parsing fails.
type GitVersion struct {
	Probed bool
	OK     bool
	Raw    string
	Major  int
	Minor  int
	Patch  int
}

// gitVersionPattern is the locked parser. Git's own first line has always
// been "git version X.Y[.Z]" followed by an arbitrary packager suffix on the
// same line — "git version 2.39.5 (Apple Git-154)", "2.30.1.windows.1", a
// Debian/Homebrew build tag, or nothing at all. Only the leading numeric
// major.minor[.patch] token is consumed; anything after it is intentionally
// left unmatched rather than rejected, so a real host is never misclassified
// as unparseable merely because its packager appended free text.
var gitVersionPattern = regexp.MustCompile(`^git version (\d+)\.(\d+)(?:\.(\d+))?`)

// ProbeGitVersion runs `git --version` once and applies the locked parser to
// its first line. An exec failure or an unparseable first line both yield
// Probed: true, OK: false, every Major/Minor/Patch left at zero — the caller
// (§16 rule 1) is the one that raises the document-level rank 5.9
// probe-failed blocker and treats every capability gate as unknown; this
// function only reports what it observed and never performs that
// classification itself.
func ProbeGitVersion() (GitVersion, error) {
	out, err := exec.Command("git", "--version").Output()
	if err != nil {
		return GitVersion{Probed: true, OK: false}, err
	}

	text := string(out)
	if idx := strings.IndexByte(text, '\n'); idx >= 0 {
		text = text[:idx]
	}
	raw := strings.TrimRight(text, "\r")

	v := GitVersion{Probed: true, Raw: raw}
	m := gitVersionPattern.FindStringSubmatch(raw)
	if m == nil {
		return v, nil
	}

	major, majErr := strconv.Atoi(m[1])
	minor, minErr := strconv.Atoi(m[2])
	if majErr != nil || minErr != nil {
		// Unreachable for the pattern's own \d+ groups, but guarded anyway so
		// a malformed match can never silently masquerade as OK: true.
		return v, nil
	}
	patch := 0
	if m[3] != "" {
		if p, patchErr := strconv.Atoi(m[3]); patchErr == nil {
			patch = p
		}
	}

	v.OK = true
	v.Major = major
	v.Minor = minor
	v.Patch = patch
	return v, nil
}

// ============================================================================
// GitCapabilities — the closed §16 rule 3 six-gate table
// ============================================================================

// GitCapabilities is the closed §16 rule 3 six-gate table, one bool per gate,
// each named for the Git version at which this feature's own behaviour
// changes. An unknown GitVersion (Probed && !OK) yields every gate false via
// GitCapabilitiesForVersion; a caller MUST read that as "unknown", never as
// "absent on this host" — §16 rule 1 already raises the document-level rank
// 5.9 probe-failed blocker in that case, so no gate here is ever consulted
// for a real decision once that blocker has fired.
type GitCapabilities struct {
	// CapPruneTags is `fetch --prune-tags`, Git >= 2.17.
	CapPruneTags bool

	// CapConfigShowScope is `git config --list --show-scope`, Git >= 2.26.
	// Below this gate — or with an unknown version — the plan/guard route
	// cannot tell a key's scope apart from its value at all, so it refuses
	// with rank 5.9 probe-failed rather than publish a scope-less inventory
	// as though it were scoped, and rather than silently drop
	// config_issues[].source (§11.7).
	CapConfigShowScope bool

	// CapDefaultBackendMerge is Git >= 2.26, the version at which
	// rebase.backend — and the merge-backed default effective_backend row 3-5
	// model when it is set or absent — first exists. Kept as its own field,
	// never collapsed with CapConfigShowScope even though both gate at 2.26,
	// because the two have opposite consequences: one refuses the
	// invocation outright, the other only changes how an older host's
	// built-in apply-backend default is modelled (§16 rule 3a).
	CapDefaultBackendMerge bool

	// CapSoleRemoteFallback is Git's own "exactly one configured remote"
	// rung of the remote-resolution ladder (§11.4), Git >= 2.37.
	CapSoleRemoteFallback bool

	// CapRebaseUpdateRefs is `git rebase --update-refs`, Git >= 2.38. Its
	// predicate is argv-derived (§16 rule 3b): a row is gated on it only
	// where the argv THAT ROW publishes actually carries --update-refs, so a
	// host below this gate cannot run that specific argv at all and the
	// controlled route refuses with rank 5.9 probe-failed above any
	// effective_backend classification of it.
	CapRebaseUpdateRefs bool

	// CapFetchAll is `fetch.all`, Git >= 2.44.
	CapFetchAll bool
}

// atLeast reports whether v is a known version at or above major.minor.
// Patch is deliberately excluded: none of the six §16 gates are patch-level,
// so comparing it would let a distro's backport patch release
// (2.25.<huge>, say) masquerade as meeting a minor-level gate it does not.
func (v GitVersion) atLeast(major, minor int) bool {
	if !v.OK {
		return false
	}
	if v.Major != major {
		return v.Major > major
	}
	return v.Minor >= minor
}

// GitCapabilitiesForVersion derives the six §16 rule 3 gates from a probed
// GitVersion. An unknown version (Probed && !OK, or Probed: false) yields the
// zero value — every gate false — which callers must read as "unknown", not
// "confirmed absent".
func GitCapabilitiesForVersion(v GitVersion) GitCapabilities {
	return GitCapabilities{
		CapPruneTags:           v.atLeast(2, 17),
		CapConfigShowScope:     v.atLeast(2, 26),
		CapDefaultBackendMerge: v.atLeast(2, 26),
		CapSoleRemoteFallback:  v.atLeast(2, 37),
		CapRebaseUpdateRefs:    v.atLeast(2, 38),
		CapFetchAll:            v.atLeast(2, 44),
	}
}

// ProbeGitCapabilities composes ProbeGitVersion and GitCapabilitiesForVersion,
// the one call a controlled route needs to obtain both the raw probe (for its
// own rank 5.9 probe-failed detail, §16 rule 1) and the derived gate table in
// a single step.
func ProbeGitCapabilities() (GitCapabilities, GitVersion, error) {
	v, err := ProbeGitVersion()
	return GitCapabilitiesForVersion(v), v, err
}

package internal

import (
	"os"
	"path/filepath"
	"testing"
)

// ============================================================================
// git_capability_test.go — TestGitCapability*
//
// The locked §16 rule 2 version parser over real-world version strings,
// ProbeGitVersion's Probed/OK semantics (successful probe, exec failure,
// unparseable output), and the six independent §16 rule 3 capability gates
// at their exact boundaries (2.17, 2.26, 2.26, 2.37, 2.38, 2.44).
// ============================================================================

// ---------------------------------------------------------------------------
// The locked parser (gitVersionPattern), exercised directly against
// real-world `git --version` first lines without shelling out — this is the
// pure-function half of "the locked parser over real-world version strings".
// ---------------------------------------------------------------------------

func TestGitCapability_VersionPatternRealWorldStrings(t *testing.T) {
	cases := []struct {
		name      string
		raw       string
		wantMatch bool
		wantMajor int
		wantMinor int
		wantPatch int
	}{
		{name: "macOS Xcode packager suffix", raw: "git version 2.39.5 (Apple Git-154)", wantMatch: true, wantMajor: 2, wantMinor: 39, wantPatch: 5},
		{name: "plain three-component", raw: "git version 2.43.0", wantMatch: true, wantMajor: 2, wantMinor: 43, wantPatch: 0},
		{name: "Git-for-Windows four-component", raw: "git version 2.30.1.windows.1", wantMatch: true, wantMajor: 2, wantMinor: 30, wantPatch: 1},
		{name: "minor-only, no patch component", raw: "git version 2.17", wantMatch: true, wantMajor: 2, wantMinor: 17, wantPatch: 0},
		{name: "Debian packager suffix", raw: "git version 2.30.2", wantMatch: true, wantMajor: 2, wantMinor: 30, wantPatch: 2},
		{name: "release-candidate patch suffix", raw: "git version 3.0.0-rc1", wantMatch: true, wantMajor: 3, wantMinor: 0, wantPatch: 0},
		{name: "future major version", raw: "git version 3.1.4", wantMatch: true, wantMajor: 3, wantMinor: 1, wantPatch: 4},
		{name: "empty string", raw: "", wantMatch: false},
		{name: "wrong case", raw: "GIT VERSION 2.30.0", wantMatch: false},
		{name: "non-numeric version", raw: "git version abc.def", wantMatch: false},
		{name: "unrelated program", raw: "some other program 2.3.4", wantMatch: false},
		{name: "missing minor component", raw: "git version 2", wantMatch: false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m := gitVersionPattern.FindStringSubmatch(tc.raw)
			if tc.wantMatch != (m != nil) {
				t.Fatalf("gitVersionPattern.FindStringSubmatch(%q) match = %v, want %v", tc.raw, m != nil, tc.wantMatch)
			}
			if !tc.wantMatch {
				return
			}
			gotMajor, gotMinor, gotPatch := parseCapturedVersionGroups(t, m)
			if gotMajor != tc.wantMajor || gotMinor != tc.wantMinor || gotPatch != tc.wantPatch {
				t.Errorf("%q parsed as %d.%d.%d, want %d.%d.%d", tc.raw, gotMajor, gotMinor, gotPatch, tc.wantMajor, tc.wantMinor, tc.wantPatch)
			}
		})
	}
}

// parseCapturedVersionGroups mirrors ProbeGitVersion's own group-to-int
// conversion (major/minor required, patch defaults to 0 when the optional
// third group did not participate), so this test exercises the same
// conversion rule the shipped function applies, not a reinvented one.
func parseCapturedVersionGroups(t *testing.T, m []string) (major, minor, patch int) {
	t.Helper()
	atoi := func(s string) int {
		if s == "" {
			return 0
		}
		n := 0
		for _, r := range s {
			n = n*10 + int(r-'0')
		}
		return n
	}
	return atoi(m[1]), atoi(m[2]), atoi(m[3])
}

// ---------------------------------------------------------------------------
// ProbeGitVersion's Probed/OK semantics, end to end (real exec.Command, no
// regex bypass) — successful real-host probe, exec failure (git not on
// PATH), and unparseable-but-successful output (a shimmed fake git).
// ---------------------------------------------------------------------------

func TestGitCapability_ProbeGitVersion_RealHost(t *testing.T) {
	v, err := ProbeGitVersion()
	if err != nil {
		t.Fatalf("ProbeGitVersion on the real host git: %v", err)
	}
	if !v.Probed {
		t.Error("Probed = false after a successful invocation, want true")
	}
	if !v.OK {
		t.Errorf("OK = false for real host git, want true (Raw=%q)", v.Raw)
	}
	if v.Major < 2 {
		t.Errorf("Major = %d, want >= 2 for any git installation this suite can run against", v.Major)
	}
	wantPrefix := "git version "
	if len(v.Raw) < len(wantPrefix) || v.Raw[:len(wantPrefix)] != wantPrefix {
		t.Errorf("Raw = %q, want it to start with %q", v.Raw, wantPrefix)
	}
}

func TestGitCapability_ProbeGitVersion_ExecFailure(t *testing.T) {
	// An empty PATH directory has no git binary at all: exec.Command itself
	// fails to start the process, which must still yield Probed:true (the
	// act of asking is itself the fact) alongside OK:false and a non-nil
	// error.
	t.Setenv("PATH", t.TempDir())

	v, err := ProbeGitVersion()
	if err == nil {
		t.Fatal("ProbeGitVersion with no git on PATH: want a non-nil error")
	}
	if !v.Probed {
		t.Error("Probed = false after an exec failure, want true")
	}
	if v.OK {
		t.Error("OK = true after an exec failure, want false")
	}
	if v.Major != 0 || v.Minor != 0 || v.Patch != 0 {
		t.Errorf("Major/Minor/Patch = %d/%d/%d after an exec failure, want all zero", v.Major, v.Minor, v.Patch)
	}
}

// installFakeGit points PATH at a directory containing only a `git` shell
// script that prints firstLine (optionally followed by more lines) to
// stdout and exits 0 — a real external process (never a Go-level mock of
// exec.Command), used only to observe ProbeGitVersion's own line-splitting
// and \r-trimming against output the real host's git cannot be made to
// produce on demand (an unparseable line, or a CRLF line ending).
func installFakeGit(t *testing.T, output string) {
	t.Helper()
	binDir := t.TempDir()
	outFile := filepath.Join(binDir, "version-output.txt")
	if err := os.WriteFile(outFile, []byte(output), 0o644); err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\ncat '" + outFile + "'\n"
	if err := os.WriteFile(filepath.Join(binDir, "git"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	// Prepend, never replace: the script's own shebang needs the rest of
	// PATH to resolve `cat`. Only the git *lookup* itself needs binDir to
	// win, which prepending guarantees.
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func TestGitCapability_ProbeGitVersion_UnparseableOutput(t *testing.T) {
	installFakeGit(t, "not a git version string at all\n")

	v, err := ProbeGitVersion()
	if err != nil {
		t.Fatalf("ProbeGitVersion: %v", err)
	}
	if !v.Probed {
		t.Error("Probed = false, want true (the invocation itself succeeded)")
	}
	if v.OK {
		t.Error("OK = true for an unparseable first line, want false")
	}
	if v.Raw != "not a git version string at all" {
		t.Errorf("Raw = %q, want the verbatim (newline-stripped) first line", v.Raw)
	}
	if v.Major != 0 || v.Minor != 0 || v.Patch != 0 {
		t.Errorf("Major/Minor/Patch = %d/%d/%d, want all zero when unparseable", v.Major, v.Minor, v.Patch)
	}
}

func TestGitCapability_ProbeGitVersion_FakeRealWorldStrings(t *testing.T) {
	cases := []struct {
		name      string
		output    string // full fake stdout, CRLF/multi-line included
		wantRaw   string
		wantMajor int
		wantMinor int
		wantPatch int
	}{
		{
			name:      "CRLF line ending is trimmed from Raw",
			output:    "git version 2.40.0\r\n",
			wantRaw:   "git version 2.40.0",
			wantMajor: 2, wantMinor: 40, wantPatch: 0,
		},
		{
			name:      "only the first line is consulted",
			output:    "git version 2.41.0\nsome other trailer line\n",
			wantRaw:   "git version 2.41.0",
			wantMajor: 2, wantMinor: 41, wantPatch: 0,
		},
		{
			name:      "Apple packager suffix survives end to end",
			output:    "git version 2.39.5 (Apple Git-154)\n",
			wantRaw:   "git version 2.39.5 (Apple Git-154)",
			wantMajor: 2, wantMinor: 39, wantPatch: 5,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			installFakeGit(t, tc.output)
			v, err := ProbeGitVersion()
			if err != nil {
				t.Fatalf("ProbeGitVersion: %v", err)
			}
			if !v.Probed || !v.OK {
				t.Fatalf("Probed/OK = %v/%v, want true/true (Raw=%q)", v.Probed, v.OK, v.Raw)
			}
			if v.Raw != tc.wantRaw {
				t.Errorf("Raw = %q, want %q", v.Raw, tc.wantRaw)
			}
			if v.Major != tc.wantMajor || v.Minor != tc.wantMinor || v.Patch != tc.wantPatch {
				t.Errorf("parsed %d.%d.%d, want %d.%d.%d", v.Major, v.Minor, v.Patch, tc.wantMajor, tc.wantMinor, tc.wantPatch)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// The six independent §16 rule 3 gate calculations, at their exact
// major.minor boundaries. Constructed GitVersion values are used directly
// (no exec needed) so every boundary — including ones this host's own
// installed git may not straddle — is covered deterministically.
// ---------------------------------------------------------------------------

func TestGitCapability_GateBoundaries(t *testing.T) {
	below := func(major, minor int) GitVersion {
		return GitVersion{Probed: true, OK: true, Major: major, Minor: minor}
	}

	cases := []struct {
		name string
		v    GitVersion
		gate func(GitCapabilities) bool
		want bool
	}{
		{"prune-tags below 2.17", below(2, 16), func(c GitCapabilities) bool { return c.CapPruneTags }, false},
		{"prune-tags at 2.17", below(2, 17), func(c GitCapabilities) bool { return c.CapPruneTags }, true},

		{"config-show-scope below 2.26", below(2, 25), func(c GitCapabilities) bool { return c.CapConfigShowScope }, false},
		{"config-show-scope at 2.26", below(2, 26), func(c GitCapabilities) bool { return c.CapConfigShowScope }, true},

		{"default-backend-merge below 2.26", below(2, 25), func(c GitCapabilities) bool { return c.CapDefaultBackendMerge }, false},
		{"default-backend-merge at 2.26", below(2, 26), func(c GitCapabilities) bool { return c.CapDefaultBackendMerge }, true},

		{"sole-remote-fallback below 2.37", below(2, 36), func(c GitCapabilities) bool { return c.CapSoleRemoteFallback }, false},
		{"sole-remote-fallback at 2.37", below(2, 37), func(c GitCapabilities) bool { return c.CapSoleRemoteFallback }, true},

		{"rebase-update-refs below 2.38", below(2, 37), func(c GitCapabilities) bool { return c.CapRebaseUpdateRefs }, false},
		{"rebase-update-refs at 2.38", below(2, 38), func(c GitCapabilities) bool { return c.CapRebaseUpdateRefs }, true},

		{"fetch-all below 2.44", below(2, 43), func(c GitCapabilities) bool { return c.CapFetchAll }, false},
		{"fetch-all at 2.44", below(2, 44), func(c GitCapabilities) bool { return c.CapFetchAll }, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := tc.gate(GitCapabilitiesForVersion(tc.v))
			if got != tc.want {
				t.Errorf("gate(%d.%d) = %v, want %v", tc.v.Major, tc.v.Minor, got, tc.want)
			}
		})
	}
}

func TestGitCapability_GateBoundaries_ConfigShowScopeAndDefaultBackendAreIndependentFields(t *testing.T) {
	// Both CapConfigShowScope and CapDefaultBackendMerge gate at the same
	// 2.26 boundary, but the doc comment on GitCapabilities is explicit that
	// they must never be collapsed into a shared field: assert both are
	// present and both actually equal true at 2.26, as two distinct
	// observations, not one.
	caps := GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 26})
	if !caps.CapConfigShowScope {
		t.Error("CapConfigShowScope = false at 2.26, want true")
	}
	if !caps.CapDefaultBackendMerge {
		t.Error("CapDefaultBackendMerge = false at 2.26, want true")
	}
}

func TestGitCapability_GateBoundaries_PatchLevelNeverConsulted(t *testing.T) {
	// atLeast compares major.minor only: a huge patch on a version one minor
	// below a gate's threshold must not let that gate fire (no distro
	// backport can masquerade as meeting a minor-level gate).
	v := GitVersion{Probed: true, OK: true, Major: 2, Minor: 16, Patch: 999}
	if GitCapabilitiesForVersion(v).CapPruneTags {
		t.Errorf("CapPruneTags = true for 2.16.999, want false (patch must never bridge a minor gate)")
	}
}

func TestGitCapability_GateBoundaries_UnknownVersionYieldsAllGatesFalse(t *testing.T) {
	// An unknown version (Probed && !OK, or the zero value) yields every
	// gate false, which callers must read as "unknown", never "confirmed
	// absent" — GitCapabilitiesForVersion itself has no way to encode that
	// distinction, so this test only proves the all-false shape.
	for _, v := range []GitVersion{
		{},                                  // never probed
		{Probed: true, OK: false},           // probed, unparseable
		{Probed: true, OK: false, Major: 9}, // OK false must dominate even if Major/Minor were somehow set
	} {
		caps := GitCapabilitiesForVersion(v)
		if caps != (GitCapabilities{}) {
			t.Errorf("GitCapabilitiesForVersion(%+v) = %+v, want the all-false zero value", v, caps)
		}
	}
}

func TestGitCapability_GateBoundaries_VersionWellAboveAllGates(t *testing.T) {
	caps := GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 3, Minor: 0})
	want := GitCapabilities{
		CapPruneTags:           true,
		CapConfigShowScope:     true,
		CapDefaultBackendMerge: true,
		CapSoleRemoteFallback:  true,
		CapRebaseUpdateRefs:    true,
		CapFetchAll:            true,
	}
	if caps != want {
		t.Errorf("GitCapabilitiesForVersion(3.0) = %+v, want every gate true (%+v)", caps, want)
	}
}

// ---------------------------------------------------------------------------
// ProbeGitCapabilities composes ProbeGitVersion and GitCapabilitiesForVersion.
// ---------------------------------------------------------------------------

func TestGitCapability_ProbeGitCapabilities_ComposesProbeAndDerive(t *testing.T) {
	caps, v, err := ProbeGitCapabilities()
	if err != nil {
		t.Fatalf("ProbeGitCapabilities on the real host git: %v", err)
	}
	if !v.Probed || !v.OK {
		t.Fatalf("ProbeGitCapabilities returned Probed=%v OK=%v for the real host git, want true/true", v.Probed, v.OK)
	}
	want := GitCapabilitiesForVersion(v)
	if caps != want {
		t.Errorf("ProbeGitCapabilities capabilities = %+v, want GitCapabilitiesForVersion(returned version) = %+v", caps, want)
	}
}

package internal

import (
	"encoding/json"
	"path/filepath"
)

// ============================================================================
// Schema version and route constants (§4.1, §13.1)
// ============================================================================

// RebasePlanSchemaVersion is the current, and so far only, RebasePlan.SchemaVersion.
const RebasePlanSchemaVersion = 1

// RouteLegacy and RouteNewMode are the two RebasePlan.Route / RequestedRoute values.
const (
	RouteLegacy  = "legacy"
	RouteNewMode = "new-mode"
)

// ============================================================================
// RebasePlan — the twenty-five top-level document keys (§4.1, §9.1a)
// ============================================================================

// RebasePlan is the document value. Its members are the twenty-five top-level
// keys of §4.1, in that order and no other: this struct IS the source model
// and the JSON projection, so there is no second enumeration to disagree with
// §4.1. The JSON encoder emits keys in this declaration order.
type RebasePlan struct {
	SchemaVersion  int                 `json:"schema_version"` // RebasePlanSchemaVersion == 1
	Route          string              `json:"route"`
	RequestedRoute *string             `json:"requested_route"` // null when equal to Route
	RouteTriggers  []string            `json:"route_triggers"`  // never nil
	Invocation     string              `json:"invocation"`      // "plan-only"
	Workspace      PlanWorkspace       `json:"workspace"`
	Feature        string              `json:"feature"`
	Policy         PlanPolicy          `json:"policy"`
	Intent         PlanIntent          `json:"intent"`
	Push           PlanPush            `json:"push"`
	Restore        PlanRestore         `json:"restore"`
	Fetch          PlanFetch           `json:"fetch"`
	Freshness      string              `json:"freshness"`    // twelve-value enum, §11.3
	Repositories   []PlanRepository    `json:"repositories"` // never nil
	State          PlanState           `json:"state"`
