// one.
const (
	fpEntryName                       uint16 = 1
	fpEntryGitBranch                  uint16 = 2
	fpEntryRepo                       uint16 = 3
	fpEntryExecutionContextID         uint16 = 4 // fixed anchor, §8.2
	fpEntryExecutionContextSource     uint16 = 5
