	}
	_ = entry
}

func fingerprintFixturePlanWithEntry(entry PlanEntry) RebasePlan {
	plan := fingerprintFixturePlan()
	plan.Entries = []PlanEntry{entry}
	return plan
}

package internal

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"reflect"
	"sort"
)

// ============================================================================
// rebase-plan-guard — the plan-guard surface (§3.2, §13.7, §13.7a)
//
// This file is the home of the plan-guard surface: CheckoutPlanGuard,
// PlanFetchRepoResult, PlanFetchOutcome and PlanFetchContext (the carriers
// this feature's checkout/state plumbing already needed); PlanGuardRefusalError,
// PlanWriters, PlanFetchPlan, PlanGateResult, PlanGuardLimits,
// PlanValidationIdentity and PlanStageFact (the additional carriers §9.1a's
// group-5 gap deferred here); and EvaluatePlanGuard, RevalidatePlanGuardEntry,
// the CheckoutPlanInspection* family, InspectCheckoutPlan, PlanCheckoutRebase,
// BuildCheckoutRebasePlan and BuildCheckoutContinuationPlan — the checkout
// plan-only route's own producers and the guard's two evaluators. Nothing in
// this file imports github.com/spf13/cobra or internal/cli (§19.1, §19.2):
// package cli projects its own flag/writer types into the carriers below at
// the call site, never the reverse.
// ============================================================================

// CheckoutPlanGuard is the internal-owned value the checkout executor
// receives for its plan-guard control flags, so no cli type crosses the
// package boundary and internal never imports Cobra (§19.1, §19.2).
type CheckoutPlanGuard struct {
	Plan        bool
	JSON        bool
	MaxPerEntry *int
	MaxTotal    *int
	Approve     string
	Present     map[string]bool

	// PersistedGuarded is NOT a control flag: it is set only by the checkout
	// --continue dispatch, from TransactionGuarded(tx), so a guarded run's
	// persisted limits stay load-bearing on a flagless resume (§13.6 rule 4d).
	// The zero value always leaves it false, and no external route and no
	// fresh run ever sets it.
	PersistedGuarded bool
}

// Armed reports whether this invocation armed something: at least one limit
// is present, or a token was supplied.
func (g CheckoutPlanGuard) Armed() bool {
	return g.MaxPerEntry != nil || g.MaxTotal != nil || g.Approve != ""
}

// Guarded reports whether the guarded route applies: this invocation armed a
// limit or token, or the persisted transaction was already guarded — and this
// is not a plan-only invocation.
func (g CheckoutPlanGuard) Guarded() bool {
	return (g.Armed() || g.PersistedGuarded) && !g.Plan
}

// PlanFetchRepoResult is one fetch context's observed outcome. The
// writer-taking fetch helpers RETURN it — never void, never a bare bool — so
// fetch.repos[] is a record of what happened, not a re-derivation. It has
// exactly these eight fields, one per §4.4a row member.
type PlanFetchRepoResult struct {
	RepoToken         string               // StackEntry.Repo token; "" is a value (§4.4a)
	ContextRoot       string               // the directory the child ran in, or would have
	ContextCommonDir  string               // the PRE-MEASURED --git-common-dir; "" ⇒ null
	ContextSource     string               // worktree | entry-repo | process-cwd | workspace-repo-root
	ContextCandidates []PlanFetchCandidate // NEVER nil; [] when the enumeration produced none
	Effect            *PlanFetchEffect     // enumerated BEFORE the fetch, copied from the context
	Attempted         bool                 // a git fetch child really ran
	OK                bool                 // the child's exit status; meaningful ONLY when Attempted
}

// PlanFetchOutcome is what this invocation's plan-path fetch observed, handed
// to the builder so the document's fetch/freshness facts describe its own
// fetch. One shape serves both modes: checkout produces exactly one row with
// RepoToken "" and ContextSource workspace-repo-root.
type PlanFetchOutcome struct {
	Applies    bool                  // the described route's effective policy fetches at all
	Attempted  bool                  // at least one Repos row has Attempted true
	Suppressed string                // "" or EXACTLY ONE §11.2 cause token
	Repos      []PlanFetchRepoResult // never nil
}

// PlanFetchContext is ONE enumerated fetch context with its measured effect,
// produced BEFORE any network call. It is the only carrier of an effect into
// a fetch and out of it.
type PlanFetchContext struct {
	RepoToken  string               // "" on the checkout route
	Root       string               // the directory the fetch child will run in
	CommonDir  string               // measured --git-common-dir; "" when unmeasurable
	Source     string               // worktree | entry-repo | process-cwd | workspace-repo-root
	Effect     *PlanFetchEffect     // nil exactly when it could not be established
	Candidates []PlanFetchCandidate // the §4.4a disclosure rows for this context
}

// ============================================================================
// PlanGuardRefusalError (§6.4) — the guarded-execution refusal error
// ============================================================================

// PlanGuardRefusalError is the error EvaluatePlanGuard and
// RevalidatePlanGuardEntry return in place of proceeding: a guarded
// invocation's own refusal, carrying no "plan-guard: " prefix in either
// field — the caller's own message framing owns that, never this type.
type PlanGuardRefusalError struct {
	Kind           string // the RefusalKind (or ControlledPathBlocker) token, verbatim
	Detail         string // the human sentence, verbatim; never itself prefixed
	StatePreserved bool   // true once THIS invocation has rebased an entry, or reclaimed a run guard
}

// Error composes exactly "<kind>: [state-preserved: ]<detail>" (§6.4): the
// state-preserved marker is present, in that exact position, iff
// StatePreserved is true, and absent otherwise. Neither branch prepends
// "plan-guard: " — that framing, where wanted, is the caller's own.
func (e *PlanGuardRefusalError) Error() string {
	if e.StatePreserved {
		return fmt.Sprintf("%s: state-preserved: %s", e.Kind, e.Detail)
	}
	return fmt.Sprintf("%s: %s", e.Kind, e.Detail)
}

// ============================================================================
// PlanWriters (§13.7) — the plan-only checkout route's sole writer surface
// ============================================================================

// PlanWriters is PlanCheckoutRebase's only writer parameter: Prose is where a
// fetch's "Fetching ... done/failed" line and any other human-readable, non-
// document prose goes. A plan-only route never writes a document byte to it
// and never touches os.Stdout/os.Stderr directly (§13.7 rule 1); package cli
// decides where Prose is ultimately connected.
type PlanWriters struct {
	Prose io.Writer
}

// ============================================================================
// PlanFetchPlan (§11.1, §11.2, §11.4-§11.6) — the pre-fetch enumeration a
// controlled route resolves, effect and all, before it ever decides to fetch
// ============================================================================

// PlanFetchPlan is the pre-fetch enumeration InspectCheckoutPlan resolves:
// every candidate fetch context and its measured effect, and whether that
// effect itself suppresses the fetch (ranks 5.05/5.06) before any network
// call. Applies is false only where the route cannot reach a fetch decision
// at all (a rows-less document, §11.2 cause 2); Contexts is never nil once
// Applies is true, and is exactly one entry — context_source:
// workspace-repo-root — on every checkout route (§11.1).
type PlanFetchPlan struct {
	Applies    bool
	Contexts   []PlanFetchContext
	Blockers   []PlanBlocker
	Controlled []ControlledPathBlocker
	Suppressed string // "" or one of §11.2's causes 4-6 tokens
}

// ============================================================================
// PlanGateResult (§13.7, §13.7a) — one pre-fetch/pre-mutation gate's verdict
// ============================================================================

// PlanGateResult is one ordered §13.7/§13.7a gate's outcome: ID is a
// caller-local, never-published label for tests and call-site clarity (the
// document itself carries no gate IDs); Applies is false when this gate is
// not on the invocation's own route at all; Failed, meaningful only when
// Applies, is the gate's own verdict; Kind/Entry/Detail describe the
// resulting blocker exactly as §7.1 would publish it (Entry "" for a
// document-level fact); Controlled is never nil and carries every
// controlled-path token this specific gate's failure represents, even where
// the gate's own Kind stays the zero value because the described route never
// reflects the fact as a blocker at all (§4.6's independence rule).
type PlanGateResult struct {
	ID         string
	Applies    bool
	Failed     bool
	Kind       RefusalKind
	Entry      string
	Detail     string
	Controlled []ControlledPathBlocker
}

// ============================================================================
// PlanGuardLimits (§2.17.1) — the effective, already-reconciled guard limits
// ============================================================================

// PlanGuardLimits is RebasePlanRequest.Limits: the effective
// max-replay-per-entry/max-replay-total pair a controlled invocation
// resolved ABOVE BuildRebasePlan (flag vs. persisted-transaction
// reconciliation happens in InspectCheckoutPlan, never in the builder
// itself), in the same {value, origin} shape guard.limits publishes. Both
// members at their zero value ({nil, ""}) is indistinguishable from "no
// limit was ever armed" — buildGuard treats a nil Origin exactly as "none".
type PlanGuardLimits struct {
	PerEntry PlanGuardLimit
	Total    PlanGuardLimit
}

// ============================================================================
// PlanValidationIdentity (§15) — intent.validation's identity inputs
// ============================================================================

// PlanValidationIdentity is RebasePlanRequest.Validation: the test-command
// validation identity §15 requires the document to publish without ever
// publishing the raw command itself. Command is intentionally never a
// RebasePlan member — only Digest, its SHA-256, is; Applies false leaves
// Digest "" and Command is then meaningless (never read by the builder).
type PlanValidationIdentity struct {
	Applies bool
	Command string // NEVER published; Digest is derived from this and published instead
	Source  string
	Digest  string // 64-lower-hex SHA-256 of Command; "" iff !Applies
}

// ValidationDigest computes intent.validation.command_digest's own value —
// the 64-lower-hex SHA-256 of the raw test command — without ever handing
// the command itself back to a caller that might publish it. It is exported
// so package cli can populate PlanValidationIdentity.Digest without either
// side re-implementing SHA-256 hex encoding.
func ValidationDigest(command string) string {
	sum := sha256.Sum256([]byte(command))
	return hex.EncodeToString(sum[:])
}

// ============================================================================
// PlanStageFact (§13.3, §13.7a) — one continuation entry's next-command facts
// ============================================================================

// PlanStageFact is one entries[]-scoped continuation disclosure row: what a
// --continue invocation's own shipped ladder would run next for one still-
// remaining entry, projected (never re-decided) from that ladder. Stage is
// the shipped stage token the entry is paused at; NextCommand is the exact
// argv the shipped continuation would issue next; RebaseIsNext is true when
// that command is itself a rebase (rather than, say, a plain checkout);
// StandaloneCheckout is true when the next command is a bare branch
// checkout with no rebase attached; AutostashApplies is nil where the
// autostash question does not arise for this entry's own next command.
type PlanStageFact struct {
	Entry              string
	Stage              string
	NextCommand        string
	RebaseIsNext       bool
	StandaloneCheckout bool
	AutostashApplies   *bool
}

// ============================================================================
// Checkout fetch-context enumeration (§11.1, §11.4-§11.6) — the single
// workspace-repo-root candidate every controlled checkout route resolves,
// and its own reach for ranks 5.05/5.06, BEFORE any network call.
// ============================================================================

// FetchSuppression is the per-plan suppression verdict of §11.2 causes 4-6:
// the cause token, the controlled-path tokens it publishes and the blockers
// it raises. It is produced by ONE shared ladder — ResolveFetchSuppression —
// so the external and checkout routes cannot diverge on which measured
// effect suppresses a fetch, nor on the exact row shape they publish for it.
type FetchSuppression struct {
	Suppressed string
	Controlled []ControlledPathBlocker
	Blockers   []PlanBlocker
}

// ResolveFetchSuppression is the ONE suppression ladder both modes run over
// an already-enumerated context list, in the fixed rank order 5.0 →
// 5.05 → 5.06 (§11.2 causes 4, 5, 6):
//
//   - cause 4, rank 5.0 fetch-context-indeterminate: two or more enumerated
//     contexts that do not collapse. Contexts collapse only when BOTH the
//     canonical absolute common dir AND the resolved effect agree (§11.4);
//     head_branch is disclosure and is excluded from the predicate. A single
//     candidate never reaches this rank, which is why the checkout route —
//     which resolves exactly one context — can never fire it;
//   - cause 5, rank 5.05 fetch-submodule-reach-indeterminate: unconditional
//     recursion (mode: yes) whose reach could not be bounded, on ANY
//     enumerated context;
//   - cause 6, rank 5.06 fetch-local-branch-checked-out: a positive refspec
//     covering refs/heads/** whose covered local-branch inventory is
//     non-empty or unknown, on ANY enumerated context.
//
// A context whose effect could not be established at all contributes to
// neither 5.05 nor 5.06 — an unmeasurable effect is not a measured hazard —
// but it does take part in the equivalence test of cause 4, where it cannot
// be shown to agree with anything and therefore makes a multi-context plan
// indeterminate, exactly as §11.4 requires ("one that cannot be shown to
// agree").
func ResolveFetchSuppression(contexts []PlanFetchContext) FetchSuppression {
	if len(contexts) == 0 {
		return FetchSuppression{}
	}
	if len(contexts) > 1 && !fetchContextsCollapse(contexts) {
		return FetchSuppression{
			Suppressed: "not-refreshed-context-indeterminate",
			Controlled: []ControlledPathBlocker{ControlledFetchContextIndeterminate},
			Blockers: []PlanBlocker{{
				Kind:   RefusalFetchContextIndeterminate,
				Detail: "the enumerated fetch contexts do not agree on the repository a single fetch would refresh; scope the run with a determinate --only/--from, make the contexts agree on their common dir and resolved effect, or use --no-fetch",
			}},
		}
	}
	for _, ctx := range contexts {
		if ctx.Effect == nil {
			continue
		}
		if fetchSubmoduleReachIndeterminate(*ctx.Effect) {
			return FetchSuppression{
				Suppressed: "not-refreshed-submodule-reach-indeterminate",
				Controlled: []ControlledPathBlocker{ControlledFetchSubmoduleReach},
				Blockers: []PlanBlocker{{
					Kind:   RefusalFetchSubmoduleReach,
					Detail: "unconditional submodule recursion's reach could not be bounded",
				}},
			}
		}
	}
	for _, ctx := range contexts {
		if ctx.Effect == nil {
			continue
		}
		if fetchLocalBranchCheckedOut(ctx.Effect.LocalBranchDestinations) {
			return FetchSuppression{
				Suppressed: "not-refreshed-local-branch-checked-out",
				Controlled: []ControlledPathBlocker{ControlledFetchLocalBranchHeld},
				Blockers: []PlanBlocker{{
					Kind:   RefusalFetchLocalBranchCheckedOut,
					Detail: "the fetch would write a covered refs/heads/** destination a worktree holds, or holds are unknown",
				}},
			}
		}
	}
	return FetchSuppression{}
}

// fetchContextsCollapse is §11.4's context-equivalence predicate: every
// enumerated context must agree on the canonical absolute common dir AND on
// the resolved effect — remotes[] (names, urls, refspecs,
// prune/prune_tags/tag_opt), the local-branch destinations and the submodule
// recursion. head_branch is deliberately excluded: two linked worktrees of
// one common dir sitting on different branches still collapse wherever their
// resolved effect agrees, which is the ordinary stack. A context whose
// common dir or effect could not be measured cannot be shown to agree and
// therefore never collapses.
func fetchContextsCollapse(contexts []PlanFetchContext) bool {
	first := contexts[0]
	if first.CommonDir == "" || first.Effect == nil {
		return false
	}
	for _, ctx := range contexts[1:] {
		if ctx.CommonDir == "" || ctx.Effect == nil {
			return false
		}
		if ctx.CommonDir != first.CommonDir {
			return false
		}
		if !fetchEffectsEquivalent(*first.Effect, *ctx.Effect) {
			return false
		}
	}
	return true
}

// fetchEffectsEquivalent compares exactly the resolved members §11.4 names,
// with head_branch — the one disclosure-only member — excluded.
func fetchEffectsEquivalent(a, b PlanFetchEffect) bool {
	x, y := a, b
	x.HeadBranch, y.HeadBranch = nil, nil
	return reflect.DeepEqual(x, y)
}

// fetchSubmoduleReachIndeterminate is rank 5.05 (§11.5): the fail-closed line
// stays exactly at unconditional recursion (mode: yes) whose reach could not
// be bounded; an on-demand or no-recursion context never refuses here.
func fetchSubmoduleReachIndeterminate(effect PlanFetchEffect) bool {
	return effect.SubmoduleRecursion.Mode == "yes" && effect.SubmoduleRecursion.Reach == "unknown"
}

// fetchLocalBranchCheckedOut is rank 5.06 (§11.6): a positive refspec
// covering refs/heads/** whose covered local-branch inventory is non-empty
// OR unknown. local_branch_destinations.patterns[] is already filtered
// (resolveLocalBranchDestinations/refspecsToPatterns, §11.6) to exactly the
// covering positive refspecs, so a non-empty Patterns list alone establishes
// the "covering refspec" half of the predicate; Branches/Held nil (as
// opposed to non-nil-but-empty) is that function's own "unknown" signal.
func fetchLocalBranchCheckedOut(lbd PlanLocalBranchDestinations) bool {
	if len(lbd.Patterns) == 0 {
		return false
	}
	if lbd.Branches == nil || lbd.Held == nil {
		return true
	}
	return len(lbd.Held) > 0
}

// checkoutFetchPlan enumerates the checkout route's one fetch context — the
// workspace repository root, context_source: workspace-repo-root — and its
// measured fetch effect (head_branch, remotes, refspecs, prune/tag mappings,
// local_branch_destinations including held[], and submodule_recursion
// including its reach) before any fetch runs, so a cause-5/6 document can
// still publish the whole measured row (§11.1). Cause 4
// (fetch-context-indeterminate) can never fire here: checkout resolves
// exactly one candidate, and a single candidate is always trivially equal to
// itself (§11.4), so it is intentionally absent from this function's
// blockers regardless of what the effect turns out to be.
func checkoutFetchPlan(repoDir string, caps GitCapabilities) PlanFetchPlan {
	ctx := PlanFetchContext{
		RepoToken: "",
		Root:      repoDir,
		Source:    "workspace-repo-root",
		Candidates: []PlanFetchCandidate{
			{ContextRoot: repoDir, ContextSource: "workspace-repo-root"},
		},
	}

	_, commonDir, err := MeasureContextRoots(repoDir)
	if err != nil {
		return PlanFetchPlan{Applies: true, Contexts: []PlanFetchContext{ctx}}
	}
	ctx.CommonDir = commonDir

	// §16 rule 3a: below 2.26 the ordered inventory cannot be produced, and
	// the capability gate has already refused this document.
	var inv GitConfigInventory
	if caps.CapConfigShowScope {
		inv = ProbeGitConfigInventory(repoDir)
	}
	// The holder inventory is produced by BuildPlanHolderIndex — the single
	// holder-index producer, keyed by canonical common dir (§14.4 rule 4) —
	// never by a direct BuildBranchHolderInventory call, so checkout's one
	// fetch context can never disagree with the plan's own holder facts
	// about what "one repository" is.
	ids := PlanContextIdentities{commonDir: {ContextID: commonDir, RepoRoot: repoDir, CommonDir: commonDir}}
	holders := BuildPlanHolderIndex(ids, []string{commonDir}).ByContext[commonDir]
	effect := ResolveFetchEffect(inv, repoDir, commonDir, caps, holders)
	ctx.Effect = &effect

	plan := PlanFetchPlan{Applies: true, Contexts: []PlanFetchContext{ctx}}
	sup := ResolveFetchSuppression(plan.Contexts)
	plan.Suppressed, plan.Controlled, plan.Blockers = sup.Suppressed, sup.Controlled, sup.Blockers
	return plan
}

// ============================================================================
// EvaluatePlanGuard (§4.6, §7, §13.7) — the pre-mutation admission verdict
// ============================================================================

// EvaluatePlanGuard is the guarded route's single pre-mutation gate. plan is
// the already-built document — BuildRebasePlan's own guard/approval/refusal
// verdicts, never re-measured here; g is this invocation's own control
// flags, consulted only to make this function a safe no-op when the
// invocation was never guarded at all (g.Guarded() false): there is then no
// admission predicate to enforce and nothing to refuse.
//
// Where the run IS guarded, the admission predicate is §4.6's own: a
// document with a non-nil refusal.kind, or runnable: false, or a non-empty
// guard.execute_blocked_by[] refuses; anything else proceeds. The three
// checks are deliberately independent rather than folded into one boolean:
// refusal.kind already reflects every blockers[] entry INCLUDING every
// guard-introduced rank 7-12 blocker BuildRebasePlan folds in before calling
// SelectPrimaryRefusal, so it is checked first and covers guard.would_refuse
// as a strict subset (a blocker always exists wherever would_refuse is
// true); runnable guards defensively against a document that is somehow not
// runnable for a rank 1-6 reason yet carries no refusal.kind, which
// SelectPrimaryRefusal's own contract never actually produces but this
// function does not trust blindly; and execute_blocked_by[] is checked last
// because §4.6 declares it independent of both — a controlled-path token
// the described route's own blockers/refusal never reflects at all (the
// symlinked-artefact cell) must still refuse a guarded mutation.
func EvaluatePlanGuard(plan RebasePlan, g CheckoutPlanGuard) error {
	if !g.Guarded() {
		return nil
	}
	if plan.Refusal.Kind != nil {
		detail := ""
		if plan.Refusal.Detail != nil {
			detail = *plan.Refusal.Detail
		}
		return &PlanGuardRefusalError{Kind: string(*plan.Refusal.Kind), Detail: detail}
	}
	if !plan.Runnable {
		return &PlanGuardRefusalError{Kind: string(RefusalStateRefused), Detail: "the described run is not runnable"}
	}
	if len(plan.Guard.ExecuteBlockedBy) > 0 {
		token := plan.Guard.ExecuteBlockedBy[0]
		return &PlanGuardRefusalError{
			Kind:   string(controlledPathBlockerKind(token)),
			Detail: controlledPathBlockerDetail(token),
		}
	}
	return nil
}

// controlledPathBlockerKind maps a controlled-path token to the RefusalKind
// §7.1 ranks it at, so the guard seam's marker names the KIND an operator
// reads in the document rather than the token's own spelling. The two
// owner-signalling tokens are the rank-3 `state-refused` pair; the three
// fetch-scoped tokens keep their own kinds.
func controlledPathBlockerKind(token ControlledPathBlocker) RefusalKind {
	switch token {
	case ControlledFetchContextIndeterminate:
		return RefusalFetchContextIndeterminate
	case ControlledFetchLocalBranchHeld:
		return RefusalFetchLocalBranchCheckedOut
	case ControlledFetchSubmoduleReach:
		return RefusalFetchSubmoduleReach
	default:
		return RefusalStateRefused
	}
}

// controlledPathBlockerDetail names, for EvaluatePlanGuard's own refusal
// error, which controlled-path fact a token represents. It is prose for a Go
// error message only — never a document field — so it need not match any
// blockers[].detail sentence verbatim.
func controlledPathBlockerDetail(token ControlledPathBlocker) string {
	switch token {
	case ControlledFetchContextIndeterminate:
		return "the fetch context could not be shown to be unambiguous"
	case ControlledFetchLocalBranchHeld:
		return "the fetch would write a covered refs/heads/** destination a worktree holds, or holds are unknown"
	case ControlledFetchSubmoduleReach:
		return "unconditional submodule recursion's reach could not be bounded"
	case ControlledLiveOwnerConcurrency:
		return "a pre-existing live foreign process owns this feature"
	case ControlledOwnerArtefactUndecodable:
		return "an owner-signalling artefact could not be decoded"
	default:
		return string(token)
	}
}

// ============================================================================
// RevalidatePlanGuardEntry (§10, §11.8) — the JIT re-measurement seam
// ============================================================================

// RevalidatePlanGuardEntryRequest bundles RevalidatePlanGuardEntry's inputs.
type RevalidatePlanGuardEntryRequest struct {
	// Request is the same-subject RebasePlanRequest RevalidatePlanEntry
	// itself requires: a fresh call site rebuilds it exactly as the
	// original plan build did, so this seam re-measures against CURRENT Git
	// state rather than replaying the approved document's own recorded
	// facts.
	Request RebasePlanRequest

	// Approved is the one entries[] row this invocation is immediately
	// about to run a Git command for.
	Approved PlanEntry

	// Limits is the effective guard limits this invocation is bound by.
	Limits PlanGuardLimits

	// ReplayedTotal is the count of candidates THIS invocation has already
	// rebased over, before Approved — the one running total neither the
	// approved document nor a fresh re-probe of Approved alone carries,
	// and the only state max_replay_total's JIT judgement needs beyond
	// what a fresh measurement of Approved itself already yields.
	ReplayedTotal int

	// StatePreserved is supplied truthfully by the caller: true once this
	// invocation has rebased at least one entry, or has reclaimed a run
	// guard, this run — a fact only the mutation loop itself knows.
	StatePreserved bool
}

// PlanGuardRevalidation is RevalidatePlanGuardEntry's typed JIT result. It
// exists because the running `max_replay_total` judgement of §10.3 row 1
// ("a deferred/unknown fact resolves into a count that newly exceeds an
// effective limit") is only correct when the caller accumulates the count
// this seam FRESHLY resolved, not the approved row's own recorded one. An
// `upstream-deferred` row is approved with `replay.candidate_count: null`,
// so a carrier that accumulated the approved value would add 0 for exactly
// the rows the deferral policy exists to re-measure, and a total limit
// strictly between the anchor's count and the run's real multi-row total
// would never fire.
type PlanGuardRevalidation struct {
	// Entry is the freshly re-measured row RevalidatePlanEntry produced —
	// the same value the drift comparison and the limit judgement were
	// made against, exposed so a caller never re-probes to learn it.
	Entry PlanEntry

	// CandidateCount is the freshly resolved replay count for Entry. It is
	// 0 only when Entry.Replay.CandidateCount is genuinely nil (a still-
	// unresolved unknown), which CandidateCountKnown distinguishes from a
	// resolved zero.
	CandidateCount int

	// CandidateCountKnown reports whether the fresh re-measurement resolved
	// a count at all. false means the row is still an unknown at this seam
	// and contributes nothing to the run's replay total.
	CandidateCountKnown bool
}

// RevalidatePlanGuardEntry is the JIT seam evaluator: immediately before
// Approved's own Git command runs, it re-measures Approved's row (via
// RevalidatePlanEntry, base/destination SHA, cutoff, candidate count/digest
// through RevalidationDigest), separately re-verifies the two collateral-
// class members a single-row digest comparison cannot correctly compare
// (§11.8), and judges the freshly re-measured candidate count against the
// effective limits and this run's own prior replay total. It returns the
// freshly resolved count for the caller's own running total, together with
// nil to proceed or a *PlanGuardRefusalError — revalidation-mismatch, or a
// newly-exceeded limit-per-entry/limit-total — with StatePreserved set from
// the request, never invented here.
func RevalidatePlanGuardEntry(req RevalidatePlanGuardEntryRequest) (PlanGuardRevalidation, error) {
	reval, err := RevalidatePlanEntry(req.Request, req.Approved)
	if err != nil {
		// §22.33i (v-e-1): an input the seam could not READ — the unreadable
		// stack.yaml reload of §25.102 input 3 — is rank 5.9 probe-failed
		// before any Git mutation, never a silent proceed and never a rank 9
		// mismatch derived from an unmeasured value.
		return PlanGuardRevalidation{}, &PlanGuardRefusalError{
			Kind:           string(RefusalProbeFailed),
			Detail:         fmt.Sprintf("revalidate entry %s: %v", req.Approved.Name, err),
			StatePreserved: req.StatePreserved,
		}
	}
	result := PlanGuardRevalidation{Entry: reval.Entry}
	if reval.Entry.Replay.CandidateCount != nil {
		result.CandidateCount = *reval.Entry.Replay.CandidateCount
		result.CandidateCountKnown = true
	}

	if reval.Drifted {
		return result, &PlanGuardRefusalError{
			Kind: string(RefusalRevalidationMismatch), Detail: reval.Blocker.Detail,
			StatePreserved: req.StatePreserved,
		}
	}

	// An UNMEASURED input outranks a mismatch derived from it: rank 5.9
	// probe-failed fires before the rank 9 comparison (§22.33i (v-e-1)).
	if reval.ProbeFailed {
		return result, &PlanGuardRefusalError{
			Kind: string(RefusalProbeFailed), Detail: reval.ProbeFailedDetail,
			StatePreserved: req.StatePreserved,
		}
	}

	if drifted, detail := collateralDrifted(req.Approved, reval.Entry); drifted {
		return result, &PlanGuardRefusalError{
			Kind: string(RefusalRevalidationMismatch), Detail: detail,
			StatePreserved: req.StatePreserved,
		}
	}

	if blocker := newlyExceededLimit(reval.Entry, req.Limits, req.ReplayedTotal); blocker != nil {
		return result, &PlanGuardRefusalError{
			Kind: string(blocker.Kind), Detail: blocker.Detail,
			StatePreserved: req.StatePreserved,
		}
	}
	return result, nil
}

// collateralDrifted re-verifies the two collateral-class members a single
// entry re-probe cannot correctly compare through RevalidatePlanEntry's own
// neutralized digest (§11.8, neutralizeRevalidationCollateral's own doc
// comment): CollateralMechanism and CollateralRefs, the set of refs this
// entry's own rebase would replay past. fresh already carries values
// computed by the SAME buildEntries/computeCollateral pass RevalidatePlanEntry
// ran to produce it, so no further Git probing happens here — only the
// comparison against the approved snapshot is this function's job.
// collateral_exposed is deliberately excluded: recomputing it correctly
// needs every STRICTLY EARLIER row of the ORIGINAL run in execution order,
// which neither the approved row nor a fresh re-probe of one entry
// reconstructs, and it is a disclosure member describing a DIFFERENT row's
// hazard, never a safety precondition on THIS entry's own mutation.
func collateralDrifted(approved, fresh PlanEntry) (bool, string) {
	if !stringPtrEqual(approved.CollateralMechanism, fresh.CollateralMechanism) {
		return true, fmt.Sprintf("entry %s's collateral mechanism changed since approval", approved.Name)
	}
	if !collateralRefsEqual(approved.CollateralRefs, fresh.CollateralRefs) {
		return true, fmt.Sprintf("entry %s's collateral refs changed since approval", approved.Name)
	}
	return false, ""
}

func stringPtrEqual(a, b *string) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}

func collateralRefsEqual(a, b []PlanCollateralRef) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// newlyExceededLimit judges the freshly re-measured candidate count against
// the effective limits and this run's own prior replay total — the state
// neither the approved row nor a fresh re-probe alone carries. It returns
// nil when nothing newly exceeds, never re-litigating a limit the approved
// document's own guard.evaluation[] already waived or accepted: a JIT limit
// refusal is by definition about count drift SINCE that evaluation, not a
// re-run of it.
func newlyExceededLimit(fresh PlanEntry, limits PlanGuardLimits, replayedTotal int) *PlanBlocker {
	count := 0
	if fresh.Replay.CandidateCount != nil {
		count = *fresh.Replay.CandidateCount
	}
	if limits.PerEntry.Value != nil && count > *limits.PerEntry.Value {
		name := fresh.Name
		return &PlanBlocker{
			Kind:   RefusalLimitPerEntry,
			Entry:  &name,
			Detail: fmt.Sprintf("%s replays %d candidates (limit %d)", fresh.Name, count, *limits.PerEntry.Value),
		}
	}
	if limits.Total.Value != nil {
		projected := replayedTotal + count
		if projected > *limits.Total.Value {
			return &PlanBlocker{
				Kind:   RefusalLimitTotal,
				Detail: fmt.Sprintf("the run replays %d candidates (limit %d)", projected, *limits.Total.Value),
			}
		}
	}
	return nil
}

// ============================================================================
// CheckoutPlanInspection (§13.7) — the checkout plan-only route's own
// read-only measurement pass, above and separate from BuildRebasePlan
// ============================================================================

// CheckoutPlanInspectionRequest bundles InspectCheckoutPlan's inputs.
type CheckoutPlanInspectionRequest struct {
	Opts CheckoutSyncOpts

	// StateOpts controls the checkout state inspector's liveness seam; the
	// zero value selects the shipped liveness probe and os.Getpid() (§23.1).
	StateOpts CheckoutPlanStateOpts
}

// CheckoutPlanInspection is InspectCheckoutPlan's own result: every fact
// BuildCheckoutRebasePlan/BuildCheckoutContinuationPlan need to construct a
// RebasePlanRequest without re-probing Git state a second time. Fields past
// the first hard error in the ordered sequence below (Stack/Order/Selection)
// stay at their zero value — the caller's own document build still proceeds
// with what was measured, exactly as a document-level StackErr/SortErr/
// SelectionErr already does inside BuildRebasePlan itself.
type CheckoutPlanInspection struct {
	Continue     bool
	Version      GitVersion
	Capabilities GitCapabilities

	State   CheckoutPlanState
	Verdict CheckoutPlanStateVerdict

	Stack    Stack
	StackErr error
	Order    []StackEntry
	SortErr  error

	Selection         SyncSelection
	SelectionResolved bool
	SelectionErr      error

	// PlanEntries is buildCheckoutPlanFrom's own result — the persistable
	// []CheckoutPlanEntry a fresh run would write into a transaction. It is
	// never populated on --continue: a continuation replays the ALREADY-
	// persisted plan, never re-derives one (§13.3).
	PlanEntries  []CheckoutPlanEntry
	PlanBuildErr error

	Remaining      []string
	StageFacts     []PlanStageFact
	BasePreflight  PlanBasePreflight
	FetchPlan      PlanFetchPlan
	Gates          []PlanGateResult
	Limits         PlanGuardLimits
	LimitConflicts []PlanGuardLimitConflict
}

// InspectCheckoutPlan is the checkout route's own §13.7 ordered read-only
// inspection: version/capabilities, state (transaction/lock/worktree/head),
// the fresh-run precondition gates, the stack/order/selection triple, the
// reconciled guard limits, and — fresh-route only — the I14 base preflight
// and the pre-fetch context/effect enumeration. It performs no mutation and
// no network call of its own; checkoutFetchPlan measures a fetch's WOULD-BE
// effect, never runs one.
func InspectCheckoutPlan(req CheckoutPlanInspectionRequest) CheckoutPlanInspection {
	opts := req.Opts
	var insp CheckoutPlanInspection
	insp.Continue = opts.Continue
	insp.Capabilities, insp.Version, _ = ProbeGitCapabilities()
	insp.State, insp.Verdict = InspectCheckoutPlanState(opts, req.StateOpts)
	// §16 rules 3a/3b, at their required position: immediately after the
	// version probe, above the fetch and above every config read. Checkout
	// never passes --update-refs (§11.8), so rule 3b never applies here.
	insp.Gates = append(CapabilityGates(insp.Version, insp.Capabilities, false),
		append(checkoutPreconditionGates(opts), checkoutLockLadderGates(opts, insp.State)...)...)

	tx := insp.State.Files.CheckoutTransaction.Transaction
	insp.Limits = resolveCheckoutGuardLimits(opts.PlanGuard, tx)
	insp.LimitConflicts = resolveCheckoutLimitConflicts(tx, opts.PlanGuard)

	stack, stackErr := LoadStack(opts.FeaturePath)
	if stackErr != nil {
		insp.StackErr = stackErr
		return insp
	}
	insp.Stack = stack

	order, sortErr := TopoSort(stack)
	if sortErr != nil {
		insp.SortErr = sortErr
		return insp
	}
	insp.Order = order

	sel, selErr := ResolveSyncSelectionFromOrder(stack, order, opts.Policy, SyncSelectionOpts{
		Mode:    ModeCheckout,
		NewMode: opts.NewMode,
		Feature: opts.Feature,
	})
	if selErr != nil {
		insp.SelectionErr = selErr
		return insp
	}
	insp.Selection = sel
	insp.SelectionResolved = true

	insp.Remaining = RemainingRebaseEntries(
		checkoutEffectiveRoute(opts, tx),
		RebasePlanLayout{FeaturePath: opts.FeaturePath, RepoRoot: opts.RepoDir},
		RemainingEntriesState{Mode: ModeCheckout, Checkout: insp.State},
		order, sel,
	)

	if opts.Continue {
		insp.StageFacts = checkoutStageFacts(insp.State, insp.Remaining)
		return insp
	}

	// Fresh route only below this point: --continue never re-derives a plan,
	// never re-evaluates I14, and never fetches (§13.3, §11.1).
	planEntries, planErr := buildCheckoutPlanFrom(opts.RepoDir, stack, order, sel)
	if planErr != nil {
		insp.PlanBuildErr = planErr
		return insp
	}
	insp.PlanEntries = planEntries
	insp.BasePreflight = checkoutBasePreflight(opts, stack, sel)

	if opts.Policy.Fetch == SyncFetchEnabled {
		insp.FetchPlan = checkoutFetchPlan(opts.RepoDir, insp.Capabilities)
	}

	return insp
}

// checkoutEffectiveRoute derives this invocation's own effective route
// (§13.6 rule 4): a continuation of an already-persisted transaction
// inherits ITS OWN route (txNewMode, never re-derived from opts.NewMode,
// which a continuation invocation may not even repeat); a fresh run's route
// is opts.NewMode directly.
func checkoutEffectiveRoute(opts CheckoutSyncOpts, tx *CheckoutTransaction) string {
	if opts.Continue && tx != nil {
		if txNewMode(tx) {
			return RouteNewMode
		}
		return RouteLegacy
	}
	if opts.NewMode {
		return RouteNewMode
	}
	return RouteLegacy
}

// checkoutRouteTriggers is RebasePlanRequest.RouteTriggers: the sorted names
// of every Changed trigger flag this invocation actually supplied.
func checkoutRouteTriggers(changed map[string]bool) []string {
	names := make([]string, 0, len(changed))
	for k, v := range changed {
		if v {
			names = append(names, k)
		}
	}
	sort.Strings(names)
	return names
}

// checkoutPushSource and checkoutPushIntent derive intent.push/push_source
// (§4.6, §3's four-member domain minus the external-only persisted-payload
// member): a fresh run's own --push flag is the whole story; a continuation
// of an already new-mode transaction resumes ITS OWN persisted intent; a
// continuation of a legacy transaction still resumes the persisted intent
// (every CheckoutTransaction has always persisted Push, §13.1) but is
// tagged with the legacy-continuation origin token the domain reserves for
// exactly this case.
func checkoutPushSource(opts CheckoutSyncOpts, tx *CheckoutTransaction) string {
	if !opts.Continue {
		return "flag"
	}
	if tx != nil && txNewMode(tx) {
		return "persisted-transaction"
	}
	return "flag-legacy-continuation"
}

func checkoutPushIntent(opts CheckoutSyncOpts, tx *CheckoutTransaction) bool {
	if opts.Continue && tx != nil {
		return tx.Push
	}
	return opts.Push
}

// checkoutBasePreflight is I14 (§10.7 rule 1a): the shipped
// firstUnresolvedCheckoutBase locator, projected into PlanBasePreflight with
// the shipped verifyCheckoutBasesLocally sentence, verbatim. It is called
// only on the fresh route (I14 is evaluated at most once per run, pre-lock,
// and never re-reached on --continue, mirroring RunCheckoutSync's own
// single call site).
func checkoutBasePreflight(opts CheckoutSyncOpts, stack Stack, sel SyncSelection) PlanBasePreflight {
	entry, ref, found := firstUnresolvedCheckoutBase(opts, stack, sel)
	if !found {
		return PlanBasePreflight{Applies: true}
	}
	return PlanBasePreflight{
		Applies: true,
		Failed:  true,
		Entry:   entry,
		Ref:     ref,
		Detail:  fmt.Sprintf("base %q for stack entry %q does not resolve locally; drop --no-fetch or fetch manually first", ref, entry),
	}
}

// CapabilityGates is §16 rules 3a/3b evaluated at the ONE position both
// rules require: immediately after the version probe, ABOVE this route's own
// fetch and above every config read. Each fires as a DOCUMENT-LEVEL
// (entry: null) rank 5.9 `probe-failed` gate — non-waivable, like every
// rank 1-10 fact — so the document is `runnable: false` and the route's
// fetch is suppressed by the same gate ladder every other pre-fetch gate
// uses. There is no per-row variant of either rule.
//
//   - rule 3a, `config --list --show-scope` (2.26): a host below the gate
//     cannot produce the ordered inventory this document's whole
//     repositories[].config surface is derived from, so no row may publish a
//     configuration verdict at all;
//   - rule 3b, `rebase --update-refs` (2.38): argv-DERIVED — it fires only
//     where at least one actual planned argv row of THIS invocation would
//     carry the option, which the caller decides from mode and scope before
//     any row is built (checkout never passes it, §11.8).
//
// An unestablished version (`Version.OK` false) fails both gates: a
// capability that could not be measured is never assumed present.
func CapabilityGates(version GitVersion, caps GitCapabilities, argvNeedsUpdateRefs bool) []PlanGateResult {
	established := version.Probed && version.OK
	showScope := established && caps.CapConfigShowScope
	updateRefs := established && caps.CapRebaseUpdateRefs

	var gates []PlanGateResult
	if !showScope {
		gates = append(gates, PlanGateResult{
			ID: "capability-config-show-scope", Applies: true, Failed: true,
			Kind: RefusalProbeFailed,
			Detail: "git config --list --show-scope requires Git 2.26 or newer; observed " +
				gitVersionLabel(version),
		})
	}
	if argvNeedsUpdateRefs && !updateRefs {
		gates = append(gates, PlanGateResult{
			ID: "capability-rebase-update-refs", Applies: true, Failed: true,
			Kind: RefusalProbeFailed,
			Detail: "this invocation's planned argv carries --update-refs, which requires Git 2.38 or newer; observed " +
				gitVersionLabel(version),
		})
	}
	return gates
}

// gitVersionLabel renders the observed version for a capability gate's own
// detail sentence, naming an unestablished probe honestly rather than
// printing a zero version.
func gitVersionLabel(v GitVersion) string {
	if !v.Probed {
		return "no probe"
	}
	if !v.OK {
		return "an unparseable git --version"
	}
	return fmt.Sprintf("%d.%d", v.Major, v.Minor)
}

// checkoutPreconditionGates evaluates the three fresh-run, pre-lock
// preconditions RunCheckoutSync itself checks before ever touching the
// filesystem for a transaction (§13.7 gates 1-3): no persisted transaction
// may already exist, no other Git operation may be in progress, and the
// working tree must be clean. Detail is the shipped sentence, verbatim, so
// a Gates-derived blockers[] row reads identically to the legacy executor's
// own refusal. All three are silent no-ops on --continue, which has already
// passed them by definition (it owns the transaction and the lock).
func checkoutPreconditionGates(opts CheckoutSyncOpts) []PlanGateResult {
	if opts.Continue {
		return nil
	}
	dirty, _ := gitWorkingTreeDirty(opts.RepoDir) // an unmeasurable tree simply does not fire this gate
	return []PlanGateResult{
		{
			ID: "checkout-transaction-exists", Applies: true, Failed: HasCheckoutTransaction(opts.FeaturePath),
			Kind:   RefusalStateRefused,
			Detail: "checkout sync transaction already exists; use --continue or --abort",
		},
		{
			ID: "checkout-operation-in-progress", Applies: true, Failed: gitOperationInProgress(opts.RepoDir),
			Kind:   RefusalStateRefused,
			Detail: "another Git operation is in progress; complete or abort it before checkout sync",
		},
		{
			ID: "checkout-working-tree-dirty", Applies: true, Failed: dirty,
			Kind:   RefusalStateRefused,
			Detail: "working tree is dirty; commit or stash changes before checkout sync",
		},
	}
}

// checkoutLockLadderGates is §13.7 gate j: the projection of the WHOLE
// native `.checkout-sync.lock` ladder — AcquireCheckoutLock on the fresh arm,
// forceAcquireCheckoutLock on the continuation arm — with each row's own
// SHIPPED sentence reproduced byte for byte, including its operands.
//
// It is a snapshot projection, never a re-decision: it reads only the
// already-measured PlanCheckoutLockFile of §12.5a and never opens the lock
// again. Three classes of native sentence are deliberately NOT projected,
// because they describe write races and future writes rather than snapshot
// facts: `reclaim stale checkout-sync lock: %w`, `reclaim checkout-sync
// lock: %w`, `acquire checkout-sync lock after stale recovery: %w` and
// `create lock directory: %w`.
//
// Two rows of the native ladder are unreachable from here and are therefore
// absent by construction:
//
//   - row 5a, a SELF-PID lock, refuses on the FRESH arm only (its sentence is
//     the initialized-or-invalid one, since a self PID is never "live
//     foreign"); the continuation arm reclaims its own lock and publishes no
//     blocker at all;
//   - row 6, `stale lock from PID %d detected with existing transaction`, is
//     unreachable below gate b: HasCheckoutTransaction is a bare os.Stat
//     evaluated ABOVE the lock, so a dead foreign lock beside a transaction
//     takes gate b's `previous checkout-sync incomplete; use --continue or
//     --abort` sentence instead.
//
// A SYMLINKED lock synthesizes no native sentence at all: the shipped ladder
// reads straight through the link, so only the controlled-path token of
// §12.5 describes it (gateVerdicts owns that), never a blocker here.
func checkoutLockLadderGates(opts CheckoutSyncOpts, state CheckoutPlanState) []PlanGateResult {
	lock := state.Files.CheckoutLock
	if !lock.Applicable {
		return nil
	}
	lockPath := CheckoutLockPath(opts.FeaturePath)
	id := "checkout-lock-ladder"
	fail := func(detail string) []PlanGateResult {
		return []PlanGateResult{{ID: id, Applies: true, Failed: true, Kind: RefusalStateRefused, Detail: detail}}
	}

	switch lock.Presence {
	case PlanPresenceAbsent, PlanPresenceNotApplicable, PlanPresenceSymlink:
		// Absent refuses nothing; a symlink is the controlled-token cell and
		// synthesizes no native sentence.
		return nil
	case PlanPresenceUnreadable:
		reason := UnreadableIOError
		if lock.UnreadableReason != nil {
			reason = *lock.UnreadableReason
		}
		err := lock.Err
		if err == nil {
			// The empty-document row carries no loader error of its own (the
			// emptiness IS the finding), so the projected `%w` operand is the
			// same sentence the shipped decoder produces for a document with
			// no content.
			err = errors.New("EOF")
		}
		switch reason {
		case UnreadableDecodeError, UnreadableEmptyDocument:
			if opts.Continue {
				return fail(fmt.Sprintf("invalid checkout-sync lock %s: %v", lockPath, err))
			}
			return fail(fmt.Sprintf("invalid checkout-sync lock; inspect %s and use --abort to recover: %v", lockPath, err))
		default:
			// io-error and not-a-file (a directory) both take the read arm.
			if opts.Continue {
				return fail(fmt.Sprintf("read checkout-sync lock: %v", err))
			}
			return fail(fmt.Sprintf("read existing checkout-sync lock: %v", err))
		}
	}

	// Readable. The shipped ladder's own order: invalid PID first, then a
	// live holder, then (fresh only) a self-recorded PID, then nothing.
	if lock.Lock == nil {
		return nil
	}
	if lock.Lock.PID <= 0 {
		return fail(fmt.Sprintf("checkout-sync lock is being initialized or is invalid; retry or inspect %s", lockPath))
	}
	if lock.Alive != nil && *lock.Alive {
		if opts.Continue {
			return fail(fmt.Sprintf("lock held by live process %d; cannot reclaim", lock.Lock.PID))
		}
		return fail(fmt.Sprintf("checkout-sync lock held by live process %d (created %s); cannot steal live lock",
			lock.Lock.PID, lock.Lock.Created))
	}
	if lock.Self != nil && *lock.Self && !opts.Continue {
		// Row 5a: writeLockExclusive fails, the PID is this process, so the
		// shipped fresh ladder cannot call it a live FOREIGN holder and takes
		// the initialized-or-invalid arm. The continuation arm reclaims it.
		return fail(fmt.Sprintf("checkout-sync lock is being initialized or is invalid; retry or inspect %s", lockPath))
	}
	// A dead, foreign lock with no transaction relation: the reclaim is
	// projected as succeeding, so no blocker at all.
	return nil
}

// checkoutStageFacts derives StageFacts for the --continue route: one
// disclosure row per Remaining entry projecting (never re-deciding) the
// shipped continuation ladder's own next command for that entry, purely
// from the persisted transaction's own Stage/CurrentIndex/Plan — the same
// inputs resumeTransaction (checkout_sync.go) itself switches on.
// AutostashApplies mirrors autostashApplies' own §18.4 rule exactly
// (rebase_plan_build.go) for the overlapping continuation cases. It is
// deliberately silent on whether a later row's own rebase turns out to be a
// structural no-op — that answer needs this run's own entries[].strategy,
// which does not exist until BuildRebasePlan's buildEntries has run — so
// StandaloneCheckout here is always the complement of RebaseIsNext, a real
// but necessarily coarser signal than a caller already holding entries[]
// could give.
func checkoutStageFacts(state CheckoutPlanState, remaining []string) []PlanStageFact {
	tx := state.Files.CheckoutTransaction.Transaction
	if tx == nil || len(remaining) == 0 {
		return nil
	}
	index := make(map[string]int, len(tx.Plan))
	for i, e := range tx.Plan {
		index[e.Name] = i
	}

	facts := make([]PlanStageFact, 0, len(remaining))
	for _, name := range remaining {
		idx, known := index[name]
		atCurrent := known && idx == tx.CurrentIndex

		fact := PlanStageFact{Entry: name, Stage: string(StagePlanned)}
		rebaseIsNext := true
		autostash := true
		if atCurrent {
			fact.Stage = string(tx.Stage)
			rebaseIsNext = checkoutStageRebasesNext(tx.Stage)
			autostash = checkoutStageAutostashApplies(tx.Stage)
		}

		fact.RebaseIsNext = rebaseIsNext
		fact.StandaloneCheckout = !rebaseIsNext
		fact.NextCommand = "git checkout " + name
		if rebaseIsNext {
			fact.NextCommand = "git rebase"
		}
		fact.AutostashApplies = &autostash
		facts = append(facts, fact)
	}
	return facts
}

// checkoutStageRebasesNext answers whether resumeTransaction's own switch
// over tx.Stage (checkout_sync.go) reaches a NEW git rebase for the
// current-index row before this entry's row is done: true at
// StageSwitched/StagePlanned/StageRebasing (resumeFromSwitched/
// executeTransaction's own rebase step is still ahead) and at StageConflict
// (a rebase --continue-equivalent is the very next Git command, via
// resumeTransaction's own StageConflict arm); false at StageRebased/
// StageValidating/StageRestoring/StageCompleted, where the rebase itself
// already ran and only ancestry/validation/restoration/cleanup remains.
func checkoutStageRebasesNext(stage CheckoutStage) bool {
	switch stage {
	case StageSwitched, StagePlanned, StageRebasing, StageConflict:
		return true
	default:
		return false
	}
}

// checkoutStageAutostashApplies is autostashApplies' own §18.4 continuation
// rule (rebase_plan_build.go), restated here for a row whose only known
// facts are the persisted transaction's stage — never re-decided, just
// evaluated from the same three-stage set.
func checkoutStageAutostashApplies(stage CheckoutStage) bool {
	switch stage {
	case StageSwitched, StagePlanned, StageRebasing:
		return true
	default:
		return false
	}
}

// originLimit is one guard.limits.* member's {value, origin}: the unarmed
// value ({nil, "none"}) whenever v is nil, the supplied origin otherwise.
func originLimit(v *int, origin string) PlanGuardLimit {
	if v == nil {
		return PlanGuardLimit{Value: nil, Origin: "none"}
	}
	return PlanGuardLimit{Value: v, Origin: origin}
}

// resolveCheckoutLimit derives ONE guard.limits.* member per §13.6 rule 4d
// and §3's six-member origin enum: a fresh run (tx nil) has only its own
// supplied flag; a continuation of an ALREADY-guarded transaction keeps
// THAT transaction's own persisted value wherever it armed this specific
// key (the reconciliation rule "persisted value stays effective", §2.17.2),
// falling back to this continuation's own supplied flag, tagged as a
// persisted-continuation arm, only where the persisted transaction never
// armed this key; a continuation of a legacy (not-yet-guarded) transaction
// has no persisted value to defer to at all, so this continuation's own
// supplied flag is the only source, tagged with the upgrade-specific
// origin.
func resolveCheckoutLimit(tx *CheckoutTransaction, guarded bool, persisted, supplied *int) PlanGuardLimit {
	switch {
	case tx == nil:
		return originLimit(supplied, "flags")
	case guarded && persisted != nil:
		return originLimit(persisted, "persisted-transaction")
	case guarded:
		return originLimit(supplied, "flags-persisted-continuation")
	default:
		return originLimit(supplied, "flags-legacy-continuation")
	}
}

// resolveCheckoutGuardLimits is RebasePlanRequest.Limits' own reconciliation
// (§13.2a): the effective, already-reconciled {max_replay_per_entry,
// max_replay_total} pair, never the raw supplied flags alone.
func resolveCheckoutGuardLimits(g CheckoutPlanGuard, tx *CheckoutTransaction) PlanGuardLimits {
	guarded := checkoutRecoveryIsGuarded(tx)
	var perEntryPersisted, totalPersisted *int
	if tx != nil {
		perEntryPersisted, totalPersisted = tx.MaxReplayPerEntry, tx.MaxReplayTotal
	}
	return PlanGuardLimits{
		PerEntry: resolveCheckoutLimit(tx, guarded, perEntryPersisted, g.MaxPerEntry),
		Total:    resolveCheckoutLimit(tx, guarded, totalPersisted, g.MaxTotal),
	}
}

// limitConflict is one guard.limit_conflicts[] row (§2.17.2): a conflict
// exists only where a PERSISTED value already existed at claim time AND
// this continuation supplied a DIFFERENT one — a continuation arming a
// previously-unarmed key is a fresh arm, never a conflict.
func limitConflict(key string, persisted *int, persistedOrigin string, supplied *int) *PlanGuardLimitConflict {
	if supplied == nil || persisted == nil || *supplied == *persisted {
		return nil
	}
	return &PlanGuardLimitConflict{Key: key, EffectiveValue: persisted, EffectiveOrigin: persistedOrigin, SuppliedValue: supplied}
}

// resolveCheckoutLimitConflicts is RebasePlanRequest.LimitConflicts: never
// populated for a fresh run or a continuation of a not-yet-guarded
// transaction, since neither has a persisted armed value to conflict with.
func resolveCheckoutLimitConflicts(tx *CheckoutTransaction, g CheckoutPlanGuard) []PlanGuardLimitConflict {
	if !checkoutRecoveryIsGuarded(tx) {
		return nil
	}
	var out []PlanGuardLimitConflict
	if c := limitConflict("max_replay_per_entry", tx.MaxReplayPerEntry, "persisted-transaction", g.MaxPerEntry); c != nil {
		out = append(out, *c)
	}
	if c := limitConflict("max_replay_total", tx.MaxReplayTotal, "persisted-transaction", g.MaxTotal); c != nil {
		out = append(out, *c)
	}
	return out
}

// checkoutWorkspace is RebasePlan.Workspace: mode/repo_root are always
// available from opts alone; stable_id is best-effort via the same
// workspace-identity subsystem the rest of the tree uses (internal/workspace.go)
// and stays nil rather than refusing the whole plan when it cannot be
// established.
func checkoutWorkspace(opts CheckoutSyncOpts) PlanWorkspace {
	ws := ResolveCurrentWorkspace(opts.RepoDir, LoadConfig())
	var stableID *string
	if ws.StableID != "" {
		id := ws.StableID
		stableID = &id
	}
	return PlanWorkspace{Mode: string(ModeCheckout), StableID: stableID, RepoRoot: opts.RepoDir}
}

// checkoutPushFacts is RebasePlanRequest.PushFacts for the checkout route
// (§14.1a rule 9): checkout is always exactly one repository, so this
// measures exactly one context/remote-facts pair, keyed by the repo token
// PushTargets itself looks up for every checkout-mode entry — "" (§2.8 row
// 1). It is a complete no-op, never touching Git, whenever this invocation
// does not intend to push at all.
func checkoutPushFacts(opts CheckoutSyncOpts, caps GitCapabilities, commonDir string) PlanPushFacts {
	if !opts.Push {
		return PlanPushFacts{}
	}
	// The ONE ordered inventory this push context reads (§14.1a rule 7):
	// both the remote ladder and MeasurePushRemoteFacts consume it.
	var inv GitConfigInventory
	if caps.CapConfigShowScope {
		inv = ProbeGitConfigInventory(opts.RepoDir)
	}
	ctx, identity, remoteName, err := ResolvePushContext(opts.RepoDir, "workspace-repo-root", "materialized", inv, caps)
	if err != nil {
		return PlanPushFacts{Applies: true, Phase: "plan-point"}
	}
	facts := MeasurePushRemoteFacts(ctx.ContextID, commonDir, remoteName, inv, caps)
	return PlanPushFacts{
		Applies:         true,
		Phase:           "plan-point",
		Identities:      PlanContextIdentities{identity.ContextID: identity},
		Contexts:        []PlanPushContext{ctx},
		Materialization: map[string]string{"": ctx.Materialization},
		Remotes:         map[string]PlanPushRemoteFacts{"": facts},
	}
}

// checkoutValidationIdentity is RebasePlanRequest.Validation (§15): checkout
// always freezes its effective test command — the fresh run's own --test
// value, or the persisted transaction's value on --continue, mirroring
// ContinueCheckoutSync's own "opts.TestCommand = tx.TestCommand" rule
// (checkout_sync.go:920) — and never re-reads config per entry the way
// unguarded legacy external does. The raw command travels only as far as
// this struct; buildIntent (rebase_plan_build.go) publishes Digest alone.
func checkoutValidationIdentity(opts CheckoutSyncOpts, tx *CheckoutTransaction) PlanValidationIdentity {
	command := opts.TestCommand
	source := "cli-test"
	if opts.Continue && tx != nil {
		command = tx.TestCommand
		source = "persisted-transaction"
	}
	if command == "" {
		return PlanValidationIdentity{Applies: false, Source: "none"}
	}
	return PlanValidationIdentity{Applies: true, Command: command, Source: source, Digest: ValidationDigest(command)}
}

// checkoutRequestedRoute is RebasePlanRequest.RequestedRoute (§13.6 rule 4):
// "" whenever this invocation's own nominal route (opts.NewMode) already
// equals the effective one, which is always true on a fresh run and true on
// a continuation whose persisted transaction agrees with the flag this
// invocation happened to carry; it surfaces only the disagreement a
// continuation's own inherited route can create.
func checkoutRequestedRoute(opts CheckoutSyncOpts, effective string) string {
	requested := RouteLegacy
	if opts.NewMode {
		requested = RouteNewMode
	}
	if requested == effective {
		return ""
	}
	return requested
}

// checkoutContinueMismatchAxis mirrors checkoutContinueMismatches' own
// four-way axis check (checkout_sync.go), read-only: every sentence it can
// produce is generated by calling the shipped checkoutContinueMismatch
// formatter directly, so the detail text is never re-authored — only the
// axis token is surfaced structurally, for a document a shipped `error`
// cannot carry.
func checkoutContinueMismatchAxis(opts CheckoutSyncOpts, tx *CheckoutTransaction) (axis, detail string, mismatched bool) {
	changed := opts.Changed
	persisted := transactionPolicy(tx)
	switch {
	case (changed["fetch"] || changed["no-fetch"]) && opts.Policy.Fetch != persisted.Fetch:
		return "fetch", checkoutContinueMismatch("fetch", string(persisted.Fetch), string(opts.Policy.Fetch)).Error(), true
	case (changed["full"] || changed["local-only"]) && opts.Policy.Propagation != persisted.Propagation:
		return "propagation", checkoutContinueMismatch("propagation", string(persisted.Propagation), string(opts.Policy.Propagation)).Error(), true
	case (changed["only"] || changed["from"]) && opts.Policy.ScopeLabel() != persisted.ScopeLabel():
		return "scope", checkoutContinueMismatch("scope", persisted.ScopeLabel(), opts.Policy.ScopeLabel()).Error(), true
	case changed["push"] && opts.Push != tx.Push:
		return "push", checkoutContinueMismatch("push", fmt.Sprintf("%v", tx.Push), fmt.Sprintf("%v", opts.Push)).Error(), true
	default:
		return "", "", false
	}
}

// checkoutContinuationGate is RebasePlanRequest.ContinuationGate (§13.7a
// rule 9): a read-only projection of ContinueCheckoutSync's own dispatch
// gates (checkout_sync.go), never a second implementation of them — every
// detail sentence it can produce comes from calling the shipped
// checkoutContinueMismatch/transactionPolicy helpers directly. It applies
// only on --continue with an already-decoded transaction; "no transaction
// to continue" and "state version too new" surface through StackErr/Gates
// elsewhere, since this gate only covers the mismatch/selection checks that
// need a decoded transaction to evaluate at all.
func checkoutContinuationGate(opts CheckoutSyncOpts, state CheckoutPlanState, tx *CheckoutTransaction, stack Stack) PlanContinuationGate {
	if !opts.Continue {
		return PlanContinuationGate{}
	}
	if tx == nil {
		// A continuation with no decoded transaction publishes the SHIPPED
		// no-transaction refusal as its own cause, so the rows-less document
		// always names why it cannot be planned (§13.7a rule 4).
		detail := "no transaction to continue"
		if err := state.Files.CheckoutTransaction.Err; err != nil {
			detail = fmt.Sprintf("%s: %v", detail, err)
		}
		return PlanContinuationGate{Applies: true, Failed: true, Axis: "state", Detail: detail}
	}
	if TransactionNewMode(tx) {
		if axis, detail, mismatched := checkoutContinueMismatchAxis(opts, tx); mismatched {
			return PlanContinuationGate{Applies: true, Failed: true, Axis: axis, Detail: detail}
		}
		for _, name := range tx.Selected {
			if !HasBranch(stack, name) {
				return PlanContinuationGate{
					Applies: true, Failed: true, Axis: "selection",
					Detail: fmt.Sprintf("selected stack entry %q no longer exists in stack; use --abort", name),
				}
			}
		}
	} else if opts.Push && !tx.Push {
		return PlanContinuationGate{
			Applies: true, Failed: true, Axis: "push",
			Detail: fmt.Sprintf("cannot add --push to an existing transaction that was started without it; persisted push=%v wins", tx.Push),
		}
	}
	return PlanContinuationGate{Applies: true}
}

// checkoutRowsAvailable is RebasePlanRequest.RowsAvailable (§13.7 rule 4):
// the fresh arm needs Stack/Order/Selection all resolved; the continuation
// arm additionally needs a decoded transaction, since Remaining/entries[]
// filtering has nothing meaningful to filter against otherwise.
func checkoutRowsAvailable(insp CheckoutPlanInspection) bool {
	resolved := insp.StackErr == nil && insp.SortErr == nil && insp.SelectionErr == nil
	if !resolved {
		return false
	}
	if insp.Continue {
		return insp.State.Files.CheckoutTransaction.Transaction != nil
	}
	return true
}

// checkoutPlanRequest is the shared assembly step BuildCheckoutRebasePlan and
// BuildCheckoutContinuationPlan both need: every RebasePlanRequest member
// InspectCheckoutPlan's own measurement pass already settled, independent of
// the fetch/fresh-vs-continuation branching each caller still does on its
// own. fetchOutcome is threaded in rather than measured here because only
// the fresh caller ever has one to report.
func checkoutPlanRequest(opts CheckoutSyncOpts, insp CheckoutPlanInspection, fetchOutcome PlanFetchOutcome) RebasePlanRequest {
	tx := insp.State.Files.CheckoutTransaction.Transaction
	route := checkoutEffectiveRoute(opts, tx)
	rowsAvailable := checkoutRowsAvailable(insp)

	var stackPtr *Stack
	if rowsAvailable {
		s := insp.Stack
		stackPtr = &s
	}

	_, commonDir, _ := MeasureContextRoots(opts.RepoDir)

	return RebasePlanRequest{
		Layout:                    RebasePlanLayout{FeaturePath: opts.FeaturePath, RepoRoot: opts.RepoDir},
		Mode:                      ModeCheckout,
		Feature:                   opts.Feature,
		Workspace:                 checkoutWorkspace(opts),
		Route:                     route,
		RequestedRoute:            checkoutRequestedRoute(opts, route),
		RouteTriggers:             checkoutRouteTriggers(opts.Changed),
		Invocation:                "plan-only",
		Policy:                    opts.Policy,
		PolicyFetchDefaultApplied: !opts.Changed["fetch"] && !opts.Changed["no-fetch"],
		Push:                      checkoutPushIntent(opts, tx),
		PushSource:                checkoutPushSource(opts, tx),
		Guard:                     opts.PlanGuard,
		Limits:                    insp.Limits,
		LimitConflicts:            insp.LimitConflicts,
		Validation:                checkoutValidationIdentity(opts, tx),
		Approve:                   opts.PlanGuard.Approve,
		Stack:                     stackPtr,
		Order:                     insp.Order,
		SortErr:                   insp.SortErr,
		StackErr:                  insp.StackErr,
		Selection:                 insp.Selection,
		SelectionResolved:         insp.SelectionResolved,
		SelectionErr:              insp.SelectionErr,
		RowsAvailable:             rowsAvailable,
		Continue:                  opts.Continue,
		Remaining:                 insp.Remaining,
		StageFacts:                insp.StageFacts,
		Changed:                   opts.Changed,
		ContinuationGate:          checkoutContinuationGate(opts, insp.State, tx, insp.Stack),
		Fetch:                     fetchOutcome,
		FetchPlan:                 insp.FetchPlan,
		PushFacts:                 RefreshPushTrackingRefs(checkoutPushFacts(opts, insp.Capabilities, commonDir), fetchOutcome),
		BasePreflight:             insp.BasePreflight,
		Version:                   insp.Version,
		Capabilities:              insp.Capabilities,
		CheckoutState:             insp.State,
		Gates:                     insp.Gates,
	}
}

// PlanCheckoutRebase is the checkout route's plan-only entry point (§13.7):
// it performs the ordered gates, fetches at most once and only under an
// effective --fetch policy on the fresh route (never on --continue), and
// returns the resulting RebasePlan value to its caller in package cli. It
// writes no document byte of its own and never touches os.Stdout/
// os.Stderr — w.Prose is the only writer it is given, and it is used only
// for the same "Fetching origin ... done/failed" line
// fetchCheckoutRepoTo already prints on the shipped mutating route.
func PlanCheckoutRebase(opts CheckoutSyncOpts, w PlanWriters) (RebasePlan, error) {
	if opts.Continue {
		return BuildCheckoutContinuationPlan(opts)
	}
	return BuildCheckoutRebasePlan(opts, w)
}

// BuildCheckoutRebasePlan covers the fresh checkout route (§13.7): it
// inspects Git/transaction/lock state, performs the pre-lock precondition
// gates and the I14 base preflight, measures (never assumes) the pre-fetch
// context/effect enumeration, performs the run's own at-most-once fetch
// when the effective policy calls for one and nothing already blocks it,
// and assembles + builds the resulting RebasePlanRequest.
func BuildCheckoutRebasePlan(opts CheckoutSyncOpts, w PlanWriters) (RebasePlan, error) {
	insp := InspectCheckoutPlan(CheckoutPlanInspectionRequest{Opts: opts})

	var fetchOutcome PlanFetchOutcome
	if opts.Policy.Fetch == SyncFetchEnabled && insp.FetchPlan.Applies && len(insp.FetchPlan.Blockers) == 0 &&
		checkoutRowsAvailable(insp) && !checkoutGatesFailed(insp.Gates) && !insp.BasePreflight.Failed && !insp.State.LiveForeignLock() {
		fetchOutcome = fetchCheckoutRepoTo(w.Prose, PlanFetchContext{
			RepoToken:  "",
			Root:       opts.RepoDir,
			CommonDir:  insp.FetchPlan.Contexts[0].CommonDir,
			Source:     "workspace-repo-root",
			Candidates: insp.FetchPlan.Contexts[0].Candidates,
		})
	}

	req := checkoutPlanRequest(opts, insp, fetchOutcome)
	return BuildRebasePlan(req)
}

// checkoutGatesFailed reports whether any applicable §13.7 precondition gate
// (checkoutPreconditionGates' own three rows) failed — one of §11.2 cause
// 2's own "any pre-fetch gate the described executor raises above its own
// fetch" members, and, independently, a reason BuildCheckoutRebasePlan must
// never issue a real fetch against a tree its own gates are about to refuse
// over.
func checkoutGatesFailed(gates []PlanGateResult) bool {
	for _, g := range gates {
		if g.Applies && g.Failed {
			return true
		}
	}
	return false
}

// BuildCheckoutContinuationPlan covers the --continue route (§13.7a): it
// never fetches (§11.1 rule: a continuation has already passed its one
// fetch opportunity or never had one) and never re-derives a plan — its
// entries are the persisted transaction's own remaining work, via
// RemainingRebaseEntries, exactly as InspectCheckoutPlan already measured.
func BuildCheckoutContinuationPlan(opts CheckoutSyncOpts) (RebasePlan, error) {
	insp := InspectCheckoutPlan(CheckoutPlanInspectionRequest{Opts: opts})
	req := checkoutPlanRequest(opts, insp, PlanFetchOutcome{})
	return BuildRebasePlan(req)
}

package internal

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// ============================================================================
// Generic exec helpers — every Git invocation in this file runs `-C <dir>`
// explicitly rather than via cmd.Dir, matching the literal command text the
// specification quotes (`git -C <execution_context> rev-list ...`, §5, §11.7).
// ============================================================================

// runGit runs `git -C dir <args...>`, discarding neither stream: stdout is
// captured and trimmed of exactly one trailing newline (never more, so a
// value that legitimately ends in blank lines is not mangled), and stderr is
// captured on the returned *exec.ExitError so a caller that needs Git's own
// sentence (never surfaced to a document, only to Go errors) can read it.
func runGit(dir string, args ...string) (string, error) {
	full := append([]string{"-C", dir}, args...)
	cmd := exec.Command("git", full...)
	var stderr strings.Builder
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return "", fmt.Errorf("git %s: %s: %w", strings.Join(args, " "), strings.TrimSpace(stderr.String()), exitErr)
		}
		return "", err
	}
	return strings.TrimSuffix(string(out), "\n"), nil
}

// runGitRaw is runGit without any newline trimming, for callers that parse a
// NUL- or newline-delimited stream themselves and need every byte Git wrote.
func runGitRaw(dir string, args ...string) ([]byte, error) {
	full := append([]string{"-C", dir}, args...)
	cmd := exec.Command("git", full...)
	out, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	return out, nil
}

// gitExitCode extracts the process exit code from a git invocation's error,
// or -1 when err does not carry one (a genuine exec failure: binary not
// found, context cancelled, and so on — never a value git itself chose).
func gitExitCode(err error) int {
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		return exitErr.ExitCode()
	}
	return -1
}

// runGitStreamLines runs `git -C dir <args...>`, streaming stdout to onLine
// one newline-delimited record at a time and reading the pipe to EOF before
// waiting on the process — the pipe is never closed early, so no command
// this function drives can ever raise EPIPE/SIGPIPE against the child (§5
// rule 6). onLine's error, if any, is remembered but does not stop the read;
// the child is always drained and waited on before this function returns.
func runGitStreamLines(dir string, args []string, onLine func(line string) error) error {
	full := append([]string{"-C", dir}, args...)
	cmd := exec.Command("git", full...)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	var stderr strings.Builder
	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		return err
	}

	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	var callbackErr error
	for scanner.Scan() {
		if callbackErr == nil {
			callbackErr = onLine(scanner.Text())
		}
	}
	scanErr := scanner.Err()
	waitErr := cmd.Wait()

	if waitErr != nil {
		return fmt.Errorf("git %s: %s", strings.Join(args, " "), strings.TrimSpace(stderr.String()))
	}
	if scanErr != nil {
		return scanErr
	}
	return callbackErr
}

// ============================================================================
// Generic length-framed SHA-256 — the one hashing primitive context_id and
// issue_id both build on.
// ============================================================================

// lengthFramedSHA256 hashes an ordered tuple of raw byte strings as SHA-256
// over their length-prefixed concatenation: each element is framed as a
// 4-byte big-endian length followed by its raw bytes, with no delimiter
// byte and no type tag, so no two adjacent elements can ever be confused for
// each other regardless of the bytes either one contains. The specification
// fixes the length-framed, raw-byte property (§4.4, §18.6) but not a
// concrete byte width; this is this file's own choice of width, exactly as
// internal/rebase_plan_fingerprint.go documents making its own choice for the
// whole-document TLV pre-image.
func lengthFramedSHA256(parts ...string) [32]byte {
	h := sha256.New()
	var length [4]byte
	for _, p := range parts {
		binary.BigEndian.PutUint32(length[:], uint32(len(p)))
		h.Write(length[:])
		h.Write([]byte(p))
	}
	var sum [32]byte
	copy(sum[:], h.Sum(nil))
	return sum
}

// ============================================================================
// Context identity (§4.4, §14.1a) — the one generic context-identity
// function, never execution-scoped and with no empty-string fallback.
// ============================================================================

// MeasureContextRoots runs the two canonicalizing Git reads a context
// identity needs — `rev-parse --show-toplevel` and `rev-parse
// --git-common-dir` — and returns each canonicalized by the §18.3 rule
// (EvalSymlinks plus the macOS /private spelling, via the package's existing
// canonicalPath). It is the read half of context identity; the caller
// already knows why this directory was chosen (entry repo, worktree, process
// cwd or workspace repository root) and supplies that as root_source
// separately, because this function has no way to infer it.
func MeasureContextRoots(dir string) (repoRoot string, commonDir string, err error) {
	top, err := runGit(dir, "rev-parse", "--show-toplevel")
	if err != nil {
		return "", "", fmt.Errorf("measure context roots: %w", err)
	}
	common, err := runGit(dir, "rev-parse", "--git-common-dir")
	if err != nil {
		return "", "", fmt.Errorf("measure context roots: %w", err)
	}
	if !filepath.IsAbs(common) {
		common = filepath.Join(dir, common)
	}
	return canonicalPath(top), canonicalPath(filepath.Clean(common)), nil
}

// ContextIdentityFor computes the §4.4 context_id: SHA-256 over the
// length-framed raw tuple ("config-context/v1", canonical raw repo root,
// root_source, canonical raw common dir). Callers that lack a canonical
// common dir MUST NOT call this with an empty string — there is no
// empty-string fallback (§4.4).
func ContextIdentityFor(repoRoot, rootSource, commonDir string) PlanContextIdentity {
	sum := lengthFramedSHA256("config-context/v1", repoRoot, rootSource, commonDir)
	return PlanContextIdentity{
		ContextID: hex.EncodeToString(sum[:]),
		RepoRoot:  repoRoot,
		CommonDir: commonDir,
	}
}

// EstablishContextIdentity composes MeasureContextRoots and
// ContextIdentityFor for the common case: a directory and the root_source
// label the caller already knows for it.
func EstablishContextIdentity(dir, rootSource string) (PlanContextIdentity, error) {
	repoRoot, commonDir, err := MeasureContextRoots(dir)
	if err != nil {
		return PlanContextIdentity{}, err
	}
	return ContextIdentityFor(repoRoot, rootSource, commonDir), nil
}

// ContextIdentityRequest is one (directory, root_source) pair
// BuildContextIdentities measures.
type ContextIdentityRequest struct {
	Dir        string
	RootSource string
}

// BuildContextIdentities measures every requested directory exactly once and
// returns the accumulated PlanContextIdentities table keyed by context_id
// (§4.4, §14.1a). Two requests that canonicalize to the same tuple collapse
// onto the same map entry, which is the ordinary multi-worktree-stack case,
// not a violation. The first measurement failure is returned immediately;
// partial identity tables are not published because every join in the
// document is keyed off this map (§4.4).
func BuildContextIdentities(reqs []ContextIdentityRequest) (PlanContextIdentities, error) {
	ids := make(PlanContextIdentities, len(reqs))
	for _, req := range reqs {
		identity, err := EstablishContextIdentity(req.Dir, req.RootSource)
		if err != nil {
			return nil, fmt.Errorf("build context identities: %s: %w", req.Dir, err)
		}
		ids[identity.ContextID] = identity
	}
	return ids, nil
}

// ============================================================================
// Candidate probes (§5 rules 4-10)
// ============================================================================

// ProbeCandidateCount is §5 rule 4: `rev-list --count --no-merges
// <upstream>..<branch>`, run in the execution context's own directory.
func ProbeCandidateCount(execDir, upstream, branch string) (int, error) {
	out, err := runGit(execDir, "rev-list", "--count", "--no-merges", upstream+".."+branch)
	if err != nil {
		return 0, err
	}
	count, convErr := strconv.Atoi(strings.TrimSpace(out))
	if convErr != nil {
		return 0, fmt.Errorf("probe candidate count: unparseable rev-list --count output %q: %w", out, convErr)
	}
	return count, nil
}

// ProbeFirstCandidate is §5 rule 5. For count <= 0 there is no first
// candidate and this returns (nil, nil) without running Git at all, per the
// rule's own "omitted for N == 0" text (generalised to any non-positive
// count, since a first candidate cannot exist without one). For N > 0 it
// runs `rev-list --skip=<N-1> --max-count=1 --no-merges --topo-order
// <upstream>..<branch>` — never `--reverse --max-count=1`, which would
// return the newest commit instead of the first replay candidate — and then
// reads that commit's raw, unsanitized subject with `git log -1
// --format=%s`. The subject is stored verbatim: sanitization is a
// render-time-only concern (internal/rebase_plan_render.go).
func ProbeFirstCandidate(execDir, upstream, branch string, count int) (*PlanReplayCandidate, error) {
	if count <= 0 {
		return nil, nil
	}
	sha, err := runGit(execDir, "rev-list",
		fmt.Sprintf("--skip=%d", count-1), "--max-count=1", "--no-merges", "--topo-order",
		upstream+".."+branch)
	if err != nil {
		return nil, err
	}
	sha = strings.TrimSpace(sha)
	if sha == "" {
		return nil, fmt.Errorf("probe first candidate: rev-list produced no commit for count %d", count)
	}
	subject, err := runGit(execDir, "log", "-1", "--format=%s", sha)
	if err != nil {
		return nil, err
	}
	return &PlanReplayCandidate{
		SHA:     sha,
		Short:   shortSHA(sha),
		Subject: subject,
	}, nil
}

// CandidateStreamResult is the outcome of the one required §5 rule 6 stream
// read: Commits retains at most the first 50 SHAs oldest-first (§5 rule 7),
// Listed is the true total observed on the stream (which may exceed
// len(Commits)), Truncated is Listed > len(Commits), and CandidateDigest is
// the SHA-256 (§5 rule 8) over every SHA the stream produced — not just the
// retained 50 — each followed by "\n", rendered as 64 lowercase hex.
type CandidateStreamResult struct {
	Commits         []string
	Listed          int
	Truncated       bool
	CandidateDigest string
}

// candidateStreamRetentionCap is the §5 rule 7 rendering cap. It bounds only
// what this process retains in memory; the digest still covers the entire
// stream (§5 rule 8).
const candidateStreamRetentionCap = 50

// ProbeCandidateStream is §5 rule 6: exactly one `rev-list --reverse
// --topo-order --no-merges <upstream>..<branch>` stream, read to EOF. The
// pipe is never closed early — a second, count-derived --skip/--max-count
// window probe MUST NOT be issued instead, and none is (§5 rule 6). A known
// empty sequence yields the SHA-256 of zero bytes for CandidateDigest, per
// sha256.New's own zero-write behaviour, with no special case needed here.
func ProbeCandidateStream(execDir, upstream, branch string) (CandidateStreamResult, error) {
	h := sha256.New()
	var result CandidateStreamResult
	err := runGitStreamLines(execDir,
		[]string{"rev-list", "--reverse", "--topo-order", "--no-merges", upstream + ".." + branch},
		func(line string) error {
			sha := strings.TrimSpace(line)
			if sha == "" {
				return nil
			}
			result.Listed++
			if len(result.Commits) < candidateStreamRetentionCap {
				result.Commits = append(result.Commits, sha)
			}
			h.Write([]byte(sha))
			h.Write([]byte("\n"))
			return nil
		})
	if err != nil {
		return CandidateStreamResult{}, err
	}
	result.Truncated = result.Listed > len(result.Commits)
	result.CandidateDigest = hex.EncodeToString(h.Sum(nil))
	return result, nil
}

// ProbeMayDropPatchEquivalent is §5 rule 10's may_drop_patch_equivalent probe:
// `git rev-list --count <branch>..<upstream>` — the reversed range from the
// count/first/stream probes above. An empty result yields false, a non-empty
// one true, and a probe failure yields (nil, err) so the caller can publish
// the null the rule requires without inventing a false negative.
func ProbeMayDropPatchEquivalent(execDir, upstream, branch string) (*bool, error) {
	out, err := runGit(execDir, "rev-list", "--count", branch+".."+upstream)
	if err != nil {
		return nil, err
	}
	count, convErr := strconv.Atoi(strings.TrimSpace(out))
	if convErr != nil {
		return nil, fmt.Errorf("probe may-drop-patch-equivalent: unparseable rev-list --count output %q: %w", out, convErr)
	}
	result := count > 0
	return &result, nil
}

// ============================================================================
// Ordered Git config inventory (§11.7)
// ============================================================================

// GitConfigEntry is one ordered `git config --list --show-scope -z` record,
// kept in inventory order exactly as Git printed it (lowest to highest
// precedence within a scope, scopes themselves in Git's own read order).
type GitConfigEntry struct {
	Scope        string // one of Git's --show-scope names (system|global|local|worktree|command|submodule|unknown)
	Key          string // section.[subsection.]variable; section/variable lowercased by Git, subsection case preserved verbatim
	Value        string // "" both for a valueless occurrence and an explicit empty value — ValuePresent disambiguates
	ValuePresent bool   // false ⇔ a valueless occurrence ("key" with no "=value")
}

// GitConfigInventory is the outcome of the one ordered `--list --show-scope
// -z` read of §11.7. A failed or unparseable read yields Available: false
// with Entries left nil — never a partial slice — so every consumer treats
// it as fully invalid rather than as an incomplete-but-usable one.
type GitConfigInventory struct {
	Available bool
	Entries   []GitConfigEntry
	Err       error
}

// ProbeGitConfigInventory runs the one ordered read of §11.7:
// `git -C root config --list --show-scope -z`. It always attempts the read;
// gating it on CapConfigShowScope (§16 rule 3a) is the caller's job, exactly
// as gating it on the route's config scope rule is.
func ProbeGitConfigInventory(root string) GitConfigInventory {
	raw, err := runGitRaw(root, "config", "--list", "--show-scope", "-z")
	if err != nil {
		return GitConfigInventory{Err: err}
	}
	entries, parseErr := parseGitConfigInventory(raw)
	if parseErr != nil {
		return GitConfigInventory{Err: parseErr}
	}
	return GitConfigInventory{Available: true, Entries: entries}
}

// parseGitConfigInventory decodes the NUL-delimited `--show-scope -z`
// stream. Git emits each entry as a PAIR of NUL-terminated records — the
// scope alone, then either "key" (valueless) or "key\nvalue" — never a
// single combined "scope\tkey" record, which this function relies on
// (empirically confirmed against Git 2.55) rather than guessing at a
// delimiter. A malformed stream — an odd record count, a final byte that is
// not NUL, or an empty key — invalidates the whole read rather than
// publishing a partial list, matching this package's other fail-closed
// inventories (WorktreeInventory, BranchRefInventory).
func parseGitConfigInventory(raw []byte) ([]GitConfigEntry, error) {
	if len(raw) == 0 {
		return []GitConfigEntry{}, nil
	}
	if raw[len(raw)-1] != 0 {
		return nil, fmt.Errorf("git config inventory: output does not end with NUL")
	}
	records := strings.Split(string(raw[:len(raw)-1]), "\x00")
	if len(records)%2 != 0 {
		return nil, fmt.Errorf("git config inventory: odd record count %d", len(records))
	}
	entries := make([]GitConfigEntry, 0, len(records)/2)
	for i := 0; i < len(records); i += 2 {
		scope := records[i]
		keyValue := records[i+1]
		key := keyValue
		value := ""
		present := false
		if idx := strings.IndexByte(keyValue, '\n'); idx >= 0 {
			key = keyValue[:idx]
			value = keyValue[idx+1:]
			present = true
		}
		if key == "" {
			return nil, fmt.Errorf("git config inventory: empty key at record %d", i)
		}
		entries = append(entries, GitConfigEntry{Scope: scope, Key: key, Value: value, ValuePresent: present})
	}
	return entries, nil
}

// entriesForKey returns every inventory entry for key (already in Git's own
// normalized section.variable lowercase, subsection case preserved), in
// inventory order.
func entriesForKey(inv GitConfigInventory, key string) []GitConfigEntry {
	var matches []GitConfigEntry
	for _, e := range inv.Entries {
		if e.Key == key {
			matches = append(matches, e)
		}
	}
	return matches
}

// finalOccurrence returns the last (highest-precedence) inventory entry for
// key — Git's own "last one wins" rule for a single-valued key.
func finalOccurrence(inv GitConfigInventory, key string) (GitConfigEntry, bool) {
	matches := entriesForKey(inv, key)
	if len(matches) == 0 {
		return GitConfigEntry{}, false
	}
	return matches[len(matches)-1], true
}

// parseGitConfigBool applies Git's own `--type=bool` parsing rule to one raw
// occurrence (empirically confirmed against Git 2.55): a valueless
// occurrence is true; the explicit empty string is false; "true"/"yes"/"on"
// (case-insensitive) are true and "false"/"no"/"off" are false; any other
// value that parses as a base-10 integer is true iff non-zero; anything else
// does not parse.
func parseGitConfigBool(value string, present bool) (result bool, ok bool) {
	if !present {
		return true, true
	}
	switch strings.ToLower(value) {
	case "true", "yes", "on":
		return true, true
	case "false", "no", "off", "":
		return false, true
	}
	if n, err := strconv.Atoi(strings.TrimSpace(value)); err == nil {
		return n != 0, true
	}
	return false, false
}

// firstInvalidBooleanOccurrence scans every occurrence of key, in inventory
// order, for the first one Git's own bool grammar would reject — the
// "ordered-callback keys" rule of §11.7, applied directly to a plain-boolean
// key that carries no typed read of its own (every fatal plain-boolean key
// except rebase.updateRefs and rebase.autoStash, which §11.7 caps at two
// typed reads total per context).
func firstInvalidBooleanOccurrence(inv GitConfigInventory, key string) (GitConfigEntry, bool) {
	for _, e := range entriesForKey(inv, key) {
		if _, ok := parseGitConfigBool(e.Value, e.ValuePresent); !ok {
			return e, true
		}
	}
	return GitConfigEntry{}, false
}

// rebaseMergesGrammar applies §11.7's rebase.rebaseMerges-specific parse
// table to the ordered inventory's final effective occurrence: this key has
// no typed read (a --type=bool --get would misreport the valid
// rebase-cousins/no-rebase-cousins tokens as a boolean error and would
// collapse a valueless occurrence), so its grammar is reimplemented here
// exactly as the table specifies. present distinguishes a valueless
// occurrence (recreates merges) from an explicit one.
func rebaseMergesGrammar(value string, present bool) (recreates bool, ok bool) {
	if !present {
		return true, true
	}
	switch value {
	case "rebase-cousins", "no-rebase-cousins": // exact, case-sensitive; both recreate merges
		return true, true
	}
	switch strings.ToLower(value) {
	case "true", "yes", "on":
		return true, true
	case "false", "no", "off", "":
		return false, true
	}
	if n, err := strconv.Atoi(strings.TrimSpace(value)); err == nil {
		return n != 0, true
	}
	return false, false
}

// typedBoolStatus is the outcome of one `--type=bool --get` read.
type typedBoolStatus int

const (
	typedBoolAbsent typedBoolStatus = iota
	typedBoolValid
	typedBoolInvalid
)

// probeTypedBoolConfig runs one of §11.7's at-most-two typed boolean reads:
// `git -C root config --type=bool --get key`. Exit 1 is Git's own "key not
// found" (typedBoolAbsent); exit 128 is Git's own "bad boolean"
// (typedBoolInvalid) — reached whenever ANY occurrence in file order is
// unparseable, even one a later, valid occurrence would otherwise mask,
// because Git's config machinery aborts at the first one it cannot parse
// while walking to find the last (verified empirically against Git 2.55: a
// first-bad-then-valid pair and a valid-then-first-bad pair both exit 128).
// Any other outcome is a genuine exec error, not a config result, and is
// returned as such.
func probeTypedBoolConfig(root, key string) (typedBoolStatus, bool, error) {
	out, err := runGit(root, "config", "--type=bool", "--get", key)
	if err == nil {
		return typedBoolValid, strings.TrimSpace(out) == "true", nil
	}
	switch gitExitCode(err) {
	case 1:
		return typedBoolAbsent, false, nil
	case 128:
		return typedBoolInvalid, false, nil
	}
	return typedBoolAbsent, false, err
}

// deriveBooleanSlot derives one plain-boolean PlanConfigSlot (update_refs or
// auto_stash — the two keys §11.7 grants a typed read) using the typed read
// as the fast, authoritative path, falling back to a manual walk of the
// already-fetched ordered inventory — applying Git's own bool grammar — to
// find the first occurrence a typed read would have failed on, when the
// typed read itself reports invalid. invocationKey is the literal key Git
// expects on the command line (e.g. "rebase.updateRefs"); lookupKey is its
// Git-normalized, all-lowercase inventory form (e.g. "rebase.updaterefs").
func deriveBooleanSlot(inv GitConfigInventory, root, invocationKey, lookupKey string) (PlanConfigSlot, *GitConfigEntry) {
	status, value, err := probeTypedBoolConfig(root, invocationKey)
	if err != nil {
		return PlanConfigSlot{Status: "probe-failed"}, nil
	}
	switch status {
	case typedBoolAbsent:
		return PlanConfigSlot{Status: "absent"}, nil
	case typedBoolValid:
		v := strconv.FormatBool(value)
		source := "probed"
		return PlanConfigSlot{Status: "valid", Value: &v, Source: &source}, nil
	default: // typedBoolInvalid
		if entry, invalid := firstInvalidBooleanOccurrence(inv, lookupKey); invalid {
			return PlanConfigSlot{Status: "invalid", Source: &entry.Scope}, &entry
		}
		// The typed read reported invalid but the same-grammar manual walk
		// found nothing wrong. Unreachable against a real Git, but a
		// fabricated occurrence would be worse than an honest probe-failed.
		return PlanConfigSlot{Status: "probe-failed"}, nil
	}
}

// deriveRebaseMergesSlot derives repositories[].config.rebase_merges. There
// is no typed read for this key (§11.7): its value is the ordered
// inventory's final occurrence alone. Absence yields interpretation:"false"
// — the one documented exception where a not-present slot still carries an
// interpretation (§4.4).
func deriveRebaseMergesSlot(inv GitConfigInventory) (PlanConfigSlot, *GitConfigEntry) {
	entry, ok := finalOccurrence(inv, "rebase.rebasemerges")
	if !ok {
		return PlanConfigSlot{Status: "absent", Interpretation: "false"}, nil
	}
	recreates, valid := rebaseMergesGrammar(entry.Value, entry.ValuePresent)
	if !valid {
		return PlanConfigSlot{Status: "invalid", Source: &entry.Scope, Interpretation: "invalid"}, &entry
	}
	value := entry.Value // raw mode token as written; "" for a valueless occurrence is a known value, not null
	source := "probed"
	interpretation := "false"
	if recreates {
		interpretation = "true"
	}
	return PlanConfigSlot{Status: "valid", Value: &value, Source: &source, Interpretation: interpretation}, nil
}

// deriveBackendSlot derives repositories[].config.backend. rebase.backend
// has no typed read either (§11.7): a valueless occurrence is invalid
// wherever it occurs ("any occurrence"), detected by scanning every
// occurrence in order rather than only the final one; an unknown,
// non-valueless name is invalid only at the final occurrence, and only when
// nonForcingRebasePresent is true (an entry whose argv would actually
// consult it exists in this context) — the caller supplies that fact because
// it depends on argv this function never sees. Returning a nil issue while
// still marking the slot invalid is exactly the "out-of-scope invalid value
// is neither parsed nor disclosed" case (§11.7): the configuration is
// honestly reported, but no config_issues[] row is minted for a cell no
// entry's argv would ever consult.
func deriveBackendSlot(inv GitConfigInventory, nonForcingRebasePresent bool) (PlanConfigSlot, *GitConfigEntry, string) {
	entries := entriesForKey(inv, "rebase.backend")
	if len(entries) == 0 {
		return PlanConfigSlot{Status: "absent"}, nil, ""
	}
	for i := range entries {
		if !entries[i].ValuePresent {
			offending := entries[i]
			return PlanConfigSlot{Status: "invalid", Source: &offending.Scope}, &offending, "missing-backend-value"
		}
	}
	final := entries[len(entries)-1]
	switch final.Value {
	case "merge", "apply":
		value := final.Value
		source := "probed"
		return PlanConfigSlot{Status: "valid", Value: &value, Source: &source}, nil, ""
	default:
		slot := PlanConfigSlot{Status: "invalid", Source: &final.Scope}
		if nonForcingRebasePresent {
			return slot, &final, "unknown-rebase-backend"
		}
		return slot, nil, ""
	}
}

// RepositoryConfigScope tells ProbeRepositoryConfig / DeriveRepositoryConfig
// which parts of §11.7's closed v1 fatal-key domain the described route
// actually exercises for this execution context, and supplies the small set
// of argv/backend facts the fatal table gates on that a config read alone
// cannot determine — those depend on the entries this context executes and
// their published argv, which only the caller (a planner) has measured.
// Neither function ever infers any of these from the repository itself.
type RepositoryConfigScope struct {
	// Rebase must be true iff this context is an execution_context of at
	// least one real rebase (§11.7's scope rule). When false, all four
	// PlanRepositoryConfig slots are not-evaluated and no rebase-scoped
	// config_issues[] row is ever produced.
	Rebase bool

	// NonForcingRebasePresent must be true when at least one entry in this
	// context publishes an argv that effective_backend row 1 would NOT
	// already force to merge — i.e., an entry whose rebase.backend value
	// would actually be consulted. It gates only the "unknown rebase.backend
	// name" issue (§11.7 fatal table); the valueless case is unconditional.
	NonForcingRebasePresent bool

	// MergeBackendActive must be true when at least one entry in this
	// context runs under effective_backend: merge. It gates the
	// rebase.abbreviateCommands and rebase.maxLabelLength issues, both
	// declared "merge backend only" in the fatal table.
	MergeBackendActive bool
}

// PlanConfigResult is the composite outcome of the one ordered
// `git config --list --show-scope -z` read plus its at-most-two typed
// boolean reads for a single execution context (§11.7): the four
// repositories[].config slots, and every config_issues[] row the closed v1
// rebase-scoped fatal-key domain yields from that same inventory.
type PlanConfigResult struct {
	UpdateRefs   PlanConfigSlot
	RebaseMerges PlanConfigSlot
	Backend      PlanConfigSlot
	AutoStash    PlanConfigSlot
	Issues       []PlanConfigIssue // never nil
}

// notEvaluatedConfigResult is the total value of a rebase-out-of-scope
// context: all four slots not-evaluated (§11.7's scope rule: "a base-only or
// push-only context performs zero config reads and its four slots are
// not-evaluated").
func notEvaluatedConfigResult() PlanConfigResult {
	slot := PlanConfigSlot{Status: "not-evaluated"}
	return PlanConfigResult{
		UpdateRefs:   slot,
		RebaseMerges: PlanConfigSlot{Status: "not-evaluated", Interpretation: "unknown"},
		Backend:      slot,
		AutoStash:    slot,
		Issues:       []PlanConfigIssue{},
	}
}

// probeFailedConfigResult is the total value published when the ordered
// inventory itself could not be established — either CapConfigShowScope is
// false (§16, §11.7) or the read/parse failed for an independent reason.
func probeFailedConfigResult() PlanConfigResult {
	slot := PlanConfigSlot{Status: "probe-failed"}
	return PlanConfigResult{
		UpdateRefs:   slot,
		RebaseMerges: PlanConfigSlot{Status: "probe-failed", Interpretation: "unknown"},
		Backend:      slot,
		AutoStash:    slot,
		Issues:       []PlanConfigIssue{},
	}
}

// newConfigIssue mints one config_issues[] row (§2.12's eleven-member shape)
// from the offending inventory entry. issue_id is SHA-256 over the
// length-framed tuple ("config-issue/v1", context_id, key, the offending raw
// value's presence flag as "0"/"1", the raw value itself, route_command).
// The specification fixes no issue_id formula of its own (unlike
// context_id's, §14.1a), so this file reuses the same length-framed SHA-256
// primitive with its own distinct version tag: deterministic,
// collision-resistant across keys/contexts/values/route_commands and stable
// across runs, exactly what "sole sort/dedup key" (§2.12) requires.
func newConfigIssue(contextID string, repoRoot *string, key, source, routeCommand, errorKind string, entry GitConfigEntry) PlanConfigIssue {
	presence := "0"
	if entry.ValuePresent {
		presence = "1"
	}
	sum := lengthFramedSHA256("config-issue/v1", contextID, key, presence, entry.Value, routeCommand)
	issue := PlanConfigIssue{
		IssueID:         hex.EncodeToString(sum[:]),
		ContextID:       contextID,
		RepoRoot:        repoRoot,
		Key:             key,
		Source:          source,
		RouteCommand:    routeCommand,
		ErrorKind:       errorKind,
		RawValuePresent: entry.ValuePresent,
	}
	if entry.ValuePresent {
		raw := []byte(entry.Value)
		b64 := base64.StdEncoding.EncodeToString(raw)
		sha := sha256.Sum256(raw)
		shaHex := hex.EncodeToString(sha[:])
		sanitized := ancestrySanitize(entry.Value, ancestryDetailLimit)
		issue.RawValueBase64 = &b64
		issue.RawValueSHA256 = &shaHex
		issue.SanitizedValue = &sanitized
	}
	return issue
}

// ProbeRepositoryConfig performs §11.7's per-context work end to end: the one
// ordered inventory read (gated by CapConfigShowScope), followed by
// DeriveRepositoryConfig. A caller that already holds this context's
// inventory — a push mapping reusing an execution context's read, or a
// fetch-effect resolution that also needs these same four slots — calls
// DeriveRepositoryConfig directly instead, so the ordered read is never
// taken twice for one context (§11.7, §14.1a rule 7, §22.27a).
func ProbeRepositoryConfig(root string, caps GitCapabilities, scope RepositoryConfigScope, contextID string, repoRoot *string, routeCommand string) PlanConfigResult {
	if !scope.Rebase {
		return notEvaluatedConfigResult()
	}
	if !caps.CapConfigShowScope {
		return probeFailedConfigResult()
	}
	inv := ProbeGitConfigInventory(root)
	return DeriveRepositoryConfig(inv, root, scope, contextID, repoRoot, routeCommand)
}

// DeriveRepositoryConfig is ProbeRepositoryConfig's read-already-done half:
// given an ordered inventory this context already fetched, it runs the two
// typed boolean reads (only when scope.Rebase — never more than once per
// context, which is the caller's responsibility to arrange) and derives the
// four repositories[].config slots plus every config_issues[] row the closed
// v1 rebase-scoped fatal-key domain yields.
func DeriveRepositoryConfig(inv GitConfigInventory, root string, scope RepositoryConfigScope, contextID string, repoRoot *string, routeCommand string) PlanConfigResult {
	if !scope.Rebase {
		return notEvaluatedConfigResult()
	}
	if !inv.Available {
		return probeFailedConfigResult()
	}

	mint := func(key, source, errorKind string, entry GitConfigEntry) PlanConfigIssue {
		return newConfigIssue(contextID, repoRoot, key, source, routeCommand, errorKind, entry)
	}

	var issues []PlanConfigIssue

	updateRefsSlot, updateRefsIssue := deriveBooleanSlot(inv, root, "rebase.updateRefs", "rebase.updaterefs")
	if updateRefsIssue != nil {
		issues = append(issues, mint("rebase.updateRefs", updateRefsIssue.Scope, "bad-boolean", *updateRefsIssue))
	}

	autoStashSlot, autoStashIssue := deriveBooleanSlot(inv, root, "rebase.autoStash", "rebase.autostash")
	if autoStashIssue != nil {
		issues = append(issues, mint("rebase.autoStash", autoStashIssue.Scope, "bad-boolean", *autoStashIssue))
	}

	rebaseMergesSlot, rebaseMergesIssue := deriveRebaseMergesSlot(inv)
	if rebaseMergesIssue != nil {
		issues = append(issues, mint("rebase.rebaseMerges", rebaseMergesIssue.Scope, "unknown-rebase-merges-mode", *rebaseMergesIssue))
	}

	backendSlot, backendIssue, backendErrorKind := deriveBackendSlot(inv, scope.NonForcingRebasePresent)
	if backendIssue != nil {
		issues = append(issues, mint("rebase.backend", backendIssue.Scope, backendErrorKind, *backendIssue))
	}

	for _, plain := range []struct{ lookupKey, jsonKey string }{
		{"rebase.stat", "rebase.stat"},
		{"rebase.autosquash", "rebase.autoSquash"},
		{"rebase.reschedulefailedexec", "rebase.rescheduleFailedExec"},
		{"rebase.forkpoint", "rebase.forkPoint"},
	} {
		if entry, invalid := firstInvalidBooleanOccurrence(inv, plain.lookupKey); invalid {
			issues = append(issues, mint(plain.jsonKey, entry.Scope, "bad-boolean", entry))
		}
	}

	if scope.MergeBackendActive {
		if entry, ok := finalOccurrence(inv, "rebase.abbreviatecommands"); ok {
			if _, valid := parseGitConfigBool(entry.Value, entry.ValuePresent); !valid {
				issues = append(issues, mint("rebase.abbreviateCommands", entry.Scope, "bad-boolean", entry))
			}
		}
		if entry, ok := finalOccurrence(inv, "rebase.maxlabellength"); ok {
			valid := false
			if entry.ValuePresent {
				if _, convErr := strconv.Atoi(strings.TrimSpace(entry.Value)); convErr == nil {
					valid = true
				}
			}
			if !valid {
				issues = append(issues, mint("rebase.maxLabelLength", entry.Scope, "bad-numeric", entry))
			}
		}
	}

	if issues == nil {
		issues = []PlanConfigIssue{}
	}
	return PlanConfigResult{
		UpdateRefs:   updateRefsSlot,
		RebaseMerges: rebaseMergesSlot,
		Backend:      backendSlot,
		AutoStash:    autoStashSlot,
		Issues:       issues,
	}
}

// ============================================================================
// Branch holder inventory (§7.9, §14.4, §18.3)
// ============================================================================

// BranchHoldMechanism is the closed four-member domain a worktree can hold a
// branch under: a plain checkout, or one of the three mid-operation states
// BuildBranchHolderInventory discovers by reading that worktree's own
// operation-state files rather than the porcelain listing's `branch` line,
// which a detached mid-operation worktree never carries.
type BranchHoldMechanism string

const (
	HoldCheckedOut  BranchHoldMechanism = "checked-out"
	HoldRebaseMerge BranchHoldMechanism = "rebase-merge"
	HoldRebaseApply BranchHoldMechanism = "rebase-apply"
	HoldBisect      BranchHoldMechanism = "bisect"
)

// holderMarkerReadCap bounds the head-name/BISECT_START reads
// BuildBranchHolderInventory performs: a ref or branch name is never anywhere
// close to this size, so a file this large is either not the artefact it
// claims to be or hostile, and is refused rather than read in full.
const holderMarkerReadCap = 4096

// BranchHolderRecord is one held branch: the canonical worktree path holding
// it (§18.3's canonical/symlink/`/private`-aware comparison rule — this is
// exactly the path a caller compares against another canonicalized path to
// decide self versus foreign), the mechanism, and whether the holding
// worktree is itself administratively prunable — a prunable worktree still
// holds its branch until `git worktree prune` actually runs, so it is kept
// as a holder, never dropped.
type BranchHolderRecord struct {
	Worktree  string
	Mechanism BranchHoldMechanism
	Prunable  bool
}

// BranchHolderInventory is one repository's whole hold inventory (§7.9,
// §18.3): every branch any worktree holds, checked out or mid-operation,
// keyed by short branch name. A branch is held by at most one worktree at a
// time — Git itself refuses to check out a branch that is already checked
// out, mid-rebase or mid-bisect elsewhere — so ByBranch is single-valued.
// An unavailable inventory is a probe failure, never a "not held" answer,
// so BuildBranchHolderInventory fails closed for the whole repository
// rather than publish a partial map.
type BranchHolderInventory struct {
	Available bool
	ByBranch  map[string]BranchHolderRecord
	Err       error
}

// BuildBranchHolderInventory performs exactly one `git worktree list
// --porcelain` — through the shipped BuildWorktreeInventory — its only
// process, then classifies every record: a non-detached record holds its
// branch as HoldCheckedOut; a detached record is probed, via bounded
// symlink-free reads of that worktree's own Git directory, for a
// rebase-merge, rebase-apply or bisect state that names the branch it is
// operating on. A record this function cannot classify either way (neither
// a branch line nor a detectable operation) simply holds nothing, which is
// not a failure of the whole inventory.
func BuildBranchHolderInventory(repoRoot string) BranchHolderInventory {
	wt := BuildWorktreeInventory(repoRoot)
	if !wt.Available {
		return BranchHolderInventory{Err: wt.Err}
	}
	byBranch := make(map[string]BranchHolderRecord, len(wt.Records))
	for _, rec := range wt.Records {
		if rec.Bare {
			continue // a bare repository record holds no branch
		}
		if rec.BranchRef != nil {
			short := strings.TrimPrefix(*rec.BranchRef, "refs/heads/")
			byBranch[short] = BranchHolderRecord{
				Worktree:  rec.Path,
				Mechanism: HoldCheckedOut,
				Prunable:  rec.Prunable,
			}
			continue
		}
		if branch, mechanism, ok := detectHolderOperation(rec.Path); ok {
			byBranch[branch] = BranchHolderRecord{
				Worktree:  rec.Path,
				Mechanism: mechanism,
				Prunable:  rec.Prunable,
			}
		}
	}
	return BranchHolderInventory{Available: true, ByBranch: byBranch}
}

// detectHolderOperation resolves worktreePath's own Git directory — never
// the common dir, since rebase-merge/, rebase-apply/ and BISECT_START are
// strictly per-worktree (§18.3) — and reports the branch a merge-rebase,
// apply-rebase or bisect there is holding. A missing or unreadable Git
// directory, or none of the three markers present, yields ok == false
// without error: an undetected mid-operation state is simply "not held that
// way", never a failure of the whole-repository inventory (that failure is
// BuildWorktreeInventory's, already handled by the caller).
func detectHolderOperation(worktreePath string) (branch string, mechanism BranchHoldMechanism, ok bool) {
	gitDir, err := resolveWorktreeGitDir(worktreePath)
	if err != nil {
		return "", "", false
	}
	if name, ok := readOperationHeadName(gitDir, "rebase-merge"); ok {
		return name, HoldRebaseMerge, true
	}
	if name, ok := readOperationHeadName(gitDir, "rebase-apply"); ok {
		return name, HoldRebaseApply, true
	}
	if name, ok := readBisectStartBranch(gitDir); ok {
		return name, HoldBisect, true
	}
	return "", "", false
}

// resolveWorktreeGitDir resolves worktreePath's own Git directory: a plain
// directory for a main working tree, or the target of a `gitdir: <path>`
// pointer file for a linked worktree — the same shape the shipped
// probeActiveGitOp (internal/stack_status.go) resolves, reimplemented here
// symlink-free because this file needs the resolved directory path itself,
// not only an operation-kind classification.
func resolveWorktreeGitDir(worktreePath string) (string, error) {
	if worktreePath == "" {
		return "", errors.New("resolveWorktreeGitDir requires a non-empty path")
	}
	gitDir := filepath.Join(worktreePath, ".git")
	info, err := os.Lstat(gitDir)
	if err != nil {
		return "", err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return "", fmt.Errorf("refusing to follow symlinked %s", gitDir)
	}
	if info.IsDir() {
		return gitDir, nil
	}
	data, err := os.ReadFile(gitDir)
	if err != nil {
		return "", err
	}
	after, ok := strings.CutPrefix(strings.TrimSpace(string(data)), "gitdir: ")
	if !ok || after == "" {
		return "", fmt.Errorf("malformed gitdir pointer in %s", gitDir)
	}
	if !filepath.IsAbs(after) {
		after = filepath.Join(worktreePath, after)
	}
	resolved := filepath.Clean(after)
	resolvedInfo, err := os.Lstat(resolved)
	if err != nil {
		return "", err
	}
	if resolvedInfo.Mode()&os.ModeSymlink != 0 {
		return "", fmt.Errorf("refusing to follow symlinked %s", resolved)
	}
	if !resolvedInfo.IsDir() {
		return "", fmt.Errorf("resolved git directory %s is not a directory", resolved)
	}
	return resolved, nil
}

// readSymlinkFreeFile Lstats path and reads it only when that Lstat shows a
// regular file no larger than maxBytes, refusing a symlink outright rather
// than following it. present is false, with a nil error, exactly for
// fs.ErrNotExist — every other failure, including "exists but is a
// symlink"/"not a regular file"/"too large", is reported as an error so a
// caller never silently treats a hostile or malformed artefact as absent.
func readSymlinkFreeFile(path string, maxBytes int64) (content string, present bool, err error) {
	info, statErr := os.Lstat(path)
	if statErr != nil {
		if errors.Is(statErr, fs.ErrNotExist) {
			return "", false, nil
		}
		return "", false, statErr
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return "", false, fmt.Errorf("refusing to follow symlinked artefact %s", path)
	}
	if !info.Mode().IsRegular() {
		return "", false, fmt.Errorf("artefact %s is not a regular file", path)
	}
	if info.Size() > maxBytes {
		return "", false, fmt.Errorf("artefact %s exceeds %d bytes", path, maxBytes)
	}
	data, readErr := os.ReadFile(path)
	if readErr != nil {
		return "", false, readErr
	}
	return string(data), true, nil
}

// readOperationHeadName reads <gitDir>/<opDir>/head-name — opDir one of
// rebase-merge, rebase-apply — and reports the branch the operation started
// from. Git writes either a full `refs/heads/<branch>` ref or the literal
// "detached HEAD" when the operation began on a detached HEAD, which itself
// held no branch; only the former reports a hold.
func readOperationHeadName(gitDir, opDir string) (string, bool) {
	dirInfo, err := os.Lstat(filepath.Join(gitDir, opDir))
	if err != nil || dirInfo.Mode()&os.ModeSymlink != 0 || !dirInfo.IsDir() {
		return "", false
	}
	content, present, err := readSymlinkFreeFile(filepath.Join(gitDir, opDir, "head-name"), holderMarkerReadCap)
	if err != nil || !present {
		return "", false
	}
	ref := strings.TrimSpace(content)
	branch, ok := strings.CutPrefix(ref, "refs/heads/")
	if !ok || branch == "" {
		return "", false
	}
	return branch, true
}

// readBisectStartBranch reads <gitDir>/BISECT_START, which Git writes as the
// short branch name `git bisect start` began from (never a full ref), and
// reports it as the branch bisect is holding.
func readBisectStartBranch(gitDir string) (string, bool) {
	content, present, err := readSymlinkFreeFile(filepath.Join(gitDir, "BISECT_START"), holderMarkerReadCap)
	if err != nil || !present {
		return "", false
	}
	branch := strings.TrimSpace(content)
	if branch == "" {
		return "", false
	}
	return branch, true
}

// PlanHolderIndex is the per-invocation cache of branch holder inventories,
// keyed by context_id (§7.9, §18.3): every context_id that shares a
// canonical common dir shares one entry, and BuildPlanHolderIndex therefore
// calls BuildBranchHolderInventory once per distinct canonical common dir,
// however many context_ids resolve to it. Every consumer — the row fact,
// rank 5.4, §11.8's collateral exclusion, §11.6's held[] and the restore
// question — reads this shared table rather than probing again.
type PlanHolderIndex struct {
	ByContext map[string]BranchHolderInventory
}

// BuildPlanHolderIndex builds one BranchHolderInventory per distinct
// canonical common dir among the identities in need, and publishes it under
// every context_id in need that resolves to that common dir. ids is the full
// PlanContextIdentities table this invocation established; need lists the
// context_ids that actually require a holder fact — a context_id this
// invocation never asks about costs no process at all.
func BuildPlanHolderIndex(ids PlanContextIdentities, need []string) PlanHolderIndex {
	byCommonDir := make(map[string]BranchHolderInventory)
	byContext := make(map[string]BranchHolderInventory, len(need))
	for _, contextID := range need {
		identity, ok := ids[contextID]
		if !ok {
			continue
		}
		inv, cached := byCommonDir[identity.CommonDir]
		if !cached {
			inv = BuildBranchHolderInventory(identity.RepoRoot)
			byCommonDir[identity.CommonDir] = inv
		}
		byContext[contextID] = inv
	}
	return PlanHolderIndex{ByContext: byContext}
}

// ============================================================================
// Fetch-effect resolution (§11.4-§11.7): remote ladder, refspecs, legacy
// remote/branch files, local-branch destinations and submodule recursion.
// ============================================================================

// configSubsectionByLastDot extracts the subsection of a normalized
// "prefix<subsection>.variable" config key (prefix already includes its own
// trailing dot, e.g. "remote.") by splitting on the LAST dot rather than the
// first. Git variable names are always dot-free, so the segment after the
// final dot is always the variable and everything between the fixed prefix
// and that final dot is the subsection — robust even when the subsection
// itself contains dots (a remote or URL-base name that does), which a
// first-dot split would truncate.
func configSubsectionByLastDot(key, prefix string) (string, bool) {
	if !strings.HasPrefix(key, prefix) {
		return "", false
	}
	rest := key[len(prefix):]
	last := strings.LastIndexByte(rest, '.')
	if last <= 0 {
		return "", false
	}
	return rest[:last], true
}

// remoteConfigNames returns every distinct config-defined remote name —
// every subsection of remote.<name>.* in the inventory — sorted for
// deterministic all-remotes iteration (§11.4's `fetch.all` effect) and for
// remotes[]'s own required name order.
func remoteConfigNames(inv GitConfigInventory) []string {
	seen := make(map[string]bool)
	for _, e := range inv.Entries {
		if name, ok := configSubsectionByLastDot(e.Key, "remote."); ok {
			seen[name] = true
		}
	}
	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// entriesUnderRemote returns every inventory entry whose key is
// remote.<name>.<anything>, in inventory order.
func entriesUnderRemote(inv GitConfigInventory, name string) []GitConfigEntry {
	var out []GitConfigEntry
	for _, e := range inv.Entries {
		if base, ok := configSubsectionByLastDot(e.Key, "remote."); ok && base == name {
			out = append(out, e)
		}
	}
	return out
}

// applyInsteadOf rewrites rawURL through every configured
// url.<base>.insteadOf entry, using the longest-matching insteadOf VALUE
// (the old prefix string) — confirmed against git-config(1): "Any URL that
// starts with this value will be rewritten to start, instead, with
// [the base]... When more than one insteadOf strings match, the longest
// match is used." Returns the rewritten URL and true when some entry
// matched, or rawURL unchanged and false otherwise.
func applyInsteadOf(inv GitConfigInventory, rawURL string) (string, bool) {
	bestLen := -1
	bestBase := ""
	for _, e := range inv.Entries {
		if !strings.HasSuffix(e.Key, ".insteadof") {
			continue
		}
		base, ok := configSubsectionByLastDot(e.Key, "url.")
		if !ok || !e.ValuePresent || e.Value == "" {
			continue
		}
		if !strings.HasPrefix(rawURL, e.Value) {
			continue
		}
		if len(e.Value) > bestLen {
			bestLen = len(e.Value)
			bestBase = base
		}
	}
	if bestLen < 0 {
		return rawURL, false
	}
	return bestBase + rawURL[bestLen:], true
}

// effectivePruneFlag resolves a per-remote boolean key (remote.<name>.prune
// or remote.<name>.pruneTags) with the ordinary Git fallback to its global
// counterpart (fetch.prune / fetch.pruneTags) when the per-remote key is
// unset or invalid — confirmed against git-config(1)'s PRUNING section.
func effectivePruneFlag(inv GitConfigInventory, perRemoteKey, globalKey string) bool {
	if entry, ok := finalOccurrence(inv, perRemoteKey); ok {
		if b, valid := parseGitConfigBool(entry.Value, entry.ValuePresent); valid {
			return b
		}
	}
	if entry, ok := finalOccurrence(inv, globalKey); ok {
		if b, valid := parseGitConfigBool(entry.Value, entry.ValuePresent); valid {
			return b
		}
	}
	return false
}

// effectiveTagOpt resolves remote.<name>.tagOpt, whose only two meaningful
// stored values are Git's own flag-string literals "--no-tags"/"--tags";
// any other value, or its absence, is the ordinary auto-following default.
// There is no global fallback key for tagOpt — it is exclusively a
// per-remote setting in Git itself.
func effectiveTagOpt(inv GitConfigInventory, name string) string {
	entry, ok := finalOccurrence(inv, "remote."+name+".tagopt")
	if !ok || !entry.ValuePresent {
		return "auto-follow"
	}
	switch strings.TrimSpace(entry.Value) {
	case "--no-tags":
		return "no-tags"
	case "--tags":
		return "tags"
	default:
		return "auto-follow"
	}
}

// decomposeRefspec parses one remote.<name>.fetch value into a PlanRefspec:
// an optional leading "^" marks it negative (never forced), an optional
// leading "+" marks it forced, and the remainder splits on the first ":"
// into src/dst — a refspec with no colon is its own src with an empty dst
// (Git's own shorthand for "fetch this ref, do not write a tracking ref").
func decomposeRefspec(raw string) PlanRefspec {
	r := PlanRefspec{Raw: raw}
	rest := raw
	switch {
	case strings.HasPrefix(rest, "^"):
		r.Negative = true
		rest = rest[1:]
	case strings.HasPrefix(rest, "+"):
		r.Forced = true
		rest = rest[1:]
	}
	if idx := strings.IndexByte(rest, ':'); idx >= 0 {
		r.Src = rest[:idx]
		r.Dst = rest[idx+1:]
	} else {
		r.Src = rest
	}
	return r
}

// refspecDestinationCovers reports whether a refspec destination pattern dst
// covers namespace ns (e.g. "refs/tags/" or "refs/heads/"), stripping Git's
// single trailing "*" wildcard to obtain a fixed prefix and treating
// coverage as a prefix relationship in either direction — refs/* covers
// refs/tags/, and refs/tags/v* also covers refs/tags/ as a narrower subset;
// both are legitimate "this refspec can write into ns" answers. Coverage is
// a predicate over the pattern, never a literal-prefix comparison.
func refspecDestinationCovers(dst, ns string) bool {
	prefix := strings.TrimSuffix(dst, "*")
	if prefix == "" {
		return true
	}
	return strings.HasPrefix(prefix, ns) || strings.HasPrefix(ns, prefix)
}

// refMatchesPattern reports whether a single, fully-qualified ref (e.g.
// "refs/heads/main") falls under a fetch destination pattern (e.g.
// "refs/heads/*" or an exact "refs/heads/main"). Git refspec destinations
// carry at most one trailing "*"; an exact pattern with none matches only
// itself.
func refMatchesPattern(dst, ref string) bool {
	if !strings.HasSuffix(dst, "*") {
		return dst == ref
	}
	prefix := strings.TrimSuffix(dst, "*")
	return strings.HasPrefix(ref, prefix)
}

// legacyRemoteFilePath is $GIT_DIR/remotes/<name> — read from the common
// dir, shared across every worktree exactly as config is (§11.4).
func legacyRemoteFilePath(commonDir, name string) string {
	return filepath.Join(commonDir, "remotes", name)
}

// readLegacyRemoteFile parses a legacy remotes/<name> file's "URL:" and
// "Pull:" lines. Git's own format is line-oriented, one directive per line;
// only the first "URL:" line and every "Pull:" line (a legacy refspec each)
// are meaningful to this feature.
func readLegacyRemoteFile(path string) (url string, refspecs []string, ok bool) {
	content, present, err := readSymlinkFreeFile(path, holderMarkerReadCap)
	if err != nil || !present {
		return "", nil, false
	}
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "URL:"):
			if url == "" {
				url = strings.TrimSpace(strings.TrimPrefix(line, "URL:"))
			}
		case strings.HasPrefix(line, "Pull:"):
			refspecs = append(refspecs, strings.TrimSpace(strings.TrimPrefix(line, "Pull:")))
		}
	}
	return url, refspecs, true
}

// legacyBranchFilePath is $GIT_DIR/branches/<name> — also read from the
// common dir.
func legacyBranchFilePath(commonDir, name string) string {
	return filepath.Join(commonDir, "branches", name)
}

// readLegacyBranchFile parses a legacy branches/<name> file: a single line
// "<url>[#<remote-branch>]". Fetching it implies a refspec that writes the
// LOCAL branch refs/heads/<name> — Git's own documented behaviour for this
// ancient mechanism — from the named remote branch, or HEAD when none is
// given.
func readLegacyBranchFile(path, name string) (url string, refspec string, ok bool) {
	content, present, err := readSymlinkFreeFile(path, holderMarkerReadCap)
	if err != nil || !present {
		return "", "", false
	}
	line := strings.TrimSpace(strings.SplitN(content, "\n", 2)[0])
	if line == "" {
		return "", "", false
	}
	remoteBranch := "HEAD"
	if idx := strings.IndexByte(line, '#'); idx >= 0 {
		remoteBranch = line[idx+1:]
		line = line[:idx]
	}
	url = strings.TrimSpace(line)
	refspec = fmt.Sprintf("%s:refs/heads/%s", remoteBranch, name)
	return url, refspec, true
}

// applyRemoteURL fills a remote's three URL members from a raw configured
// URL (possibly empty), applying insteadOf rewriting uniformly regardless of
// where the raw URL itself came from, and publishing url_source:
// name-verbatim exactly where there is no URL at all (§11.4) — a remote
// name is never published as a URL.
func applyRemoteURL(remote *PlanFetchRemote, inv GitConfigInventory, rawURL, sourceIfNoRewrite string) {
	if rawURL == "" {
		remote.URLSource = "name-verbatim"
		return
	}
	remote.URLConfigured = rawURL
	effective, rewritten := applyInsteadOf(inv, rawURL)
	remote.URLEffective = effective
	if rewritten {
		remote.URLSource = "insteadOf-rewritten"
	} else {
		remote.URLSource = sourceIfNoRewrite
	}
}

// ResolveHeadBranch measures fetch_effect.head_branch (§11.4): HEAD's short
// branch name in dir, or nil when that HEAD is detached, unborn or
// unreadable. It reuses the shipped gitCurrentBranch
// (internal/checkout_sync.go) rather than re-issuing the same
// `symbolic-ref --short HEAD` read.
func ResolveHeadBranch(dir string) *string {
	branch, err := gitCurrentBranch(dir)
	if err != nil || branch == "" {
		return nil
	}
	return &branch
}

// ResolveRemoteName resolves Git's own remote-resolution ladder against
// headBranch (§11.4): branch.<name>.remote for name == *headBranch, then
// the sole configured remote (gated by CapSoleRemoteFallback, Git >= 2.37),
// then "origin". remote.pushDefault is excluded — this is the FETCH ladder,
// never the push one. A nil headBranch (detached, unborn or unreadable
// HEAD) skips straight to the sole-remote rung, exactly as Git does for a
// detached HEAD.
func ResolveRemoteName(inv GitConfigInventory, headBranch *string, caps GitCapabilities) string {
	if headBranch != nil && *headBranch != "" {
		key := "branch." + *headBranch + ".remote"
		if entry, ok := finalOccurrence(inv, key); ok && entry.ValuePresent && entry.Value != "" {
			return entry.Value
		}
	}
	if caps.CapSoleRemoteFallback {
		names := remoteConfigNames(inv)
		if len(names) == 1 {
			return names[0]
		}
	}
	return "origin"
}

// buildConfigRemote builds one config-sourced fetch_effect.remotes[] row
// from every remote.<name>.* entry already isolated by entriesUnderRemote.
func buildConfigRemote(inv GitConfigInventory, name string, entries []GitConfigEntry) PlanFetchRemote {
	remote := PlanFetchRemote{Name: name, Source: "config"}
	var rawURL string
	for _, e := range entries {
		switch {
		case e.Key == "remote."+name+".url" && e.ValuePresent:
			rawURL = e.Value
		case e.Key == "remote."+name+".fetch" && e.ValuePresent:
			remote.Refspecs = append(remote.Refspecs, decomposeRefspec(e.Value))
		}
	}
	applyRemoteURL(&remote, inv, rawURL, "config")
	return remote
}

// ResolveFetchRemote resolves one remote definition by name (§11.4): a
// config-defined remote.<name>.* set, else a legacy $GIT_DIR/remotes/<name>
// file, else a legacy $GIT_DIR/branches/<name> file, else "no remote at
// all" (the second return is false). commonDir is where the legacy files
// live — shared across worktrees exactly as config is. prune/prune_tags/
// tag_opt are resolved uniformly regardless of which of the three sources
// answered, since Git's fetch.prune/fetch.pruneTags globals apply
// independently of how the remote itself was defined.
func ResolveFetchRemote(inv GitConfigInventory, commonDir, name string, caps GitCapabilities) (PlanFetchRemote, bool) {
	var remote PlanFetchRemote
	found := false

	switch {
	case len(entriesUnderRemote(inv, name)) > 0:
		remote = buildConfigRemote(inv, name, entriesUnderRemote(inv, name))
		found = true
	default:
		if url, refspecs, ok := readLegacyRemoteFile(legacyRemoteFilePath(commonDir, name)); ok {
			remote = PlanFetchRemote{Name: name, Source: "legacy-remotes"}
			for _, raw := range refspecs {
				remote.Refspecs = append(remote.Refspecs, decomposeRefspec(raw))
			}
			applyRemoteURL(&remote, inv, url, "legacy-file")
			found = true
		} else if url, refspec, ok := readLegacyBranchFile(legacyBranchFilePath(commonDir, name), name); ok {
			remote = PlanFetchRemote{Name: name, Source: "legacy-branches", Refspecs: []PlanRefspec{decomposeRefspec(refspec)}}
			applyRemoteURL(&remote, inv, url, "legacy-file")
			found = true
		}
	}
	if !found {
		return PlanFetchRemote{}, false
	}

	remote.TagOpt = effectiveTagOpt(inv, name)
	remote.Prune = effectivePruneFlag(inv, "remote."+name+".prune", "fetch.prune")
	if caps.CapPruneTags {
		remote.PruneTags = effectivePruneFlag(inv, "remote."+name+".prunetags", "fetch.prunetags")
	}
	return remote, true
}

// ============================================================================
// Local-branch destinations (§11.6)
// ============================================================================

// refspecsToPatterns extracts every positive (non-negative) refspec from
// refspecs whose destination covers refs/heads/**, in the refspecs' own
// configured order — local_branch_destinations.patterns[] never sorts
// across remotes, only groups by the remotes[] name-sorted iteration order
// its caller already fixes (§11.6).
func refspecsToPatterns(remoteName string, refspecs []PlanRefspec) []PlanFetchRefspecPattern {
	var patterns []PlanFetchRefspecPattern
	for _, r := range refspecs {
		if r.Negative {
			continue
		}
		if !refspecDestinationCovers(r.Dst, "refs/heads/") {
			continue
		}
		patterns = append(patterns, PlanFetchRefspecPattern{Remote: remoteName, Dst: r.Dst, Forced: r.Forced})
	}
	return patterns
}

// coveredLocalBranches enumerates repoRoot's own EXISTING local branches —
// never the remote's, which knowing would itself require the very fetch
// being planned — whose refs/heads/<branch> ref matches at least one
// pattern's destination, returning short names (refs/heads/ stripped,
// unsorted, uncapped). A read failure returns ok: false so the caller can
// publish the required null rather than a false empty list (§11.6, rank
// 5.06's "non-empty OR UNKNOWN" trigger).
func coveredLocalBranches(repoRoot string, patterns []PlanFetchRefspecPattern) (branches []string, ok bool) {
	if len(patterns) == 0 {
		return []string{}, true
	}
	out, err := runGit(repoRoot, "for-each-ref", "--format=%(refname)", "refs/heads/")
	if err != nil {
		return nil, false
	}
	var matched []string
	if out != "" {
		for _, ref := range strings.Split(out, "\n") {
			for _, p := range patterns {
				if refMatchesPattern(p.Dst, ref) {
					matched = append(matched, strings.TrimPrefix(ref, "refs/heads/"))
					break
				}
			}
		}
	}
	if matched == nil {
		matched = []string{}
	}
	return matched, true
}

// resolveLocalBranchDestinations resolves fetch_effect.local_branch_destinations
// (§11.6) from a resolved remote set's own positive refspecs. Patterns/
// Branches are nil only when the underlying computation genuinely could not
// be established — no contacted remote at all, or the local for-each-ref
// read itself failed — the specific "unknown" state rank 5.06 also triggers
// on; otherwise both are always a non-nil, possibly-empty slice. Held is nil
// specifically when holders.Available is false (the holder inventory itself
// could not be built), never merely because nothing is held. Held is
// computed from the FULL, uncapped branch list before the 200-entry display
// cap is applied to Branches, so a held branch beyond that cap is never
// silently dropped — "held[] ... never truncated" is a separate rule from
// "branches[] ... capped at 200".
func resolveLocalBranchDestinations(remotes []PlanFetchRemote, repoRoot string, holders BranchHolderInventory) PlanLocalBranchDestinations {
	if len(remotes) == 0 {
		return PlanLocalBranchDestinations{}
	}

	var patterns []PlanFetchRefspecPattern
	for _, remote := range remotes {
		patterns = append(patterns, refspecsToPatterns(remote.Name, remote.Refspecs)...)
	}
	if patterns == nil {
		patterns = []PlanFetchRefspecPattern{}
	}

	full, ok := coveredLocalBranches(repoRoot, patterns)
	if !ok {
		return PlanLocalBranchDestinations{Patterns: patterns}
	}

	var held []PlanBranchHold
	if holders.Available {
		held = []PlanBranchHold{}
		for _, branch := range full {
			if rec, isHeld := holders.ByBranch[branch]; isHeld {
				held = append(held, PlanBranchHold{Branch: branch, Worktree: rec.Worktree, Hold: string(rec.Mechanism)})
			}
		}
		sort.Slice(held, func(i, j int) bool {
			if held[i].Branch != held[j].Branch {
				return held[i].Branch < held[j].Branch
			}
			if held[i].Worktree != held[j].Worktree {
				return held[i].Worktree < held[j].Worktree
			}
			return held[i].Hold < held[j].Hold
		})
	}

	sort.Strings(full)
	branches := full
	truncated := false
	if len(branches) > 200 {
		branches = branches[:200]
		truncated = true
	}

	return PlanLocalBranchDestinations{
		Patterns:  patterns,
		Branches:  branches,
		Truncated: truncated,
		Held:      held,
	}
}

// ============================================================================
// Submodule recursion (§11.5)
// ============================================================================

// parseFetchRecurseSubmodulesValue applies fetch.recurseSubmodules's own
// grammar (§11.5): the case-insensitive literal "on-demand" wins outright;
// otherwise Git's ordinary --type=bool rule applies. ok is false for a
// value that matches neither.
func parseFetchRecurseSubmodulesValue(value string, present bool) (mode string, ok bool) {
	if present && strings.EqualFold(strings.TrimSpace(value), "on-demand") {
		return "on-demand", true
	}
	b, boolOK := parseGitConfigBool(value, present)
	if !boolOK {
		return "", false
	}
	if b {
		return "yes", true
	}
	return "no", true
}

// lastRecurseSubmodulesOccurrence finds whichever of fetch.recurseSubmodules
// and submodule.recurse has the LATEST position in the ordered inventory —
// genuinely interleaved across both keys, never "last occurrence of a
// single key checked in a fixed key precedence" (§11.5). It returns the
// entry together with the JSON mode_source name it corresponds to.
func lastRecurseSubmodulesOccurrence(inv GitConfigInventory) (entry GitConfigEntry, source string, found bool) {
	for _, e := range inv.Entries {
		switch e.Key {
		case "fetch.recursesubmodules":
			entry, source, found = e, "fetch.recurseSubmodules", true
		case "submodule.recurse":
			entry, source, found = e, "submodule.recurse", true
		}
	}
	return entry, source, found
}

// resolveConfigRecurseSubmodulesMode applies the correct grammar for
// whichever of the two keys won lastRecurseSubmodulesOccurrence:
// fetch.recurseSubmodules accepts boolean-or-"on-demand", while
// submodule.recurse is a plain boolean.
func resolveConfigRecurseSubmodulesMode(entry GitConfigEntry, source string) (string, bool) {
	if source == "fetch.recurseSubmodules" {
		return parseFetchRecurseSubmodulesValue(entry.Value, entry.ValuePresent)
	}
	b, ok := parseGitConfigBool(entry.Value, entry.ValuePresent)
	if !ok {
		return "", false
	}
	if b {
		return "yes", true
	}
	return "no", true
}

// gitmodulesContextRecurseSubmodules reads .gitmodules's own context-level
// [fetch] recurseSubmodules key through Git's three-source ladder — working
// tree file, then the index blob :.gitmodules, then HEAD:.gitmodules —
// never hand-parsing .gitmodules's own INI syntax (§11.5). ok is false only
// where every rung is absent/unreadable; the ladder stops at the first rung
// that answers.
func gitmodulesContextRecurseSubmodules(root string) (string, bool) {
	rungs := [][]string{
		{"config", "-f", ".gitmodules", "--get", "fetch.recursesubmodules"},
		{"config", "--blob=:.gitmodules", "--get", "fetch.recursesubmodules"},
		{"config", "--blob=HEAD:.gitmodules", "--get", "fetch.recursesubmodules"},
	}
	for _, args := range rungs {
		out, err := runGit(root, args...)
		if err != nil || out == "" {
			continue
		}
		if mode, ok := parseFetchRecurseSubmodulesValue(out, true); ok {
			return mode, true
		}
	}
	return "", false
}

// resolveSubmoduleMode resolves fetch_effect.submodule_recursion's mode and
// mode_source (§11.5): the last occurrence across fetch.recurseSubmodules
// and submodule.recurse in the ordered config; where neither occurs at all,
// .gitmodules's own context-level [fetch] recurseSubmodules through Git's
// three-source ladder; where that too answers nothing, "on-demand" from
// "default-on-demand". PlanSubmoduleRecursion.Mode/ModeSource are plain,
// non-nullable strings, so every context resolves to a concrete pair.
func resolveSubmoduleMode(inv GitConfigInventory, root string) (mode string, source string) {
	if entry, keySource, found := lastRecurseSubmodulesOccurrence(inv); found {
		if m, ok := resolveConfigRecurseSubmodulesMode(entry, keySource); ok {
			return m, keySource
		}
	}
	if m, ok := gitmodulesContextRecurseSubmodules(root); ok {
		return m, "gitmodules-fetch.recurseSubmodules"
	}
	return "on-demand", "default-on-demand"
}

// submoduleReachStoreCap and submoduleReachDepthCap are §11.5's exact
// caps: 50 stores per context, depth 3. Hitting either, or an unreadable
// member, yields reach: unknown and stops the walk; the list never claims
// completeness in that case.
const (
	submoduleReachStoreCap = 50
	submoduleReachDepthCap = 3
)

// listPresentGitlinks lists every gitlink (mode 160000) tree entry in
// root's own index — every "present" submodule regardless of whether it is
// configured in .gitmodules or currently populated (§11.5's candidate set:
// "every present gitlink submodule, whether or not it is active").
//
// The inventory is read through `git ls-files --stage -z` and raw-byte
// plumbing. `-z` is not optional: without it Git applies core.quotePath and
// rewrites every non-ASCII or special byte into a C-quoted, backslash-
// escaped rendering, so a submodule at `libs/ünïcode` or one whose path
// contains a tab, a newline or a quote would either be silently dropped or
// recorded under a name that no longer names a directory on disk — turning
// a populated submodule into an invisible one and defeating the fail-closed
// reach walk that consumes this list. Records are NUL-delimited, so the
// only in-record separator is the single TAB that Git guarantees between
// the stage metadata and the path, and every path byte survives verbatim.
func listPresentGitlinks(root string) ([]string, error) {
	out, err := runGitRaw(root, "ls-files", "--stage", "-z")
	if err != nil {
		return nil, err
	}
	var paths []string
	for _, record := range bytes.Split(out, []byte{0}) {
		if len(record) == 0 {
			continue // the trailing NUL terminator, never a real entry
		}
		tab := bytes.IndexByte(record, '\t')
		if tab < 0 {
			continue
		}
		meta := strings.Fields(string(record[:tab]))
		if len(meta) < 1 || meta[0] != "160000" {
			continue
		}
		path := string(record[tab+1:])
		if path == "" {
			continue
		}
		paths = append(paths, path)
	}
	return paths, nil
}

// submodulePopulated reports whether subRoot's own .git artefact is present
// as a plain directory or a gitdir-pointer file — never following a
// symlinked .git, which is treated as unreadable (err != nil) rather than
// silently guessed at either way.
func submodulePopulated(subRoot string) (populated bool, err error) {
	gitPath := filepath.Join(subRoot, ".git")
	info, statErr := os.Lstat(gitPath)
	if statErr != nil {
		if errors.Is(statErr, fs.ErrNotExist) {
			return false, nil
		}
		return false, statErr
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return false, fmt.Errorf("refusing to follow symlinked artefact %s", gitPath)
	}
	return true, nil
}

// walkSubmoduleReach enumerates every present gitlink submodule reachable
// from repoRoot — active or not — recursing into each one's own working
// tree up to depth 3 and 50 total stores visited (§11.5). Hitting either
// cap, or failing to read a present gitlink's own submodule set or
// populated-ness, stops the walk and reports reach: unknown; the returned
// list is then a floor on what is present, never a claim of completeness.
// reach: none is reported exactly when the walk completes and finds zero
// present gitlinks; reach: bounded when it completes having found at least
// one.
func walkSubmoduleReach(repoRoot string) ([]PlanSubmoduleEntry, string) {
	var submodules []PlanSubmoduleEntry
	visited := 0
	unknown := false

	var walk func(root, prefix string, depth int)
	walk = func(root, prefix string, depth int) {
		if unknown {
			return
		}
		gitlinks, err := listPresentGitlinks(root)
		if err != nil {
			unknown = true
			return
		}
		for _, gl := range gitlinks {
			if visited >= submoduleReachStoreCap {
				unknown = true
				return
			}
			visited++
			path := gl
			if prefix != "" {
				path = prefix + "/" + gl
			}
			submodules = append(submodules, PlanSubmoduleEntry{Path: path})

			subRoot := filepath.Join(root, gl)
			populated, popErr := submodulePopulated(subRoot)
			if popErr != nil {
				unknown = true
				return
			}
			if !populated {
				continue // nothing further reachable from an unpopulated submodule
			}
			if depth >= submoduleReachDepthCap {
				// A populated submodule at the depth cap may itself contain
				// further gitlinks this walk is not permitted to examine.
				unknown = true
				return
			}
			walk(subRoot, path, depth+1)
			if unknown {
				return
			}
		}
	}
	walk(repoRoot, "", 1)

	if submodules == nil {
		submodules = []PlanSubmoduleEntry{}
	}
	sort.Slice(submodules, func(i, j int) bool { return submodules[i].Path < submodules[j].Path })

	switch {
	case unknown:
		return submodules, "unknown"
	case len(submodules) == 0:
		return submodules, "none"
	default:
		return submodules, "bounded"
	}
}

// ResolveSubmoduleRecursion resolves fetch_effect.submodule_recursion in
// full (§11.5): the context mode/mode_source, then — for every mode except
// "no", which never recurses into anything — the bounded reach walk over
// every present gitlink, whether or not it is active. A mode: no context
// short-circuits to reach: none with an empty submodules[] and issues no
// git process at all: nothing would be visited by a real fetch under it.
func ResolveSubmoduleRecursion(inv GitConfigInventory, root string) PlanSubmoduleRecursion {
	mode, source := resolveSubmoduleMode(inv, root)
	if mode == "no" {
		return PlanSubmoduleRecursion{Mode: mode, ModeSource: source, Reach: "none", Submodules: []PlanSubmoduleEntry{}}
	}
	submodules, reach := walkSubmoduleReach(root)
	return PlanSubmoduleRecursion{Mode: mode, ModeSource: source, Reach: reach, Submodules: submodules}
}

// ============================================================================
// ResolveFetchEffect — the §11.4 orchestrator
// ============================================================================

// ResolveFetchEffect resolves fetch_effect (§11.4-§11.7) in full for one
// execution context: head_branch, the remote set (a single resolved remote,
// or — where fetch.all is effectively configured true, gated by
// CapFetchAll, §16 — every configured remote), the five may_* booleans,
// local-branch destinations and submodule recursion. commonDir is where
// legacy remote/branch files and per-worktree hold state live; holders is
// this context's already-built BranchHolderInventory (§7.9), never rebuilt
// here. It serves both workspace modes identically: a caller in either mode
// supplies its own resolved repoRoot/commonDir/holders for the context it
// is evaluating.
func ResolveFetchEffect(inv GitConfigInventory, repoRoot, commonDir string, caps GitCapabilities, holders BranchHolderInventory) PlanFetchEffect {
	headBranch := ResolveHeadBranch(repoRoot)

	all := false
	if caps.CapFetchAll {
		if entry, ok := finalOccurrence(inv, "fetch.all"); ok {
			if b, valid := parseGitConfigBool(entry.Value, entry.ValuePresent); valid {
				all = b
			}
		}
	}

	var remotes []PlanFetchRemote
	if all {
		for _, name := range remoteConfigNames(inv) {
			if remote, ok := ResolveFetchRemote(inv, commonDir, name, caps); ok {
				remotes = append(remotes, remote)
			}
		}
	} else if name := ResolveRemoteName(inv, headBranch, caps); name != "" {
		if remote, ok := ResolveFetchRemote(inv, commonDir, name, caps); ok {
			remotes = append(remotes, remote)
		}
	}
	sort.Slice(remotes, func(i, j int) bool { return remotes[i].Name < remotes[j].Name })
	contacted := len(remotes) > 0

	effect := PlanFetchEffect{
		All:                all,
		Contacted:          contacted,
		HeadBranch:         headBranch,
		SubmoduleRecursion: ResolveSubmoduleRecursion(inv, repoRoot),
		Remotes:            remotes,
	}

	if !contacted {
		return effect
	}

	for _, remote := range remotes {
		if remote.Prune {
			effect.MayDeleteRefs = true
		}
		tagCovering := false
		forcedTagCovering := false
		headCovering := false
		for _, r := range remote.Refspecs {
			if r.Negative {
				continue
			}
			if refspecDestinationCovers(r.Dst, "refs/tags/") {
				tagCovering = true
				if r.Forced {
					forcedTagCovering = true
				}
			}
			if refspecDestinationCovers(r.Dst, "refs/heads/") {
				headCovering = true
			}
		}
		if remote.Prune && (remote.PruneTags || tagCovering) {
			effect.MayDeleteTags = true
		}
		if forcedTagCovering {
			effect.MayClobberTags = true
		}
		if headCovering {
			effect.MayUpdateLocalBranches = true
		}
		if remote.Prune && headCovering {
			effect.MayDeleteLocalBranches = true
		}
	}

	effect.LocalBranchDestinations = resolveLocalBranchDestinations(remotes, repoRoot, holders)
	return effect
}

// ============================================================================
// Push read-helpers (§14.1a) — reused by the (separately owned) push-fact
// producers MeasurePushRemoteFacts / RefreshPushTrackingRefs, which resolve
// a remote and its refspecs exactly as fetch-effect resolution does and
// therefore share this file's ladder rather than re-deriving it.
// ============================================================================

// ReadRemoteTrackingRefs reads every refs/remotes/<remoteName>/* ref via one
// `for-each-ref`, keyed by the short name after that prefix — the read
// MeasurePushRemoteFacts / RefreshPushTrackingRefs use for
// PlanPushRemoteFacts.TrackingRefs (§14.1a). A repository with no such refs
// yet returns an empty, non-nil map, never an error.
func ReadRemoteTrackingRefs(root, remoteName string) (map[string]string, error) {
	prefix := "refs/remotes/" + remoteName + "/"
	out, err := runGit(root, "for-each-ref", "--format=%(refname)%00%(objectname)", prefix)
	if err != nil {
		return nil, err
	}
	refs := make(map[string]string)
	if out == "" {
		return refs, nil
	}
	for _, line := range strings.Split(out, "\n") {
		fields := strings.SplitN(line, "\x00", 2)
		if len(fields) != 2 {
			continue
		}
		name := strings.TrimPrefix(fields[0], prefix)
		if name == "" {
			continue
		}
		refs[name] = fields[1]
	}
	return refs, nil
}

// ============================================================================
// Lstat-first artefact helpers (§12.5/§12.5a) — shared by both
// rebase_plan_state.go inspectors (InspectCheckoutPlanState,
// InspectExternalPlanState), which own the PlanPresence/PlanUnreadableReason
// enums this outcome maps onto; kept independent of those types here so
// this file has no forward reference to the one written after it.
// ============================================================================

// ArtefactReadOutcome is the one-Lstat-then-at-most-one-read classification
// every state artefact read reduces to (§12.5's "exactly one read per
// artefact path" rule): Exists/IsSymlink/IsRegular are the raw Lstat facts —
// a symlinked path is reported here and MUST NEVER be opened or followed by
// a caller; NotRegular/TooLarge distinguish the two ways a real, non-symlink
// path can still fail to be a readable document; Content/OK report a
// completed read; Err carries any other Lstat/Open/Read failure (an
// io-error in the caller's own vocabulary).
type ArtefactReadOutcome struct {
	Exists     bool
	IsSymlink  bool
	IsRegular  bool
	NotRegular bool
	TooLarge   bool
	Content    string
	OK         bool
	Err        error
}

// ReadArtefactPath performs the one Lstat-first, symlink-refusing,
// size-capped read every rebase_plan_state.go inspector needs for one
// artefact path, reporting every distinction its PlanFilePresence/
// PlanUnreadableReason mapping requires directly rather than making the
// caller re-parse an error string. A missing path (fs.ErrNotExist) is the
// zero value — Exists: false, no error — distinguishing "absent" from every
// other outcome without the caller needing errors.Is at every call site.
func ReadArtefactPath(path string, maxBytes int64) ArtefactReadOutcome {
	info, err := os.Lstat(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return ArtefactReadOutcome{}
		}
		return ArtefactReadOutcome{Err: err}
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return ArtefactReadOutcome{Exists: true, IsSymlink: true}
	}
	if !info.Mode().IsRegular() {
		return ArtefactReadOutcome{Exists: true, NotRegular: true}
	}
	if info.Size() > maxBytes {
		return ArtefactReadOutcome{Exists: true, IsRegular: true, TooLarge: true}
	}
	data, readErr := os.ReadFile(path)
	if readErr != nil {
		return ArtefactReadOutcome{Exists: true, IsRegular: true, Err: readErr}
	}
	return ArtefactReadOutcome{Exists: true, IsRegular: true, Content: string(data), OK: true}
}

// ProbeCommitExists is §13.3a rule 6's ONE existence probe: whether sha
// still names a commit object in dir. It is a single
// `rev-parse --verify <sha>^{commit}` process and nothing else — never a
// second resolution of a ref the executor will not resolve.
func ProbeCommitExists(dir, sha string) (bool, error) {
	if dir == "" || sha == "" {
		return false, fmt.Errorf("probe commit exists: empty dir or sha")
	}
	if _, err := runGit(dir, "rev-parse", "--verify", sha+"^{commit}"); err != nil {
		return false, nil
	}
	return true, nil
}

