		wtApply := filepath.Join(t.TempDir(), "wt-apply")
		gitInTest(t, repo, "worktree", "add", wtApply, "feat-apply")
		if _, err := runGitConflict(wtApply, "rebase", "--apply", "main"); err == nil {
