			t.Fatalf("ByBranch[feat-apply] = %+v ok=%v, want HoldRebaseApply", rec, ok)
		}
		if rec, ok := inv.ByBranch["feat-bisect"]; !ok || rec.Mechanism != HoldBisect {
			t.Fatalf("ByBranch[feat-bisect] = %+v ok=%v, want HoldBisect", rec, ok)
