	t.Run("PrunableDeletedWorktreeStillHoldsItsBranch", func(t *testing.T) {
		repo := rppRepo(t)
		wtPath := filepath.Join(t.TempDir(), "wt")
		gitInTest(t, repo, "branch", "feature")
