func rpnCaps() GitCapabilities {
	caps, _, err := ProbeGitCapabilities()
	if err != nil {
		panic(err)
	}
	return caps
}

func TestRebasePlanner_ResolvePushContext(t *testing.T) {
	t.Run("ResolvesIdentityHeadBranchAndRemoteOverARealRepo", func(t *testing.T) {
		repo := rppRepo(t)
		gitInTest(t, repo, "remote", "add", "origin", "https://example.invalid/repo.git")
		inv := ProbeGitConfigInventory(repo)

		ctx, identity, remoteName, err := ResolvePushContext(repo, "cli-flag", "materialized", inv, rpnCaps())
		if err != nil {
			t.Fatalf("ResolvePushContext: %v", err)
		}
		if identity.ContextID == "" || identity.RepoRoot == "" {
			t.Fatalf("identity = %+v, want populated ContextID/RepoRoot", identity)
		}
		if ctx.ContextID == nil || *ctx.ContextID != identity.ContextID {
			t.Fatalf("ctx.ContextID = %v, want %q", ctx.ContextID, identity.ContextID)
		}
		if ctx.RepoRoot != identity.RepoRoot {
			t.Fatalf("ctx.RepoRoot = %q, want %q", ctx.RepoRoot, identity.RepoRoot)
		}
		if ctx.Source != "cli-flag" {
			t.Fatalf("ctx.Source = %q, want the passed-through cli-flag", ctx.Source)
		}
		if ctx.Materialization != "materialized" {
			t.Fatalf("ctx.Materialization = %q, want the passed-through materialized", ctx.Materialization)
		}
		if remoteName != "origin" {
			t.Fatalf("remoteName = %q, want origin", remoteName)
		}
	})

	t.Run("PropagatesEstablishContextIdentityErrorWithZeroResults", func(t *testing.T) {
		notRepo := rppNotARepo(t)
		ctx, identity, remoteName, err := ResolvePushContext(notRepo, "cli-flag", "materialized", GitConfigInventory{}, rpnCaps())
		if err == nil {
			t.Fatal("expected an error outside any repository")
		}
		if ctx != (PlanPushContext{}) || identity != (PlanContextIdentity{}) || remoteName != "" {
			t.Fatalf("expected every result zeroed on error, got ctx=%+v identity=%+v remoteName=%q", ctx, identity, remoteName)
		}
	})
}

func TestRebasePlanner_MeasurePushRemoteFacts(t *testing.T) {
	t.Run("RemoteFoundPopulatesRefspecsAndLeavesTrackingFieldsAtZeroValue", func(t *testing.T) {
		repo := rppRepo(t)
		gitInTest(t, repo, "remote", "add", "origin", "https://example.invalid/repo.git")
		contextID := "ctx-1"
		inv := ProbeGitConfigInventory(repo)

		facts := MeasurePushRemoteFacts(&contextID, repo, "origin", inv, rpnCaps())
		if facts.ContextID != &contextID {
			t.Fatal("expected the same *string pointer to be threaded through verbatim")
		}
		if facts.CommonDir != repo {
			t.Fatalf("CommonDir = %q, want %q", facts.CommonDir, repo)
		}
		if facts.RemoteName != "origin" {
			t.Fatalf("RemoteName = %q, want origin", facts.RemoteName)
		}
		if !facts.MappingReadOK {
			t.Fatal("expected MappingReadOK=true")
		}
		if !facts.RemoteExists {
			t.Fatal("expected RemoteExists=true")
		}
		if len(facts.FetchRefspecs) == 0 {
			t.Fatal("expected at least one default fetch refspec for a newly added remote")
		}
		if facts.TrackingPhase != "not-applicable" {
			t.Fatalf("TrackingPhase = %q, want not-applicable (RefreshPushTrackingRefs alone sets it further)", facts.TrackingPhase)
		}
		if facts.TrackingReadOK {
			t.Fatal("expected TrackingReadOK to stay false: only RefreshPushTrackingRefs ever sets it")
		}
		if facts.TrackingRefs != nil {
			t.Fatal("expected TrackingRefs to stay nil until RefreshPushTrackingRefs runs")
		}
		if facts.FetchedThisRun {
			t.Fatal("expected FetchedThisRun to stay false")
		}
	})

	t.Run("RemoteNotFoundStillReportsMappingReadOK", func(t *testing.T) {
		repo := rppRepo(t)
		contextID := "ctx-1"
		facts := MeasurePushRemoteFacts(&contextID, repo, "ghost", ProbeGitConfigInventory(repo), rpnCaps())
		if !facts.MappingReadOK {
			t.Fatal("expected MappingReadOK=true even when the remote itself does not exist")
		}
		if facts.RemoteExists {
			t.Fatal("expected RemoteExists=false")
		}
		if facts.FetchRefspecs == nil || len(facts.FetchRefspecs) != 0 {
			t.Fatalf("FetchRefspecs = %v, want a non-nil empty slice when the remote was not found", facts.FetchRefspecs)
		}
	})

	// §22.24-adjacent, §14.1a rule 5a: MappingReadOK is a claim about TWO
	// halves — an established context identity and a READABLE ordered config
	// inventory. Either one missing is the `unknown` lease cell, never the
	// null-OID `absent` one.
	t.Run("UnreadableInventoryIsNotAReadMapping", func(t *testing.T) {
		repo := rppRepo(t)
		contextID := "ctx-1"
		facts := MeasurePushRemoteFacts(&contextID, repo, "origin", GitConfigInventory{Available: false}, rpnCaps())
		if facts.MappingReadOK {
			t.Fatal("MappingReadOK = true over an UNREADABLE inventory: nothing was read")
		}
		if facts.RemoteExists {
			t.Fatal("RemoteExists = true over an unreadable inventory")
		}
		if facts.FetchRefspecs == nil || len(facts.FetchRefspecs) != 0 {
			t.Fatalf("FetchRefspecs = %v, want a non-nil empty slice", facts.FetchRefspecs)
		}
		// Round trip: those facts really do produce §14.2's `unknown` cell.
		lease := ResolvePushLease(facts, "main")
		want := PlanLease{Mode: "implicit-remote-tracking", Expectation: "unknown", ExpectedSHAFreshness: "possibly-stale"}
		if lease != want {
			t.Fatalf("lease = %+v, want the cell-5 unknown lease %+v", lease, want)
		}
	})

	t.Run("UnestablishedContextIdentityIsNotAReadMapping", func(t *testing.T) {
		repo := rppRepo(t)
		gitInTest(t, repo, "remote", "add", "origin", "https://example.invalid/repo.git")
		facts := MeasurePushRemoteFacts(nil, repo, "origin", ProbeGitConfigInventory(repo), rpnCaps())
		if facts.MappingReadOK {
			t.Fatal("MappingReadOK = true with a nil ContextID: the context was never established")
		}
		if lease := ResolvePushLease(facts, "main"); lease.Expectation != "unknown" {
			t.Fatalf("lease.Expectation = %q, want unknown", lease.Expectation)
		}
	})

	// A REAL probe failure, not an injected struct: the inventory is read
	// from a directory that is not a repository at all.
	t.Run("RealInventoryProbeFailureRoundTripsToTheUnknownCell", func(t *testing.T) {
		// A directory that does not exist at all: `git -C <path> config
		// --list --show-scope -z` cannot run there, so the ordered read
		// really fails rather than being injected as failed.
		missing := filepath.Join(rppNotARepo(t), "no-such-directory")
		inv := ProbeGitConfigInventory(missing)
		if inv.Available {
			t.Fatalf("the ordered inventory must fail for a nonexistent directory, got %+v", inv)
		}
		notRepo := missing
		contextID := "ctx-1"
		facts := MeasurePushRemoteFacts(&contextID, notRepo, "origin", inv, rpnCaps())
		if facts.MappingReadOK {
			t.Fatalf("MappingReadOK = true over a REAL failed inventory read: %+v", facts)
		}
		lease := ResolvePushLease(facts, "main")
		if lease.Expectation != "unknown" || lease.ExpectedRef != nil || lease.ExpectedSHA != nil {
			t.Fatalf("lease = %+v, want the unknown cell with null ref and sha", lease)
		}
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("freshness = %q, want possibly-stale", lease.ExpectedSHAFreshness)
		}
	})
}

func TestRebasePlanner_RefreshPushTrackingRefs(t *testing.T) {
	// fetchedOK builds a PlanFetchOutcome describing one attempted, successful
	// fetch that contacted `origin` in commonDir.
	fetchedOK := func(commonDir string) PlanFetchOutcome {
		return PlanFetchOutcome{
			Applies: true, Attempted: true,
			Repos: []PlanFetchRepoResult{{
				Attempted: true, OK: true, ContextCommonDir: commonDir,
				Effect: &PlanFetchEffect{Contacted: true, Remotes: []PlanFetchRemote{{Name: "origin"}}},
			}},
		}
	}

	t.Run("NonApplicableFactsAreNeverMeasuredOrRefreshed", func(t *testing.T) {
		in := PlanPushFacts{Applies: false, Phase: "not-applicable"}
		got := RefreshPushTrackingRefs(in, fetchedOK("anything"))
		if got.Applies || got.Phase != "not-applicable" || got.Remotes != nil {
			t.Fatalf("facts = %+v, want the not-applicable value passed through unchanged", got)
		}
	})

	t.Run("PostFetchReadOfAFetchedContextIsFreshAndCarriesTheRefs", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		sha := rppHeadSHA(t, repo)
		gitInTest(t, repo, "update-ref", "refs/remotes/origin/main", sha)

		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: repo, CommonDir: commonDir}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: commonDir, RemoteName: "origin",
				MappingReadOK: true, TrackingPhase: "not-applicable",
			}},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK(commonDir))
		if got.Phase != "post-fetch" {
			t.Fatalf("PlanPushFacts.Phase = %q, want post-fetch", got.Phase)
		}
		rf := got.Remotes[""]
		if !rf.TrackingReadOK {
			t.Fatal("expected TrackingReadOK=true")
		}
		if rf.TrackingPhase != "post-fetch" {
			t.Fatalf("TrackingPhase = %q, want post-fetch", rf.TrackingPhase)
		}
		if !rf.FetchedThisRun {
			t.Fatal("expected FetchedThisRun=true: mapping read, inventory read, post-fetch, and origin was contacted in this common dir")
		}
		if rf.TrackingRefs["main"] != sha {
			t.Fatalf("TrackingRefs[main] = %q, want %q", rf.TrackingRefs["main"], sha)
		}
	})

	t.Run("TwoLinkedWorktreesOfOneRepositoryAreBothFreshAfterOneFetch", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		sha := rppHeadSHA(t, repo)
		gitInTest(t, repo, "update-ref", "refs/remotes/origin/main", sha)
		linked := filepath.Join(t.TempDir(), "linked")
		gitInTest(t, repo, "worktree", "add", "-b", "linked", linked)

		// Two DIFFERENT context ids (they hash different top levels) sharing
		// ONE canonical common dir: §14.1a rule 8's conjunct iv is exactly
		// why both are refreshed by the single collapsed fetch.
		a, b := "ctx-main", "ctx-linked"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{
				a: {ContextID: a, RepoRoot: repo, CommonDir: commonDir},
				b: {ContextID: b, RepoRoot: linked, CommonDir: commonDir},
			},
			Remotes: map[string]PlanPushRemoteFacts{
				"a": {ContextID: &a, CommonDir: commonDir, RemoteName: "origin", MappingReadOK: true},
				"b": {ContextID: &b, CommonDir: commonDir, RemoteName: "origin", MappingReadOK: true},
			},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK(commonDir))
		for _, token := range []string{"a", "b"} {
			rf := got.Remotes[token]
			if !rf.FetchedThisRun || rf.TrackingPhase != "post-fetch" || rf.TrackingRefs["main"] != sha {
				t.Fatalf("token %q: %+v, want post-fetch/fresh with the shared origin/main baseline", token, rf)
			}
		}
	})

	t.Run("AContextWhoseRemoteIsUpstreamStaysPossiblyStaleEvenAfterItsOwnFetch", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: repo, CommonDir: commonDir}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: commonDir, RemoteName: "upstream", MappingReadOK: true,
			}},
		}
		upstreamOnly := PlanFetchOutcome{
			Applies: true, Attempted: true,
			Repos: []PlanFetchRepoResult{{
				Attempted: true, OK: true, ContextCommonDir: commonDir,
				Effect: &PlanFetchEffect{Contacted: true, Remotes: []PlanFetchRemote{{Name: "upstream"}}},
			}},
		}
		got := RefreshPushTrackingRefs(in, upstreamOnly)
		rf := got.Remotes[""]
		if rf.TrackingPhase != "post-fetch" {
			t.Fatalf("TrackingPhase = %q, want post-fetch (a child really ran)", rf.TrackingPhase)
		}
		if rf.FetchedThisRun {
			t.Fatal("expected FetchedThisRun=false: origin's baseline was never refreshed, only upstream's")
		}
	})

	t.Run("NoFetchChildStampsPlanPointAndNeverFresh", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: repo, CommonDir: commonDir}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: commonDir, RemoteName: "origin", MappingReadOK: true,
			}},
		}
		got := RefreshPushTrackingRefs(in, PlanFetchOutcome{Applies: true})
		if got.Phase != "plan-point" {
			t.Fatalf("PlanPushFacts.Phase = %q, want plan-point", got.Phase)
		}
		rf := got.Remotes[""]
		if rf.TrackingPhase != "plan-point" || rf.FetchedThisRun {
			t.Fatalf("remote facts = %+v, want a plan-point read that is never fresh", rf)
		}
		if !rf.TrackingReadOK {
			t.Fatal("a plan-point read is still a REAL read of the current refs")
		}
	})

	t.Run("UnreadableInventoryStampsUnreadAndNeverFresh", func(t *testing.T) {
		notRepo := rppNotARepo(t)
		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: notRepo, CommonDir: "common"}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: "common", RemoteName: "origin", MappingReadOK: true,
			}},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK("common"))
		rf := got.Remotes[""]
		if rf.TrackingReadOK {
			t.Fatal("expected TrackingReadOK=false outside any repository")
		}
		if rf.TrackingPhase != "unread" {
			t.Fatalf("TrackingPhase = %q, want unread (first rung of the ladder)", rf.TrackingPhase)
		}
		if rf.FetchedThisRun {
			t.Fatal("expected FetchedThisRun=false: an unread inventory can never be fresh")
		}
		if rf.TrackingRefs != nil {
			t.Fatalf("TrackingRefs = %v, want nil on a failed read", rf.TrackingRefs)
		}
	})

	t.Run("ANilContextIDReadsNothingAndKeepsTheUnknownCell", func(t *testing.T) {
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				CommonDir: "common", RemoteName: "origin", MappingReadOK: false,
			}},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK("common"))
		rf := got.Remotes[""]
		if rf.TrackingReadOK || rf.TrackingRefs != nil || rf.FetchedThisRun {
			t.Fatalf("remote facts = %+v, want a context that read NOTHING", rf)
		}
		if rf.TrackingPhase != "unread" {
			t.Fatalf("TrackingPhase = %q, want unread", rf.TrackingPhase)
		}
	})
}

func TestRebasePlanner_PushContextRefreshed(t *testing.T) {
	baseEffect := func(contacted bool, remotes ...string) *PlanFetchEffect {
		var rs []PlanFetchRemote
		for _, r := range remotes {
			rs = append(rs, PlanFetchRemote{Name: r})
		}
		return &PlanFetchEffect{Contacted: contacted, Remotes: rs}
	}
	row := func(attempted, ok bool, commonDir string, effect *PlanFetchEffect) PlanFetchOutcome {
		return PlanFetchOutcome{Applies: true, Attempted: attempted, Repos: []PlanFetchRepoResult{
			{Attempted: attempted, OK: ok, ContextCommonDir: commonDir, Effect: effect},
		}}
	}

	t.Run("EmptyCommonDirIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", baseEffect(true, "origin")), "") {
			t.Fatal("expected false: an unmeasured common dir can never join")
		}
	})

	t.Run("NotAttemptedIsFalse", func(t *testing.T) {
		if PushContextRefreshed(PlanFetchOutcome{Applies: true}, "common") {
			t.Fatal("expected false when fetch was never attempted")
		}
	})

	t.Run("MatchingContactedOriginRowIsTrue", func(t *testing.T) {
		if !PushContextRefreshed(row(true, true, "common", baseEffect(true, "origin")), "common") {
			t.Fatal("expected true for a matching, contacted, OK origin row")
		}
	})

	t.Run("DifferentCommonDirIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "other", baseEffect(true, "origin")), "common") {
			t.Fatal("expected false: common dir does not match")
		}
	})

	t.Run("NotContactedIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", baseEffect(false, "origin")), "common") {
			t.Fatal("expected false: effect was not Contacted")
		}
	})

	t.Run("OriginNotAmongEffectRemotesIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", baseEffect(true, "upstream")), "common") {
			t.Fatal("expected false: origin is not among the effect's remotes")
		}
	})

	t.Run("RepoAttemptedButNotOKIsSkipped", func(t *testing.T) {
		if PushContextRefreshed(row(true, false, "common", baseEffect(true, "origin")), "common") {
			t.Fatal("expected false: repo row was not OK")
		}
	})

	t.Run("NilEffectIsSkipped", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", nil), "common") {
			t.Fatal("expected false: nil Effect")
		}
	})

	t.Run("JoinIsOnTheCANONICALCommonDirNotTheRawString", func(t *testing.T) {
		dir := t.TempDir()
		nested := filepath.Join(dir, "a", "..", "a")
		if err := os.MkdirAll(filepath.Join(dir, "a"), 0o755); err != nil {
			t.Fatal(err)
		}
		fetched := row(true, true, nested, baseEffect(true, "origin"))
		if !PushContextRefreshed(fetched, filepath.Join(dir, "a")) {
			t.Fatal("expected true: the two spellings canonicalize to the same directory")
		}
	})
}

func TestRebasePlanner_MapThroughRefspec(t *testing.T) {
	t.Run("NonMatchingSrcFails", func(t *testing.T) {
		_, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/release/*", Dst: "refs/remotes/origin/*"}, "refs/heads/main")
		if ok {
			t.Fatal("expected no match")
		}
	})

	t.Run("ExactNonWildcardPatternMapsToTheLiteralDst", func(t *testing.T) {
		dst, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/main", Dst: "refs/remotes/origin/main"}, "refs/heads/main")
		if !ok || dst != "refs/remotes/origin/main" {
			t.Fatalf("dst=%q ok=%v, want refs/remotes/origin/main/true", dst, ok)
		}
	})

	t.Run("WildcardPatternSubstitutesTheMatchedSuffix", func(t *testing.T) {
		dst, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/*", Dst: "refs/remotes/origin/*"}, "refs/heads/feature-x")
		if !ok || dst != "refs/remotes/origin/feature-x" {
			t.Fatalf("dst=%q ok=%v, want refs/remotes/origin/feature-x/true", dst, ok)
		}
	})

	t.Run("WildcardSrcWithNonWildcardDstUsesTheLiteralDst", func(t *testing.T) {
		dst, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/*", Dst: "refs/remotes/origin/pinned"}, "refs/heads/anything")
		if !ok || dst != "refs/remotes/origin/pinned" {
			t.Fatalf("dst=%q ok=%v, want refs/remotes/origin/pinned/true (dst has no trailing * to substitute into)", dst, ok)
		}
	})
}

// TestRebasePlanner_ResolvePushLease drives §14.2's five closed cells, one
// subtest per cell, asserting the WHOLE PlanLease value (all five members) so
// no cell can be satisfied by a partially-correct projection.
func TestRebasePlanner_ResolvePushLease(t *testing.T) {
	wildcardRefspec := PlanRefspec{Src: "refs/heads/*", Dst: "refs/remotes/origin/*"}
	ref := func(s string) *string { return &s }

	t.Run("Cell5MappingUnreadableIsTheOnlyUnknownCell", func(t *testing.T) {
		lease := ResolvePushLease(PlanPushRemoteFacts{MappingReadOK: false}, "main")
		want := PlanLease{Mode: "implicit-remote-tracking", Expectation: "unknown", ExpectedSHAFreshness: "possibly-stale"}
		if lease != want {
			t.Fatalf("lease = %+v, want %+v", lease, want)
		}
	})

	t.Run("Cell4MappingReadButNoPositiveMappingIsAbsentAndFresh", func(t *testing.T) {
		lease := ResolvePushLease(PlanPushRemoteFacts{MappingReadOK: true, FetchRefspecs: nil}, "main")
		want := PlanLease{Mode: "implicit-remote-tracking", Expectation: "absent", ExpectedSHAFreshness: "fresh"}
		if lease != want {
			t.Fatalf("lease = %+v, want %+v: a configuration that WAS read and really maps nothing is Git's null-OID expectation, never `unknown`", lease, want)
		}
	})

	t.Run("Cell3MappedButTrackingInventoryUnreadIsAbsentAndPossiblyStale", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: false, TrackingPhase: "unread",
		}
		lease := ResolvePushLease(facts, "main")
		if lease.ExpectedRef == nil || *lease.ExpectedRef != "refs/remotes/origin/main" {
			t.Fatalf("ExpectedRef = %v, want refs/remotes/origin/main (the mapping survives an unread inventory)", lease.ExpectedRef)
		}
		want := PlanLease{
			Mode: "implicit-remote-tracking", Expectation: "absent",
			ExpectedRef: lease.ExpectedRef, ExpectedSHAFreshness: "possibly-stale",
		}
		if lease != want {
			t.Fatalf("lease = %+v, want %+v: Git falls back to the null OID when it cannot read the mapped ref, and nothing read may be called fresh", lease, want)
		}
	})

	t.Run("Cell2MappedAndReadWithTheMappedRefAbsentIsAbsentAndFresh", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "plan-point", TrackingRefs: map[string]string{},
		}
		lease := ResolvePushLease(facts, "main")
		want := PlanLease{
			Mode: "implicit-remote-tracking", Expectation: "absent",
			ExpectedRef: ref("refs/remotes/origin/main"), ExpectedSHAFreshness: "fresh",
		}
		if lease.ExpectedRef == nil || *lease.ExpectedRef != *want.ExpectedRef {
			t.Fatalf("ExpectedRef = %v, want %v (it is the ref that must not exist)", lease.ExpectedRef, want.ExpectedRef)
		}
		if lease.Expectation != want.Expectation || lease.ExpectedSHA != nil || lease.ExpectedSHAFreshness != want.ExpectedSHAFreshness {
			t.Fatalf("lease = %+v, want expectation=absent expected_sha=nil freshness=fresh: this invocation READ the absence", lease)
		}
	})

	t.Run("Cell1MappedAndReadWithAShaPresentIsShaCarryingTheCurrentValue", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "plan-point", TrackingRefs: map[string]string{"main": "deadbeef"},
		}
		lease := ResolvePushLease(facts, "main")
		if lease.Expectation != "sha" {
			t.Fatalf("Expectation = %q, want sha", lease.Expectation)
		}
		if lease.ExpectedSHA == nil || *lease.ExpectedSHA != "deadbeef" {
			t.Fatalf("ExpectedSHA = %v, want deadbeef", lease.ExpectedSHA)
		}
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale: a plan-point read refreshed nothing", lease.ExpectedSHAFreshness)
		}
	})

	t.Run("FreshnessIsFreshOnlyWhenAllThreeConditionsHold", func(t *testing.T) {
		full := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "post-fetch", FetchedThisRun: true,
			TrackingRefs: map[string]string{"main": "sha"},
		}
		if lease := ResolvePushLease(full, "main"); lease.ExpectedSHAFreshness != "fresh" {
			t.Fatalf("Freshness = %q, want fresh when TrackingReadOK && phase=post-fetch && FetchedThisRun", lease.ExpectedSHAFreshness)
		}

		notFetched := full
		notFetched.FetchedThisRun = false
		if lease := ResolvePushLease(notFetched, "main"); lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale when FetchedThisRun is false", lease.ExpectedSHAFreshness)
		}

		wrongPhase := full
		wrongPhase.TrackingPhase = "pre-fetch"
		if lease := ResolvePushLease(wrongPhase, "main"); lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale when phase is not post-fetch", lease.ExpectedSHAFreshness)
		}

		// A tracking read that did not happen is cell 3, whose OWN freshness
		// is possibly-stale — and whose expectation is `absent`, never the
		// `sha` the (unread) map still nominally contains.
		notRead := full
		notRead.TrackingReadOK = false
		notRead.TrackingPhase = "unread"
		lease := ResolvePushLease(notRead, "main")
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale when TrackingReadOK is false", lease.ExpectedSHAFreshness)
		}
		if lease.Expectation != "absent" || lease.ExpectedSHA != nil {
			t.Fatalf("lease = %+v, want the cell-3 absent/null pair", lease)
		}
	})

	t.Run("NegativeRefspecMatchForcesPossiblyStaleEvenWhenEveryFreshnessConditionOtherwiseHolds", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true,
			RemoteName:    "origin",
			FetchRefspecs: []PlanRefspec{
				{Src: "refs/heads/main", Negative: true},
				wildcardRefspec,
			},
			TrackingReadOK: true, TrackingPhase: "post-fetch", FetchedThisRun: true,
			TrackingRefs: map[string]string{"main": "sha"},
		}
		lease := ResolvePushLease(facts, "main")
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale: a negative refspec match must override every fresh condition", lease.ExpectedSHAFreshness)
		}
		// The negative refspec must not itself prevent the positive
		// wildcard rung below it from still mapping the branch, and the
		// mapped ref and its current value both survive.
		if lease.Expectation != "sha" {
			t.Fatalf("Expectation = %q, want sha (the negative match only affects freshness, not the mapping/expectation itself)", lease.Expectation)
		}
		if lease.ExpectedRef == nil || *lease.ExpectedRef != "refs/remotes/origin/main" {
			t.Fatalf("ExpectedRef = %v, want the mapped ref refs/remotes/origin/main", lease.ExpectedRef)
		}
		if lease.ExpectedSHA == nil || *lease.ExpectedSHA != "sha" {
			t.Fatalf("ExpectedSHA = %v, want the tracking ref's current value", lease.ExpectedSHA)
		}
	})

	t.Run("NegativeRefspecAlsoForcesPossiblyStaleOnTheUnmappedAndAbsentCells", func(t *testing.T) {
		// Cell 4 under a negative match: nothing maps, so the expectation is
		// still `absent`, but no fetch can ever refresh what it names.
		unmapped := ResolvePushLease(PlanPushRemoteFacts{
			MappingReadOK: true,
			FetchRefspecs: []PlanRefspec{{Src: "refs/heads/main", Negative: true}},
		}, "main")
		if unmapped.Expectation != "absent" || unmapped.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("lease = %+v, want absent/possibly-stale", unmapped)
		}

		// Cell 2 under a negative match.
		absent := ResolvePushLease(PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin",
			FetchRefspecs:  []PlanRefspec{{Src: "refs/heads/main", Negative: true}, wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "post-fetch", FetchedThisRun: true,
			TrackingRefs: map[string]string{},
		}, "main")
		if absent.Expectation != "absent" || absent.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("lease = %+v, want absent/possibly-stale", absent)
		}
	})

	t.Run("FirstPositiveMatchWinsWhenMultiplePositiveRefspecsCouldMap", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true,
			FetchRefspecs: []PlanRefspec{
				{Src: "refs/heads/main", Dst: "refs/remotes/origin/pinned-main"},
				wildcardRefspec,
			},
		}
		lease := ResolvePushLease(facts, "main")
		if lease.ExpectedRef == nil || *lease.ExpectedRef != "refs/remotes/origin/pinned-main" {
			t.Fatalf("ExpectedRef = %v, want the FIRST positive match's mapping, refs/remotes/origin/pinned-main", lease.ExpectedRef)
		}
	})
}

func TestRebasePlanner_PushTargets(t *testing.T) {
	t.Run("NoIntentYieldsANonNilEmptySlice", func(t *testing.T) {
		got := PushTargets(PlanPushRequest{Intent: false})
		if got == nil || len(got) != 0 {
			t.Fatalf("got = %v, want a non-nil empty slice", got)
		}
	})

	t.Run("FiltersToRemainingAndNotYetPushed", func(t *testing.T) {
		req := PlanPushRequest{
			Intent: true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{
				{Name: "a", GitBranch: "a"},
				{Name: "b", GitBranch: "b"},
				{Name: "c", GitBranch: "c"},
			}},
			Remaining:     []string{"a", "b"}, // c is not remaining
			AlreadyPushed: map[string]bool{"b": true},
		}
		got := PushTargets(req)
		if len(got) != 1 || got[0].GitBranch != "a" {
			t.Fatalf("got = %+v, want exactly one target for entry a", got)
		}
	})

	t.Run("FixedFieldsAndRefShapeAndCheckoutModeClearsRepo", func(t *testing.T) {
		req := PlanPushRequest{
			Mode:      ModeCheckout,
			Scope:     "one",
			Intent:    true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{{Name: "a", GitBranch: "feature-a", Repo: "sub"}}},
			Remaining: []string{"a"},
		}
		got := PushTargets(req)
		if len(got) != 1 {
			t.Fatalf("len = %d, want 1", len(got))
		}
		tgt := got[0]
		if tgt.Repo != "" {
			t.Fatalf("Repo = %q, want empty: checkout mode always clears push.targets[].repo", tgt.Repo)
		}
		if tgt.Remote != "origin" || tgt.Ref != "refs/heads/feature-a" || tgt.Force != "with-lease" {
			t.Fatalf("tgt = %+v, want Remote=origin Ref=refs/heads/feature-a Force=with-lease", tgt)
		}
		if tgt.Scope != "one" {
			t.Fatalf("Scope = %q, want one (passed through from the request)", tgt.Scope)
		}
	})

	t.Run("ExternalModePreservesTheEntryRepoToken", func(t *testing.T) {
		req := PlanPushRequest{
			Mode:      ModeExternal,
			Intent:    true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{{Name: "a", GitBranch: "feature-a", Repo: "sub"}}},
			Remaining: []string{"a"},
		}
		got := PushTargets(req)
		if len(got) != 1 || got[0].Repo != "sub" {
			t.Fatalf("got = %+v, want Repo=sub preserved for external mode", got)
		}
	})

	t.Run("ContextIDAndRepoRootResolveOnlyWhenBothLookupsSucceed", func(t *testing.T) {
		cid := "context-1"
		req := PlanPushRequest{
			Intent:    true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{{Name: "a", GitBranch: "a", Repo: ""}, {Name: "b", GitBranch: "b", Repo: "missing-remote-entry"}, {Name: "c", GitBranch: "c", Repo: "dangling-context"}}},
			Remaining: []string{"a", "b", "c"},
			Facts: PlanPushFacts{
				Remotes: map[string]PlanPushRemoteFacts{
					"":                 {ContextID: &cid},
					"dangling-context": {ContextID: strp("no-such-identity")},
				},
				Identities:      PlanContextIdentities{cid: {ContextID: cid, RepoRoot: "/repo/root"}},
				Materialization: map[string]string{"": "materialized"},
			},
		}
		got := PushTargets(req)
		byName := map[string]PlanPushTarget{}
		for _, tgt := range got {
			byName[tgt.GitBranch] = tgt
		}
		if a := byName["a"]; a.ContextID == nil || *a.ContextID != cid || a.RepoRoot == nil || *a.RepoRoot != "/repo/root" {
			t.Fatalf("a = %+v, want a resolved ContextID/RepoRoot", a)
		}
		if a := byName["a"]; a.Materialization != "materialized" {
			t.Fatalf("a.Materialization = %q, want materialized", a.Materialization)
		}
		if b := byName["b"]; b.ContextID != nil || b.RepoRoot != nil {
			t.Fatalf("b = %+v, want nil ContextID/RepoRoot: repo token has no Remotes entry at all", b)
		}
		if c := byName["c"]; c.ContextID != nil || c.RepoRoot != nil {
			t.Fatalf("c = %+v, want nil ContextID/RepoRoot: the ContextID it names has no Identities entry", c)
		}
	})

	t.Run("SortsByContextIDNilFirstThenAscendingThenGitBranchAscendingWithinTies", func(t *testing.T) {
		cidZ, cidA := "zzz", "aaa"
		req := PlanPushRequest{
			Intent: true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{
				{Name: "1", GitBranch: "b-branch", Repo: "z"},
				{Name: "2", GitBranch: "a-branch", Repo: "z"}, // same ContextID as 1: tie-break by GitBranch
				{Name: "3", GitBranch: "c-branch", Repo: "a"},
				{Name: "4", GitBranch: "d-branch", Repo: "no-remote-entry"}, // nil ContextID: sorts first
			}},
			Remaining: []string{"1", "2", "3", "4"},
			Facts: PlanPushFacts{
				Remotes: map[string]PlanPushRemoteFacts{
					"z": {ContextID: &cidZ},
					"a": {ContextID: &cidA},
				},
				Identities: PlanContextIdentities{
					cidZ: {ContextID: cidZ},
					cidA: {ContextID: cidA},
				},
			},
		}
		got := PushTargets(req)
		var order []string
		for _, tgt := range got {
			order = append(order, tgt.GitBranch)
		}
		want := []string{"d-branch", "c-branch", "a-branch", "b-branch"}
		if !stringSlicesEqual(order, want) {
			t.Fatalf("order = %v, want %v (nil ContextID first, then ascending ContextID, then ascending GitBranch within a tie)", order, want)
		}
	})
}

// ---------------------------------------------------------------------------
// §23.3 — TopoSort's 20,000-iteration randomized ordering test.
// ---------------------------------------------------------------------------

// topoComponents is the fixture the randomized test sorts: THREE disjoint
// linear chains (components). Each chain forces its own internal order by
// dependency alone — no siblings, so no intra-component ambiguity exists —
// which is what makes "only INTER-component interleaving may vary" an exact,
// checkable claim rather than a hedge.
func topoComponents() [][]string {
	return [][]string{
		{"a0", "a1", "a2", "a3"},
		{"b0", "b1", "b2"},
		{"c0", "c1", "c2", "c3", "c4"},
	}
}

// topoFixtureEntries builds the flat StackEntry list for topoComponents,
// where each chain's first element is rooted on an UNTRACKED base (so it has
// in-degree 0) and every later element is based on its predecessor.
func topoFixtureEntries() []StackEntry {
	var out []StackEntry
	for _, chain := range topoComponents() {
		for i, name := range chain {
			base := "main"
			if i > 0 {
				base = chain[i-1]
			}
			out = append(out, StackEntry{Name: name, Base: base})
		}
	}
	return out
}

// TestRebasePlanner_TopoSortRandomizedOrderingIsComponentStable is §23.3's
// 20,000-iteration randomized ordering test. Every iteration shuffles the
// INPUT order and asserts four things about the result:
//
//  1. it is a real topological order — every entry whose base is tracked
//     appears strictly after that base;
//  2. it is a permutation of the input — same names, same count, no
//     duplicates and no invention;
//  3. the relative order WITHIN each component is exactly the chain order,
//     invariant across every iteration; and
//  4. the ONLY thing that varies is how the components interleave, which is
//     asserted to really vary (at least two distinct interleavings are
//     observed) so the test cannot pass by the sort being accidentally
//     input-order-stable.
func TestRebasePlanner_TopoSortRandomizedOrderingIsComponentStable(t *testing.T) {
	const iterations = 20000

	entries := topoFixtureEntries()
	componentOf := map[string]int{}
	indexInComponent := map[string]int{}
	for c, chain := range topoComponents() {
		for i, name := range chain {
			componentOf[name] = c
			indexInComponent[name] = i
		}
	}

	rng := rand.New(rand.NewSource(20000))
	interleavings := map[string]bool{}

	for iter := 0; iter < iterations; iter++ {
		shuffled := append([]StackEntry(nil), entries...)
		rng.Shuffle(len(shuffled), func(i, j int) { shuffled[i], shuffled[j] = shuffled[j], shuffled[i] })

		sorted, err := TopoSort(Stack{Branches: shuffled})
		if err != nil {
			t.Fatalf("iteration %d: TopoSort: %v", iter, err)
		}
		if len(sorted) != len(entries) {
			t.Fatalf("iteration %d: sorted %d entries, want %d", iter, len(sorted), len(entries))
		}

		position := make(map[string]int, len(sorted))
		lastSeen := map[int]int{}
		var signature []byte
		for pos, e := range sorted {
			if _, dup := position[e.Name]; dup {
				t.Fatalf("iteration %d: %q appears twice", iter, e.Name)
			}
			position[e.Name] = pos

			c, known := componentOf[e.Name]
			if !known {
				t.Fatalf("iteration %d: TopoSort invented the entry %q", iter, e.Name)
			}
			// (3) intra-component order: this entry must be exactly the next
			// one of its own chain.
			want := 0
			if seen, ok := lastSeen[c]; ok {
				want = seen + 1
			}
			if got := indexInComponent[e.Name]; got != want {
				t.Fatalf("iteration %d: %q is index %d of component %d but appeared where index %d was due — intra-component order must never vary",
					iter, e.Name, got, c, want)
			}
			lastSeen[c] = want
			signature = append(signature, byte('0'+c))
		}
		if len(position) != len(entries) {
			t.Fatalf("iteration %d: result is not a permutation of the input", iter)
		}
		// (1) the dependency order itself.
		for _, e := range entries {
			if basePos, tracked := position[e.Base]; tracked && basePos >= position[e.Name] {
				t.Fatalf("iteration %d: %q at %d does not follow its base %q at %d",
					iter, e.Name, position[e.Name], e.Base, basePos)
			}
		}
		interleavings[string(signature)] = true
	}

	// (4) inter-component interleaving really is the varying dimension.
	if len(interleavings) < 2 {
		t.Fatalf("observed %d distinct component interleavings over %d iterations, want at least 2: the randomization is not reaching TopoSort's own queue seeding",
			len(interleavings), iterations)
	}
}

// TestRebasePlanner_TopoSortNeverInventsAnOrderForACycle is the companion
// negative: a cyclic stack has no topological order at all, so every
// iteration of the same randomized loop must refuse rather than emit a
// partial one.
func TestRebasePlanner_TopoSortNeverInventsAnOrderForACycle(t *testing.T) {
	cyclic := []StackEntry{
		{Name: "x", Base: "z"},
		{Name: "y", Base: "x"},
		{Name: "z", Base: "y"},
	}
	rng := rand.New(rand.NewSource(3))
	for iter := 0; iter < 1000; iter++ {
		shuffled := append([]StackEntry(nil), cyclic...)
		rng.Shuffle(len(shuffled), func(i, j int) { shuffled[i], shuffled[j] = shuffled[j], shuffled[i] })
		if _, err := TopoSort(Stack{Branches: shuffled}); err == nil {
			t.Fatalf("iteration %d: a cyclic stack must refuse, never sort", iter)
		}
	}
}

package internal

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"gopkg.in/yaml.v3"
)

// ---------------------------------------------------------------------------
// sync-modes — external new-mode state (spec §8) and the one shared read-only
// external-state classifier (§11.1).
// ---------------------------------------------------------------------------

// SyncRunStateVersion is the external payload state_version.
const SyncRunStateVersion = 2

// SyncRunStateGuardedVersion is the guarded envelope state_version (either
// route), the guarded twin of SyncRunStateVersion (§13.6 rule 1).
const SyncRunStateGuardedVersion = 3

// CheckoutTransactionVersion is the checkout transaction state_version.
const CheckoutTransactionVersion = 2

// CheckoutTransactionGuardedVersion is the guarded checkout transaction
// state_version (either route), the guarded twin of CheckoutTransactionVersion
// (§13.6 rule 1).
const CheckoutTransactionGuardedVersion = 3

// SyncRunStage is the closed, exhaustive stage enum of the v2 payload.
type SyncRunStage string

const (
	SyncStageInitializing SyncRunStage = "initializing"
	SyncStageFetching     SyncRunStage = "fetching"
	SyncStageRebasing     SyncRunStage = "rebasing"
	SyncStageValidating   SyncRunStage = "validating"
	SyncStagePushing      SyncRunStage = "pushing"
	SyncStageFinalizing   SyncRunStage = "finalizing"
	SyncStageFailed       SyncRunStage = "failed"
)

// SyncRunState is the authoritative v2 payload of one new-mode external run.
type SyncRunState struct {
	StateVersion int          `yaml:"state_version"`
	Feature      string       `yaml:"feature"`
	StartedAt    string       `yaml:"started_at"`
	UpdatedAt    string       `yaml:"updated_at"`
	Marker       string       `yaml:"marker"`
	OwnerToken   string       `yaml:"owner_token"`
	Stage        SyncRunStage `yaml:"stage"`

	FetchPolicy       SyncFetchPolicy       `yaml:"fetch_policy"`
	PropagationPolicy SyncPropagationPolicy `yaml:"propagation_policy"`
	ScopeKind         SyncScopeKind         `yaml:"scope_kind"`
	ScopeSelector     string                `yaml:"scope_selector,omitempty"`

	Selected         []string `yaml:"selected"`
	Push             bool     `yaml:"push"`
	TestCommand      string   `yaml:"test_command,omitempty"`
	ValidationSource string   `yaml:"validation_source,omitempty"`

	FailedBranch string   `yaml:"failed_branch"`
	Pending      []string `yaml:"pending"`
	Completed    []string `yaml:"completed"`
	Pushed       []string `yaml:"pushed"`
	Repos        []string `yaml:"repos"`

	// Guarded envelope extension (§13.1, §13.6). Absent on every unguarded
	// payload, so an unguarded run's on-disk bytes are unchanged.
	MaxReplayPerEntry *int   `yaml:"max_replay_per_entry,omitempty"`
	MaxReplayTotal    *int   `yaml:"max_replay_total,omitempty"`
	Route             string `yaml:"route,omitempty"`
}

// Policy re-reads the frozen decision of the run.
func (s *SyncRunState) Policy() SyncRunPolicy {
	return SyncRunPolicy{
		Fetch:       s.FetchPolicy,
		Propagation: s.PropagationPolicy,
		ScopeKind:   s.ScopeKind,
		Selector:    s.ScopeSelector,
	}
}

// SyncRunGuard is the run ownership guard.
type SyncRunGuard struct {
	PID          int    `yaml:"pid"`
	Created      string `yaml:"created"`
	Token        string `yaml:"token"`
	StateVersion int    `yaml:"state_version"`
}

// SyncStepHook is the external crash-injection seam. It is nil in production
// and MUST NOT be reachable from the CLI.
var SyncStepHook func(stage SyncRunStage, index int) error

// SyncReclaimBarrier is §23.1 seam 3: a barrier between
// checkSyncRunGuardReclaimable's verdict and ReclaimSyncRunGuard's own
// compare-and-swap. It is nil in production, injects no verdict of its own,
// and its returned error (if any) aborts the reclaim exactly as a real
// failure at that point would.
var SyncReclaimBarrier func(featurePath string) error

// syncProcessAlive is the substitutable liveness predicate for the sync path.
// tws status never touches it: it injects through SyncClassifyOpts.Alive.
var syncProcessAlive = isProcessAlive

// ---------- paths ----------

// SyncRunStatePath is the v2 payload path.
func SyncRunStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.v2.yaml")
}

// SyncRunGuardPath is the run guard path.
func SyncRunGuardPath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-run.lock")
}

// ---------- payload persistence ----------

// LoadSyncRunState reads and validates the payload. It accepts state_version
// 2 (unguarded) and 3 (guarded) and rejects any other value with the shipped
// sentence shape (§13.6 rule 3).
func LoadSyncRunState(featurePath string) (*SyncRunState, error) {
	if err := syncIOFault(SyncIOReadSyncRunState, SyncRunStatePath(featurePath)); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(SyncRunStatePath(featurePath))
	if err != nil {
		return nil, err
	}
	var s SyncRunState
	if err := yaml.Unmarshal(data, &s); err != nil {
		return nil, err
	}
	if s.StateVersion != SyncRunStateVersion && s.StateVersion != SyncRunStateGuardedVersion {
		return nil, fmt.Errorf("unsupported scoped sync state version %d", s.StateVersion)
	}
	return &s, nil
}

// SaveSyncRunState writes the payload atomically at mode 0600 and refreshes
// updated_at. A non-zero StateVersion is preserved, a zero one defaults to
// SyncRunStateVersion, and any other value is refused: the birth decision of
// §13.6 rule 2 is made once by the caller and is never silently rewritten
// here.
func SaveSyncRunState(featurePath string, s *SyncRunState) error {
	if err := syncIOFault(SyncIOWriteSyncRunState, SyncRunStatePath(featurePath)); err != nil {
		return err
	}
	switch s.StateVersion {
	case 0:
		s.StateVersion = SyncRunStateVersion
	case SyncRunStateVersion, SyncRunStateGuardedVersion:
		// preserved as given
	default:
		return fmt.Errorf("unsupported scoped sync state version %d", s.StateVersion)
	}
	s.UpdatedAt = time.Now().UTC().Format(time.RFC3339)
	data, err := yaml.Marshal(s)
	if err != nil {
		return err
	}
	return atomicWriteFile(SyncRunStatePath(featurePath), data, 0600)
}

// RemoveSyncRunState removes the payload, returning any error other than
// "already gone" (§12.2c rule 2).
func RemoveSyncRunState(featurePath string) error {
	path := SyncRunStatePath(featurePath)
	if err := syncIOFault(SyncIORemoveSyncRunState, path); err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove scoped sync state %s: %w", path, err)
	}
	return nil
}

// DeleteSyncRunState removes the payload.
func DeleteSyncRunState(featurePath string) {
	_ = RemoveSyncRunState(featurePath)
}

// HasSyncRunState reports whether a payload file exists.
func HasSyncRunState(featurePath string) bool {
	_, err := os.Lstat(SyncRunStatePath(featurePath))
	return err == nil
}

// PayloadNewMode answers "is this persisted payload a new-mode run?" from the
// same three-way switch as txNewMode (§13.6 rule 4): a nil payload is never
// new-mode, an explicit route decides outright, and an absent or unknown
// route falls back to the version, so every payload a shipped binary could
// have written reproduces today's "every persisted v2 payload is new-mode"
// rule exactly.
func PayloadNewMode(payload *SyncRunState) bool {
	if payload == nil {
		return false
	}
	switch payload.Route {
	case RouteNewMode:
		return true
	case RouteLegacy:
		return false
	default:
		return payload.StateVersion >= SyncRunStateVersion
	}
}

// NewSyncRunState builds a fresh payload for one run.
func NewSyncRunState(feature, marker, token string, policy SyncRunPolicy) *SyncRunState {
	now := time.Now().UTC().Format(time.RFC3339)
	return &SyncRunState{
		StateVersion:      SyncRunStateVersion,
		Feature:           feature,
		StartedAt:         now,
		UpdatedAt:         now,
		Marker:            marker,
		OwnerToken:        token,
		Stage:             SyncStageInitializing,
		FetchPolicy:       policy.Fetch,
		PropagationPolicy: policy.Propagation,
		ScopeKind:         policy.ScopeKind,
		ScopeSelector:     policy.Selector,
		Selected:          []string{},
		Pending:           []string{},
		Completed:         []string{},
		Pushed:            []string{},
		Repos:             []string{},
	}
}

// ---------- guard ----------

// ClaimSyncRunGuard claims the run guard with O_EXCL, the same idiom as
// writeLockExclusive. It never steals a live guard and refuses a stale guard
// that still has a payload.
func ClaimSyncRunGuard(featurePath, token string) error {
	path := SyncRunGuardPath(featurePath)
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return fmt.Errorf("create sync guard directory: %w", err)
	}
	if err := writeSyncGuardExclusive(path, token); err == nil {
		return nil
	} else if !os.IsExist(err) {
		return err
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read existing sync guard: %w", err)
	}
	var guard SyncRunGuard
	if err := yaml.Unmarshal(data, &guard); err != nil {
		return fmt.Errorf("invalid sync guard; inspect %s and use --abort to recover: %w", path, err)
	}
	if guard.PID <= 0 {
		return fmt.Errorf("sync guard is being initialized or is invalid; retry or inspect %s", path)
	}
	if syncProcessAlive(guard.PID) {
		return fmt.Errorf("a scoped sync is already running for %q (pid %d, started %s); wait for it or use --continue/--abort after it exits", filepath.Base(featurePath), guard.PID, guard.Created)
	}
	if HasSyncRunState(featurePath) {
		return fmt.Errorf("stale sync guard from PID %d with existing scoped state; use --continue or --abort to recover", guard.PID)
	}
	if err := removeLockIfUnchanged(path, data); err != nil {
		return fmt.Errorf("reclaim stale sync guard: %w", err)
	}
	return writeSyncGuardExclusive(path, token)
}

// syncGuardReclaimCheck is checkSyncRunGuardReclaimable's judged result: the
// bytes it read (so a compare-and-swap stays anchored to them) and whether
// the guard was absent.
type syncGuardReclaimCheck struct {
	absent        bool
	originalBytes []byte
	guard         SyncRunGuard
}

// checkSyncRunGuardReclaimable performs the shipped read/YAML/PID checks of
// ReclaimSyncRunGuard, in order, and returns the judged bytes rather than
// acting on them: exactly one os.ReadFile, no write. ownerToken exists only
// for call-shape parity and MUST NOT affect the verdict (§12.4).
func checkSyncRunGuardReclaimable(featurePath, ownerToken string) (syncGuardReclaimCheck, error) {
	path := SyncRunGuardPath(featurePath)
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return syncGuardReclaimCheck{absent: true}, nil
	}
	if err != nil {
		return syncGuardReclaimCheck{}, fmt.Errorf("read sync guard: %w", err)
	}
	var guard SyncRunGuard
	if err := yaml.Unmarshal(data, &guard); err != nil {
		return syncGuardReclaimCheck{}, fmt.Errorf("invalid sync guard %s: %w", path, err)
	}
	if guard.PID <= 0 {
		return syncGuardReclaimCheck{}, fmt.Errorf("sync guard is being initialized or is invalid; retry or inspect %s", path)
	}
	if guard.PID != os.Getpid() && syncProcessAlive(guard.PID) {
		return syncGuardReclaimCheck{}, fmt.Errorf("sync guard held by live process %d; cannot reclaim", guard.PID)
	}
	return syncGuardReclaimCheck{originalBytes: data, guard: guard}, nil
}

// ReclaimSyncRunGuard reclaims the guard for --continue/--abort. A live guard
// owned by another process is never reclaimed.
func ReclaimSyncRunGuard(featurePath, token string) error {
	path := SyncRunGuardPath(featurePath)
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return fmt.Errorf("create sync guard directory: %w", err)
	}
	check, err := checkSyncRunGuardReclaimable(featurePath, token)
	if err != nil {
		return err
	}
	// §23.1 seam 3: the window between the reclaimability decision and the
	// compare-and-swap that acts on it. Nil in production; a test uses it to
	// let a second process really change the guard's bytes here, so the CAS
	// below is exercised against a file that moved under it.
	if SyncReclaimBarrier != nil {
		if err := SyncReclaimBarrier(featurePath); err != nil {
			return err
		}
	}
	if check.absent {
		return writeSyncGuardExclusive(path, token)
	}
	if err := removeLockIfUnchanged(path, check.originalBytes); err != nil {
		return fmt.Errorf("reclaim sync guard: %w", err)
	}
	return writeSyncGuardExclusive(path, token)
}

// ReadSyncRunGuard reads the guard read-only.
func ReadSyncRunGuard(featurePath string) (*SyncRunGuard, error) {
	data, err := os.ReadFile(SyncRunGuardPath(featurePath))
	if err != nil {
		return nil, err
	}
	var guard SyncRunGuard
	if err := yaml.Unmarshal(data, &guard); err != nil {
		return nil, err
	}
	return &guard, nil
}

// RemoveSyncRunGuard removes the guard, returning any error other than
// "already gone" (§12.2c rule 2).
func RemoveSyncRunGuard(featurePath string) error {
	path := SyncRunGuardPath(featurePath)
	if err := syncIOFault(SyncIORemoveSyncRunGuard, path); err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove sync guard %s: %w", path, err)
	}
	return nil
}

// ReleaseSyncRunGuard removes the guard. It is the last teardown step.
func ReleaseSyncRunGuard(featurePath string) {
	_ = RemoveSyncRunGuard(featurePath)
}

func writeSyncGuardExclusive(path, token string) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	guard := SyncRunGuard{
		PID:          os.Getpid(),
		Created:      time.Now().UTC().Format(time.RFC3339),
		Token:        token,
		StateVersion: SyncRunStateVersion,
	}
	data, err := yaml.Marshal(&guard)
	if err == nil {
		_, err = file.Write(data)
	}
	closeErr := file.Close()
	if err != nil {
		_ = os.Remove(path)
		return err
	}
	return closeErr
}

// ---------- stale guard release ----------

// SyncGuardReleaseReason classifies why ReleaseStaleSyncRunGuard did, or did
// not, release a guard (§12.8).
type SyncGuardReleaseReason string

const (
	SyncGuardAbsent      SyncGuardReleaseReason = "absent"
	SyncGuardReleased    SyncGuardReleaseReason = "released"
	SyncGuardSymlink     SyncGuardReleaseReason = "symlink"
	SyncGuardUnreadable  SyncGuardReleaseReason = "unreadable"
	SyncGuardInvalidPID  SyncGuardReleaseReason = "invalid-pid"
	SyncGuardSelfPID     SyncGuardReleaseReason = "self-pid"
	SyncGuardLiveForeign SyncGuardReleaseReason = "live-foreign"
	SyncGuardChanged     SyncGuardReleaseReason = "changed"
)

// SyncGuardRelease is ReleaseStaleSyncRunGuard's judged outcome; one value
// answers both "was it released" and "why/why not" (§12.8).
type SyncGuardRelease struct {
	Reason  SyncGuardReleaseReason
	Path    string
	PID     int
	Created string

	// Self is true exactly when the guard's PID equals this process's PID:
	// under Reason SyncGuardSelfPID (refused, self-owned), and under Reason
	// SyncGuardReleased when AllowSelfPID let a self-owned guard through.
	Self bool

	// Err is non-nil only for SyncGuardUnreadable and SyncGuardChanged.
	Err error
}

// SyncGuardReleaseOpts controls ReleaseStaleSyncRunGuardWith.
type SyncGuardReleaseOpts struct {
	// AllowSelfPID lets a guard whose PID equals this process's own be
	// released rather than refused with SyncGuardSelfPID.
	AllowSelfPID bool
}

// ReleaseStaleSyncRunGuard releases a stale guard with the default options: a
// self-owned guard is refused (SyncGuardSelfPID), not released.
func ReleaseStaleSyncRunGuard(featurePath string) SyncGuardRelease {
	return ReleaseStaleSyncRunGuardWith(featurePath, SyncGuardReleaseOpts{})
}

// ReleaseStaleSyncRunGuardWith judges the guard the same way
// ReclaimSyncRunGuard does, but only ever removes it — it never claims a
// fresh one in its place (§12.8). The self-PID check is evaluated BEFORE the
// general liveness check, since the current process is always "alive" and
// would otherwise be misclassified as a live foreign owner.
func ReleaseStaleSyncRunGuardWith(featurePath string, o SyncGuardReleaseOpts) SyncGuardRelease {
	path := SyncRunGuardPath(featurePath)
	info, err := os.Lstat(path)
	if os.IsNotExist(err) {
		return SyncGuardRelease{Reason: SyncGuardAbsent, Path: path}
	}
	if err != nil {
		return SyncGuardRelease{Reason: SyncGuardUnreadable, Path: path, Err: err}
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return SyncGuardRelease{Reason: SyncGuardSymlink, Path: path}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return SyncGuardRelease{Reason: SyncGuardUnreadable, Path: path, Err: err}
	}
	var guard SyncRunGuard
	if err := yaml.Unmarshal(data, &guard); err != nil {
		return SyncGuardRelease{Reason: SyncGuardUnreadable, Path: path, Err: err}
	}
	if guard.PID <= 0 {
		return SyncGuardRelease{Reason: SyncGuardInvalidPID, Path: path, Created: guard.Created}
	}
	if guard.PID == os.Getpid() {
		if !o.AllowSelfPID {
			return SyncGuardRelease{Reason: SyncGuardSelfPID, Path: path, PID: guard.PID, Created: guard.Created, Self: true}
		}
		if err := removeLockIfUnchanged(path, data); err != nil {
			return SyncGuardRelease{Reason: SyncGuardChanged, Path: path, PID: guard.PID, Created: guard.Created, Self: true, Err: err}
		}
		return SyncGuardRelease{Reason: SyncGuardReleased, Path: path, PID: guard.PID, Created: guard.Created, Self: true}
	}
	if syncProcessAlive(guard.PID) {
		return SyncGuardRelease{Reason: SyncGuardLiveForeign, Path: path, PID: guard.PID, Created: guard.Created}
	}
	if err := removeLockIfUnchanged(path, data); err != nil {
		return SyncGuardRelease{Reason: SyncGuardChanged, Path: path, PID: guard.PID, Created: guard.Created, Err: err}
	}
	return SyncGuardRelease{Reason: SyncGuardReleased, Path: path, PID: guard.PID, Created: guard.Created}
}

// ---------- marker ----------

var syncMarkerRe = regexp.MustCompile(`^tws-scoped-sync-[0-9a-f]{32}\.lock$`)

// isSyncMarker recognises a per-run sentinel marker. It is used ONLY for
// classification and has exactly one caller, ClassifyExternalSyncState.
func isSyncMarker(s string) bool { return syncMarkerRe.MatchString(s) }

// ---------- the shared classifier ----------

// SyncStateCell is one cell of the §8.6 matrix, 1-12.
type SyncStateCell int

// SyncExternalState is the decoded, read-only view of a feature's external
// sync state. It performs no mutation, takes no guard, and repairs nothing.
type SyncExternalState struct {
	Cell       SyncStateCell
	Legacy     *SyncState
	LegacyErr  error
	Marker     string
	Payload    *SyncRunState
	PayloadErr error
	Guard      *SyncRunGuard
	GuardLive  bool
	GuardErr   error

	// Symlink facts, recorded from the single os.Lstat this classifier performs
	// per consulted path. They are facts, not policy: the classifier never
	// refuses, and package cli applies I18 from these fields without
	// re-Lstat-ing anything.
	LegacyPath     string
	PayloadPath    string
	GuardPath      string
	LegacySymlink  bool
	PayloadSymlink bool
	GuardSymlink   bool
}

// SyncClassifyOpts controls only when the guard file is opened and how liveness
// is decided. Neither changes the returned cell: the guard is precedence and
// context, not an axis.
type SyncClassifyOpts struct {
	AlwaysReadGuard bool
	Alive           func(pid int) bool
}

type legacyKind int

const (
	legacyAbsent legacyKind = iota
	legacySentinel
	legacyReal
	legacyInvalid
)

type payloadKind int

const (
	payloadAbsent payloadKind = iota
	payloadValid
	payloadUnreadable
)

// ClassifyExternalSyncState reads the legacy path, the payload, and (per opts)
// the guard, and returns the §8.6 cell plus every decoded value. It is
// read-only and never returns an error for "absent"; absence is expressed by
// the cell.
func ClassifyExternalSyncState(featurePath string, opts SyncClassifyOpts) SyncExternalState {
	st := SyncExternalState{
		LegacyPath:  SyncStatePath(featurePath),
		PayloadPath: SyncRunStatePath(featurePath),
		GuardPath:   SyncRunGuardPath(featurePath),
	}
	alive := opts.Alive
	if alive == nil {
		alive = syncProcessAlive
	}

	// a. legacy path — exactly one Lstat, then today's follow/read.
	lk := legacyAbsent
	if info, err := os.Lstat(st.LegacyPath); err == nil {
		st.LegacySymlink = info.Mode()&os.ModeSymlink != 0
		state, loadErr := LoadSyncState(featurePath)
		switch {
		case loadErr != nil || state == nil:
			lk = legacyInvalid
			st.LegacyErr = loadErr
			if st.LegacyErr == nil {
				st.LegacyErr = fmt.Errorf("empty sync state document")
			}
		case isSyncMarker(state.FailedBranch):
			lk = legacySentinel
			st.Legacy = state
			st.Marker = state.FailedBranch
		default:
			lk = legacyReal
			st.Legacy = state
		}
	}

	// b. payload — the single added ordinary runtime-state-path read. A
	// symlink is never followed, never read, and never trusted as content.
	pk := payloadAbsent
	if info, err := os.Lstat(st.PayloadPath); err == nil {
		if info.Mode()&os.ModeSymlink != 0 {
			st.PayloadSymlink = true
			pk = payloadUnreadable
			st.PayloadErr = fmt.Errorf("refusing to follow symlink at %s", st.PayloadPath)
		} else {
			payload, loadErr := LoadSyncRunState(featurePath)
			if loadErr != nil || payload == nil {
				pk = payloadUnreadable
				st.PayloadErr = loadErr
				if st.PayloadErr == nil {
					st.PayloadErr = fmt.Errorf("empty scoped sync state document")
				}
			} else {
				pk = payloadValid
				st.Payload = payload
			}
		}
	}

	// c. guard — read only when the run is a new-mode run, or the legacy file
	// decoded to a sentinel, or a payload was found.
	if opts.AlwaysReadGuard || lk == legacySentinel || pk != payloadAbsent {
		if info, err := os.Lstat(st.GuardPath); err == nil {
			if info.Mode()&os.ModeSymlink != 0 {
				st.GuardSymlink = true
				st.GuardErr = fmt.Errorf("refusing to follow symlink at %s", st.GuardPath)
			} else {
				guard, readErr := ReadSyncRunGuard(featurePath)
				if readErr != nil || guard == nil {
					st.GuardErr = readErr
					if st.GuardErr == nil {
						st.GuardErr = fmt.Errorf("empty sync guard document")
					}
				} else {
					st.Guard = guard
					st.GuardLive = guard.PID > 0 && alive(guard.PID)
					if st.GuardLive && st.Payload != nil && st.Payload.OwnerToken != "" && guard.Token != st.Payload.OwnerToken {
						st.GuardLive = false
					}
				}
			}
		}
	}

	st.Cell = syncStateCell(lk, pk)
	return st
}

// syncStateCell maps the two disk axes onto the 12-cell matrix of §8.6.
func syncStateCell(lk legacyKind, pk payloadKind) SyncStateCell {
	base := map[legacyKind]int{legacyAbsent: 1, legacySentinel: 4, legacyReal: 7, legacyInvalid: 10}[lk]
	return SyncStateCell(base + int(pk))
}

// GuardForeign reports a guard whose token does not match the payload's.
func (s SyncExternalState) GuardForeign() bool {
	return s.Guard != nil && s.Payload != nil && s.Payload.OwnerToken != "" && s.Guard.Token != s.Payload.OwnerToken
}

// HasGuardFile reports whether a guard file exists at all (readable or not).
func (s SyncExternalState) HasGuardFile() bool {
	return s.Guard != nil || s.GuardErr != nil || s.GuardSymlink
}

package internal

import (
	"fmt"
	"sort"
)

// ---------------------------------------------------------------------------
// sync-modes — the shared selector and plan model (spec §5).
//
// One model, one resolution function, shared by both workspace modes. There is
// no second topological sort, no second descendant walker, no second parent
// lookup, and no second ancestry rule.
// ---------------------------------------------------------------------------

// SyncFetchPolicy is axis F.
type SyncFetchPolicy string

const (
	SyncFetchEnabled  SyncFetchPolicy = "fetch"
	SyncFetchDisabled SyncFetchPolicy = "no-fetch"
)

// SyncPropagationPolicy is axis P.
type SyncPropagationPolicy string

const (
	SyncPropagationFull      SyncPropagationPolicy = "full"
	SyncPropagationLocalOnly SyncPropagationPolicy = "local-only"
)

// SyncScopeKind is axis S.
type SyncScopeKind string

const (
	SyncScopeAll     SyncScopeKind = "all"
	SyncScopeOne     SyncScopeKind = "one"
	SyncScopeSubtree SyncScopeKind = "subtree"
)

// SyncRunPolicy is the frozen decision of one run. It is persisted verbatim.
type SyncRunPolicy struct {
	Fetch       SyncFetchPolicy       `yaml:"fetch_policy"`
	Propagation SyncPropagationPolicy `yaml:"propagation_policy"`
	ScopeKind   SyncScopeKind         `yaml:"scope_kind"`
	Selector    string                `yaml:"scope_selector,omitempty"` // logical StackEntry.Name
}

// SyncSelectionRole classifies one selected entry.
type SyncSelectionRole string

const (
	// SyncRoleAnchor: base is a literal ref, empty, or a stack entry in a
	// different repo. Never rebased under local-only.
	SyncRoleAnchor SyncSelectionRole = "anchor"
	// SyncRolePropagated: base names another stack entry in the same repo.
	SyncRolePropagated SyncSelectionRole = "propagated"
)

// SyncSelectedEntry is one resolved member of the selection, in the order
// TopoSort returned (parent before child; sibling order unspecified, §3.7).
//
// It deliberately carries no LastBaseSHA: no executor may reconstruct
// StackEntry values from the selection, because that would silently drop
// LastBaseSHA and destroy the amend-aware `--onto <base> <LastBaseSHA>` replay.
type SyncSelectedEntry struct {
	Name       string
	GitBranch  string
	Repo       string
	Base       string
	Role       SyncSelectionRole
	ParentName string
	Archived   bool
}

// SyncSelection is the whole resolved plan-independent selection.
type SyncSelection struct {
	Policy  SyncRunPolicy
	Entries []SyncSelectedEntry
	Names   map[string]bool
	Repos   []string
}

// SyncSelectionOpts carries everything the validator needs that the policy does
// not. It is deliberately tiny and value-only: resolution stays pure.
type SyncSelectionOpts struct {
	Mode    WorkspaceMode // ModeExternal or ModeCheckout; selects the checkout-only rules
	NewMode bool          // any trigger flag was Changed; selects the new-mode-only rules
	Feature string        // resolved feature name, interpolated into the I10/I11 messages
}

// SameStackRepo is the single cross-repo predicate. An empty string names the
// default repository.
func SameStackRepo(a, b string) bool {
	if a == "" && b == "" {
		return true
	}
	return a == b
}

// IsAnchorSelection reports whether the selection holds no propagation edge at
// all, which is the local-only no-op condition (D3).
func (s SyncSelection) IsAnchorSelection() bool {
	for _, e := range s.Entries {
		if e.Role == SyncRolePropagated {
			return false
		}
	}
	return true
}

// Anchors returns the selected anchors in selection order.
func (s SyncSelection) Anchors() []SyncSelectedEntry {
	var out []SyncSelectedEntry
	for _, e := range s.Entries {
		if e.Role == SyncRoleAnchor {
			out = append(out, e)
		}
	}
	return out
}

// Role reports the role of one selected entry. Unselected names report the
// zero value, which no executor may treat as a role.
func (s SyncSelection) Role(name string) SyncSelectionRole {
	for _, e := range s.Entries {
		if e.Name == name {
			return e.Role
		}
	}
	return ""
}

// SelectedNames returns the selection's logical names in selection order. It is
// what the v2 payload persists as `selected`.
func (s SyncSelection) SelectedNames() []string {
	out := make([]string, 0, len(s.Entries))
	for _, e := range s.Entries {
		out = append(out, e.Name)
	}
	return out
}

// Scoped reports whether the run restricts the selection below the whole stack.
func (p SyncRunPolicy) Scoped() bool { return p.ScopeKind != SyncScopeAll }

// ScopeLabel renders the scope for the §3.7 header.
func (p SyncRunPolicy) ScopeLabel() string {
	switch p.ScopeKind {
	case SyncScopeOne:
		return "only:" + p.Selector
	case SyncScopeSubtree:
		return "subtree:" + p.Selector
	default:
		return string(SyncScopeAll)
	}
}

// ResolveSyncSelection is the one resolution function. It owns I10, I11, I12,
// and I13 — every selection-validity rule — and no caller re-implements,
// re-checks, or supplements them.
//
// It performs no Git command, no filesystem access, no path resolution, and no
// I/O: opts.Feature is consumed as a message value only.
func ResolveSyncSelection(stack Stack, policy SyncRunPolicy, opts SyncSelectionOpts) (SyncSelection, error) {
	sorted, err := TopoSort(stack)
	if err != nil {
		return SyncSelection{}, err
	}
	return ResolveSyncSelectionFromOrder(stack, sorted, policy, opts)
}

// ResolveSyncSelectionFromOrder is ResolveSyncSelection's body, taking the
// already-sorted order so a caller that already holds this invocation's one
// TopoSort result never sorts a second time. It is otherwise byte-identical
// to ResolveSyncSelection, including every error string.
func ResolveSyncSelectionFromOrder(stack Stack, order []StackEntry, policy SyncRunPolicy, opts SyncSelectionOpts) (SyncSelection, error) {
	members := make(map[string]bool, len(order))
	switch policy.ScopeKind {
	case SyncScopeAll:
		for _, e := range order {
			members[e.Name] = true
		}
	case SyncScopeOne:
		if !HasBranch(stack, policy.Selector) {
			return SyncSelection{}, unknownStackEntryError(policy.Selector, opts.Feature)
		}
		members[policy.Selector] = true
	case SyncScopeSubtree:
		if !HasBranch(stack, policy.Selector) {
			return SyncSelection{}, unknownStackEntryError(policy.Selector, opts.Feature)
		}
		members[policy.Selector] = true
		for name := range Descendants(stack, policy.Selector) {
			members[name] = true
		}
	default:
		return SyncSelection{}, fmt.Errorf("unknown sync scope %q", policy.ScopeKind)
	}

	if policy.ScopeKind != SyncScopeAll {
		if GetBranch(stack, policy.Selector).Archived {
			return SyncSelection{}, archivedStackEntryError(policy.Selector, opts.Feature)
		}
	}

	sel := SyncSelection{Policy: policy, Names: make(map[string]bool, len(members))}
	repoSet := make(map[string]bool)
	for _, entry := range order {
		if !members[entry.Name] {
			continue
		}
		selected := SyncSelectedEntry{
			Name:      entry.Name,
			GitBranch: entry.GitBranch(),
			Repo:      entry.Repo,
			Base:      entry.Base,
			Archived:  entry.Archived,
			Role:      SyncRoleAnchor,
		}
		if parent := GetBranch(stack, entry.Base); parent.Name != "" && SameStackRepo(parent.Repo, entry.Repo) {
			selected.Role = SyncRolePropagated
			selected.ParentName = parent.Name
		}
		sel.Entries = append(sel.Entries, selected)
		sel.Names[entry.Name] = true
		repoSet[entry.Repo] = true
	}

	if opts.Mode == ModeCheckout {
		for _, e := range sel.Entries {
			if !SameStackRepo(e.Repo, "") {
				return SyncSelection{}, fmt.Errorf("stack entry %q belongs to repository %q; checkout sync is single-repository (cross-repo-unsupported)", e.Name, e.Repo)
			}
		}
	}

	if opts.NewMode {
		seen := make(map[string]string, len(sel.Entries))
		for _, e := range sel.Entries {
			if first, ok := seen[e.GitBranch]; ok {
				return SyncSelection{}, fmt.Errorf("stack entries %q and %q share Git branch %q; select one of them with --only", first, e.Name, e.GitBranch)
			}
			seen[e.GitBranch] = e.Name
		}
	}

	for repo := range repoSet {
		sel.Repos = append(sel.Repos, repo)
	}
	sort.Strings(sel.Repos)
	return sel, nil
}

// unknownStackEntryError is the single I10 format string.
func unknownStackEntryError(selector, feature string) error {
	return fmt.Errorf("unknown stack entry %q in feature %q; run: tws stack status %s", selector, feature, feature)
}

// archivedStackEntryError is the single I11 format string.
func archivedStackEntryError(selector, feature string) error {
	return fmt.Errorf("stack entry %q is archived; restore it with: tws new %s %s", selector, feature, selector)
}

package internal

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

type SyncState struct {
	StartedAt    string   `yaml:"started_at"`
	FailedBranch string   `yaml:"failed_branch"`
	Pending      []string `yaml:"pending"`
	Completed    []string `yaml:"completed"`
	Skipped      []string `yaml:"skipped"`
}

func SyncStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.yaml")
}

func LoadSyncState(featurePath string) (*SyncState, error) {
	if err := syncIOFault(SyncIOReadSyncState, SyncStatePath(featurePath)); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil {
		return nil, err
	}
	var s SyncState
	if err := yaml.Unmarshal(data, &s); err != nil {
		return nil, err
	}
	return &s, nil
}

func SaveSyncState(featurePath string, s *SyncState) error {
	data, err := yaml.Marshal(s)
	if err != nil {
		return err
	}
	return atomicWriteFile(SyncStatePath(featurePath), data, 0644)
}

// RemoveSyncState removes the legacy state/sentinel file, returning any error
// other than "already gone" (§12.2c rule 2).
func RemoveSyncState(featurePath string) error {
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIORemoveSyncState, path); err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove sync state %s: %w", path, err)
	}
	return nil
}

func DeleteSyncState(featurePath string) {
	_ = RemoveSyncState(featurePath)
}

func HasSyncState(featurePath string) bool {
	_, err := os.Stat(SyncStatePath(featurePath))
	return err == nil
}

func NewSyncState() *SyncState {
	return &SyncState{
		StartedAt: time.Now().UTC().Format(time.RFC3339),
	}
}

// SyncStateIOFault is §23.1 item 4's injected reader/remover/restorer/writer
// seam. It is nil in production and MUST NOT be reachable from the CLI. A
// test sets it to force a NON-ErrNotExist I/O failure at a named operation
// on a named path, which is the only way to exercise the error arms of the
// state writers on a filesystem where permissions cannot be made to fail
// (root, ACLs, CI containers). Returning nil lets the real operation
// proceed.
//
// op is one of the closed labels below; path is the artefact's absolute
// path, so a fault can be scoped to exactly one file.
var SyncStateIOFault func(op, path string) error

// The closed op label domain of SyncStateIOFault.
const (
	SyncIOReadSyncState        = "read-sync-state"        // the .sync-state.yaml capture read
	SyncIOReadSyncRunState     = "read-sync-run-state"    // the payload read path
	SyncIORemoveSyncState      = "remove-sync-state"      // §12.2c rule 2 remover
	SyncIORemoveSyncRunState   = "remove-sync-run-state"  // §12.2c rule 2 remover
	SyncIORemoveSyncRunGuard   = "remove-sync-run-guard"  // §12.2c rule 2 remover
	SyncIOWriteSentinel        = "write-sentinel"         // SaveGuardedLegacySentinel
	SyncIORestoreSyncState     = "restore-sync-state"     // RestoreSyncStateBytes
	SyncIORemoveStateUnchanged = "remove-state-unchanged" // RemoveSyncStateIfUnchanged
	SyncIOWriteSyncRunState    = "write-sync-run-state"   // SaveSyncRunState
	SyncIOWriteTransaction     = "write-checkout-tx"      // SaveCheckoutTransaction
	SyncIOReloadStack          = "reload-stack"           // the JIT seam's stack.yaml reload
)

// syncIOFault consults the injected seam. It returns nil in production,
// where SyncStateIOFault is nil.
func syncIOFault(op, path string) error {
	if SyncStateIOFault == nil {
		return nil
	}
	return SyncStateIOFault(op, path)
}

// ---------- guarded legacy rollback: conditional restore/remove ----------

// ErrSyncStateChanged and ErrSyncStateHasPayload are the two distinguished
// "restored nothing" outcomes of RestoreSyncStateBytes, RemoveSyncStateIfUnchanged
// and SaveGuardedLegacySentinel: both mean the file on disk was left exactly
// as found.
var ErrSyncStateChanged = errors.New("sync state changed since it was captured")
var ErrSyncStateHasPayload = errors.New("a scoped sync payload exists beside the sync state")

// RestoreSyncStateBytes writes prior back over .sync-state.yaml through the
// shipped atomic writer, but ONLY when both preconditions hold:
//
//  1. the file's current bytes are byte-identical to expect — the exact
//     sentinel this invocation installed — so a restore can never clobber a
//     document another party wrote (ErrSyncStateChanged otherwise); and
//  2. no scoped payload exists beside it (HasSyncRunState is false), so a
//     restore can never place a REAL legacy state next to a live payload,
//     which would be classifier cell 8 (ErrSyncStateHasPayload otherwise).
//
// The result is therefore either the captured bytes or the value the file had
// before the attempt — never a partial document and never a cell-8 pair.
// len(prior) == 0 is a programming error and returns an error rather than
// truncating the file; the caller uses RemoveSyncStateIfUnchanged for the
// fresh cell, where there were no prior bytes at all. The guarded legacy
// rollback NEVER calls the unconditional RemoveSyncState.
func RestoreSyncStateBytes(featurePath string, prior, expect []byte) error {
	if len(prior) == 0 {
		return fmt.Errorf("restore sync state: refusing to write an empty prior document")
	}
	if err := syncIOFault(SyncIORestoreSyncState, SyncStatePath(featurePath)); err != nil {
		return err
	}
	current, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil || !bytes.Equal(current, expect) {
		return ErrSyncStateChanged
	}
	if HasSyncRunState(featurePath) {
		return ErrSyncStateHasPayload
	}
	return atomicWriteFile(SyncStatePath(featurePath), prior, 0644)
}

// RemoveSyncStateIfUnchanged is the fresh route's rollback counterpart of
// RestoreSyncStateBytes: it removes .sync-state.yaml only while its bytes are
// still expect AND no payload exists beside it, returning ErrSyncStateChanged
// or ErrSyncStateHasPayload otherwise and removing nothing.
func RemoveSyncStateIfUnchanged(featurePath string, expect []byte) error {
	if err := syncIOFault(SyncIORemoveStateUnchanged, SyncStatePath(featurePath)); err != nil {
		return err
	}
	current, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil || !bytes.Equal(current, expect) {
		return ErrSyncStateChanged
	}
	if HasSyncRunState(featurePath) {
		return ErrSyncStateHasPayload
	}
	return RemoveSyncState(featurePath)
}

// ---------- the guarded legacy sentinel (§13.6 rule 2c) ----------

// GuardedLegacySentinelVersion is the guarded legacy sentinel's own version.
// It is deliberately a SEPARATE constant from SyncRunStateGuardedVersion: the
// payload and the sentinel are different documents with different readers.
const GuardedLegacySentinelVersion = 3

// GuardedLegacySentinel is .sync-state.yaml as a guarded legacy run writes
// it. The shipped SyncState is embedded INLINE and written exactly as the
// shipped sentinel writes it, so a binary whose decoder ignores unknown keys
// sees a sentinel and nothing else, and fails closed on the marker in every
// cell.
type GuardedLegacySentinel struct {
	SyncState `yaml:",inline"` // started_at, failed_branch = the marker, pending/completed/
	// skipped = [], byte-for-byte the shipped sentinel shape

	GuardedStateVersion int    `yaml:"guarded_state_version"` // always 3
	Route               string `yaml:"route"`                 // always "legacy"
	Feature             string `yaml:"feature"`
	Marker              string `yaml:"marker"`      // MUST equal FailedBranch
	OwnerToken          string `yaml:"owner_token"` // the token step 2 claimed with
	CreatedAt           string `yaml:"created_at"`  // RFC3339 UTC
	WriterPID           int    `yaml:"writer_pid"`  // diagnostic only; never a verdict

	MaxReplayPerEntry *int   `yaml:"max_replay_per_entry,omitempty"` // the EFFECTIVE limits, so a
	MaxReplayTotal    *int   `yaml:"max_replay_total,omitempty"`     // persisted 0 survives
	Push              bool   `yaml:"push"`                           // provenance; the flag still wins
	TestCommand       string `yaml:"test_command,omitempty"`         // the FROZEN validation command
	ValidationSource  string `yaml:"validation_source,omitempty"`    // its provenance. There is NO
	// digest member and no validation_digest key: §15's identity is DERIVED
	// from TestCommand by whoever needs it (§13.1 rule 2, §25.3)

	Universe []string `yaml:"universe"` // the full-stack Selected list in
	// the invocation's ONE TopoSort order
	PendingIntent     []string `yaml:"pending_intent"`        // the remaining set of §13.3
	CarriedCompleted  []string `yaml:"carried_completed"`     // the prior state's Completed, verbatim
	CarriedFailed     string   `yaml:"carried_failed_branch"` // the prior state's FailedBranch
	PriorPendingCount int      `yaml:"prior_pending_count"`   // len(prior.Pending) — the number the
	// shipped resume prints (§12.3 row 7)

	PriorLegacyPresent bool   `yaml:"prior_legacy_present"`          // false on a FRESH run only
	PriorLegacySHA256  string `yaml:"prior_legacy_sha256,omitempty"` // 64-lower-hex over the bytes
	PriorLegacyBase64  string `yaml:"prior_legacy_base64,omitempty"` // std base64 of the CAPTURED
	// bytes, verbatim
}

// SaveGuardedLegacySentinel installs the sentinel at .sync-state.yaml through
// ONE conditional atomic write at the shipped 0644 mode. expect is the
// captured prior bytes; nil means "expect the path to be absent" (the fresh
// route). The write refuses — writing nothing, returning ErrSyncStateChanged
// — when the current file is not what expect says it is, so the path is
// either the old bytes/absent or the complete sentinel, never anything
// between.
// MarshalGuardedLegacySentinel renders the exact bytes
// SaveGuardedLegacySentinel installs. Both go through this one function, so
// the setup of §13.2a can hand its rollback the precise `expect` bytes it is
// about to write without re-deriving them from a second, possibly divergent
// encoder — and without silently swallowing a marshal failure.
func MarshalGuardedLegacySentinel(s *GuardedLegacySentinel) ([]byte, error) {
	data, err := yaml.Marshal(s)
	if err != nil {
		return nil, fmt.Errorf("marshal guarded sentinel: %w", err)
	}
	return data, nil
}

func SaveGuardedLegacySentinel(featurePath string, s *GuardedLegacySentinel, expect []byte) error {
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIOWriteSentinel, path); err != nil {
		return err
	}
	current, err := os.ReadFile(path)
	switch {
	case err == nil:
		if expect == nil || !bytes.Equal(current, expect) {
			return ErrSyncStateChanged
		}
	case errors.Is(err, fs.ErrNotExist):
		if expect != nil {
			return ErrSyncStateChanged
		}
	default:
		return fmt.Errorf("read sync state: %w", err)
	}
	data, err := MarshalGuardedLegacySentinel(s)
	if err != nil {
		return err
	}
	if err := atomicWriteFile(path, data, 0644); err != nil {
		return fmt.Errorf("write sync sentinel: %w", err)
	}
	return nil
}

// GuardedLegacySentinelVerdict is the closed verdict domain of
// InspectGuardedLegacySentinel.
type GuardedLegacySentinelVerdict string

const (
	SentinelNotApplicable GuardedLegacySentinelVerdict = "not-applicable" // the zero value
	SentinelAbsent        GuardedLegacySentinelVerdict = "absent"
	SentinelNotGuarded    GuardedLegacySentinelVerdict = "not-guarded" // real legacy state, or
	// a PLAIN shipped sentinel
	SentinelValid        GuardedLegacySentinelVerdict = "valid"
	SentinelSymlink      GuardedLegacySentinelVerdict = "symlink"
	SentinelUnreadable   GuardedLegacySentinelVerdict = "unreadable"
	SentinelUnsupported  GuardedLegacySentinelVerdict = "unsupported-version"
	SentinelCorrupt      GuardedLegacySentinelVerdict = "corrupt"
	SentinelForeign      GuardedLegacySentinelVerdict = "foreign"
	SentinelHashMismatch GuardedLegacySentinelVerdict = "hash-mismatch"
)

// GuardedLegacySentinelView is the decided view. Sentinel and Prior are
// non-nil ONLY under SentinelValid, so no caller can resume from a document
// this ladder did not accept.
type GuardedLegacySentinelView struct {
	Verdict  GuardedLegacySentinelVerdict
	Path     string
	Sentinel *GuardedLegacySentinel // the decoded extension
	Prior    *SyncState             // the VERIFIED backed-up legacy state; nil when
	// PriorLegacyPresent is false
	Version int   // the raw guarded_state_version, for the unsupported sentence
	Err     error // the underlying I/O or decode error; sanitized by cli
}

// isLowerHex64 reports whether s is exactly 64 lowercase hex characters, the
// shape of a SHA-256 digest as this sentinel persists it.
func isLowerHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, r := range s {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return false
		}
	}
	return true
}

// InspectGuardedLegacySentinel performs ONE Lstat and at most ONE read of a
// regular file, follows no symlink, and applies the ordered ladder of §13.6
// rule 2c: the first failing clause decides, and only SentinelValid resumes.
// It refuses nothing and prints nothing: internal decides, cli speaks.
func InspectGuardedLegacySentinel(featurePath, feature string) GuardedLegacySentinelView {
	path := SyncStatePath(featurePath)
	view := GuardedLegacySentinelView{Path: path}

	info, err := os.Lstat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		view.Verdict = SentinelAbsent
		return view
	case err != nil:
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	case info.Mode()&os.ModeSymlink != 0:
		view.Verdict = SentinelSymlink
		return view
	case !info.Mode().IsRegular():
		view.Verdict = SentinelUnreadable
		return view
	}

	data, err := os.ReadFile(path)
	if err != nil {
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	}
	if len(data) == 0 {
		view.Verdict = SentinelUnreadable
		return view
	}
	var raw GuardedLegacySentinel
	if err := yaml.Unmarshal(data, &raw); err != nil {
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	}

	if !isSyncMarker(raw.FailedBranch) {
		view.Verdict = SentinelNotGuarded
		return view
	}
	if raw.GuardedStateVersion == 0 {
		view.Verdict = SentinelNotGuarded
		return view
	}
	if raw.GuardedStateVersion != GuardedLegacySentinelVersion {
		view.Verdict = SentinelUnsupported
		view.Version = raw.GuardedStateVersion
		return view
	}
	if raw.Route != RouteLegacy || raw.Marker != raw.FailedBranch || !isSyncMarker(raw.Marker) ||
		raw.OwnerToken == "" || raw.Feature == "" {
		view.Verdict = SentinelCorrupt
		return view
	}
	if raw.Feature != feature {
		view.Verdict = SentinelForeign
		return view
	}

	if !raw.PriorLegacyPresent {
		if raw.PriorLegacyBase64 != "" || raw.PriorLegacySHA256 != "" || raw.PriorPendingCount != 0 ||
			len(raw.CarriedCompleted) != 0 || raw.CarriedFailed != "" {
			view.Verdict = SentinelCorrupt
			return view
		}
		view.Verdict = SentinelValid
		view.Sentinel = &raw
		return view
	}

	decoded, err := base64.StdEncoding.DecodeString(raw.PriorLegacyBase64)
	if err != nil {
		view.Verdict = SentinelHashMismatch
		return view
	}
	if !isLowerHex64(raw.PriorLegacySHA256) {
		view.Verdict = SentinelHashMismatch
		return view
	}
	sum := sha256.Sum256(decoded)
	if raw.PriorLegacySHA256 != hex.EncodeToString(sum[:]) {
		view.Verdict = SentinelHashMismatch
		return view
	}

	var prior SyncState
	if err := yaml.Unmarshal(decoded, &prior); err != nil {
		view.Verdict = SentinelCorrupt
		return view
	}
	if isSyncMarker(prior.FailedBranch) {
		view.Verdict = SentinelCorrupt
		return view
	}
	if raw.PriorPendingCount != len(prior.Pending) {
		view.Verdict = SentinelCorrupt
		return view
	}

	view.Verdict = SentinelValid
	view.Sentinel = &raw
	view.Prior = &prior
	return view
}

// GuardedLegacySentinelResumable is the ONE dispatch predicate (§19.2): a
// classifier cell 4 — sentinel present, payload absent — whose sentinel this
// ladder accepted. It is evaluated on NO other cell.
func GuardedLegacySentinelResumable(st SyncExternalState, v GuardedLegacySentinelView) bool {
	return st.Cell == 4 && v.Verdict == SentinelValid
}
